/* Dialectica schools: one per school, grouped by tradition, in English and Chinese. Edit freely, then run `node scripts/check-data.mjs`. */
window.DIALECTICA = window.DIALECTICA || {};
window.DIALECTICA.schools = [
  {"id":"confucianism","tradition":"eastasia","start":-500,"end":2026,"dates":{"en":"c. 500 BCE – today","zh":"约公元前500年–今"},"name":{"en":"Confucianism","zh":"儒家"},"branches":["ethics","politics"],"idea":{"en":"People become fully humane through learning, ritual and family relationships, and good government rests on the ruler’s virtue rather than on force.","zh":"人通过学习、礼仪与人伦关系成就仁德；良好的政治依靠君主的德行，而非强力。"},"question":{"en":"How can people live well together and be governed well?","zh":"人如何才能好好相处，国家如何才能治理得好？"},"origin":{"en":"In the Spring and Autumn period the Zhou order was falling apart: lords warred with one another and the old rites had become empty show. Confucius, a minor official and teacher from the state of Lu, looked back to the early Zhou as a model and tried to restore order by cultivating persons rather than by tightening laws.","zh":"春秋时期，周代秩序日渐瓦解：诸侯相互征伐，古礼沦为空洞的排场。鲁国的小官与教师孔子以西周初年为典范，试图通过修养人格而不是加重刑罚来重建秩序。"},"reasoning":{"en":"Social order depends on people’s inner dispositions, and dispositions are formed by practice: the roles we play in the family and the rites we perform. So cultivate humaneness (ren) and ritual propriety (li) from the family outward; a ruler who is virtuous will win people over as the wind bends the grass, and punishment becomes a last resort.","zh":"社会秩序取决于人的内在品性，而品性由实践养成：家庭中的角色与日常所行的礼。因此要由家及国地培养“仁”与“礼”；君主有德，百姓自然归附，如风吹草偃，刑罚只是最后的手段。"},"claims":[{"en":"Humaneness (ren) is the highest virtue.","zh":"“仁”是最高的德行。"},{"en":"Ritual shapes character as well as expressing it.","zh":"礼不仅表达品格，也塑造品格。"},{"en":"Govern by virtue and example, not by punishment.","zh":"为政以德，以身作则，而不是靠刑罚。"}],"legacy":{"en":"From the Han dynasty onward it became the official learning of imperial China, and it shaped education, family life and the state across Korea, Japan and Vietnam.","zh":"自汉代起成为中华帝国的官方学术，并深刻塑造了朝鲜半岛、日本与越南的教育、家庭与国家制度。"},"works":[{"by":"confucius","t":{"en":"Analects (compiled by disciples)","zh":"《论语》（弟子辑录）"},"y":-400},{"by":"mencius","t":{"en":"Mencius","zh":"《孟子》"},"y":-300},{"by":"xunzi","t":{"en":"Xunzi","zh":"《荀子》"},"y":-250}],"figures":["confucius","mencius","xunzi","dong-zhongshu"],"tags":"confucius ren li junzi filial piety analects 儒家 孔子 仁 礼 君子 孝 论语","wiki":"Confucianism"},
  {"id":"mohism","tradition":"eastasia","start":-430,"end":-200,"dates":{"en":"c. 430–200 BCE","zh":"约公元前430–前200年"},"name":{"en":"Mohism","zh":"墨家"},"branches":["ethics","politics","logic"],"idea":{"en":"Care for everyone impartially, and judge every doctrine and practice by whether it benefits the people.","zh":"对所有人一视同仁地关爱，并以是否有利于百姓来衡量一切学说与做法。"},"question":{"en":"What standard tells us which practices are right?","zh":"用什么标准来判断一种做法是否正确？"},"origin":{"en":"Mozi, probably of humble artisan background, lived through war and hardship and rejected the Confucians’ graded love and costly rites such as elaborate funerals and music. His followers formed a disciplined organisation that also served as defensive military engineers for besieged states.","zh":"墨子大约出身工匠阶层，身处战乱与贫困之中，他反对儒家有差等的爱，也反对厚葬、礼乐等耗费巨大的礼制。他的门徒组成纪律严明的团体，还作为守城的军事工程师援助被围攻的国家。"},"reasoning":{"en":"Disorder arises because people care for their own family and state more than others’. If everyone cared impartially, theft and aggression would lose their point. Any doctrine should pass three tests: the precedent of the sage kings, the evidence of ordinary people’s eyes and ears, and its benefit to the people.","zh":"天下之乱，起于人人只爱自家、自国而不爱他人；若人人兼爱，偷盗与攻伐便失去意义。任何学说都要经过“三表”检验：是否合于古代圣王之事，是否有百姓耳目的实证，是否有利于国家百姓。"},"claims":[{"en":"Practise impartial care for all (jian ai).","zh":"兼爱：对所有人一视同仁。"},{"en":"Wars of aggression are unjust.","zh":"非攻：侵略战争是不义的。"},{"en":"Wasteful rites and music harm the people.","zh":"节用、节葬、非乐：奢靡礼乐有害于民。"}],"legacy":{"en":"It faded after the Qin–Han unification, but its later canons contain China’s earliest systematic logic, optics and mechanics, and it was rediscovered by reformers in the 19th and 20th centuries.","zh":"秦汉统一后渐趋湮没，但后期墨家的经说包含了中国最早系统的逻辑学、光学与力学，并在19至20世纪被改革者重新发现。"},"works":[{"by":"mozi","t":{"en":"Mozi: “Impartial Care” chapters (written down by his followers)","zh":"《墨子·兼爱》（墨家后学所记）"},"y":-400},{"by":"mozi","t":{"en":"Mozi: “Against Offensive War” chapters (written down by his followers)","zh":"《墨子·非攻》（墨家后学所记）"},"y":-400}],"figures":["mozi"],"tags":"mozi mohist impartial care universal love against war consequentialism 墨家 墨子 兼爱 非攻 节用 墨经","wiki":"Mohism"},
  {"id":"daoism","tradition":"eastasia","start":-400,"end":2026,"dates":{"en":"c. 4th c. BCE – today","zh":"约公元前4世纪–今"},"name":{"en":"Daoism","zh":"道家"},"branches":["metaphysics","ethics","politics"],"idea":{"en":"The Dao, the nameless way of all things, works without forcing; people flourish by returning to spontaneity and acting through non-action (wuwei).","zh":"道是万物无名的运行之道，它从不强为；人应回归自然，以“无为”处世，方能安顿。"},"question":{"en":"How can we live in accord with the way things naturally go?","zh":"人如何才能顺应万物自然的运行？"},"origin":{"en":"While the Warring States schools competed to offer rules for restoring order, Daoist texts questioned the whole project of names, rules and striving, which they saw as a cause of disorder. The Laozi (Daodejing) took shape over the 4th and 3rd centuries BCE, and the writings gathered under Zhuangzi’s name developed a playful, sceptical voice.","zh":"战国诸子竞相提出重建秩序的规范，道家文本却质疑名分、规范与争竞本身，认为它们正是混乱的根源。《老子》（《道德经》）约在公元前4至前3世纪成书，托名庄子的著作则发展出一种诙谐而怀疑的声音。"},"reasoning":{"en":"Every distinction we make, such as good and bad or useful and useless, depends on its opposite and on a point of view. Imposing such distinctions on the world distorts its natural course. So the sage acts without forcing, and the best ruler interferes least.","zh":"我们作出的一切区分，如善恶、有用无用，都依赖于其对立面和某个视角；把这些区分强加给世界，就扭曲了它的自然进程。所以圣人无为而为，最好的统治者干预最少。"},"claims":[{"en":"The Dao that can be spoken of is not the constant Dao.","zh":"道可道，非常道。"},{"en":"Softness and yielding overcome hardness.","zh":"柔弱胜刚强。"},{"en":"All distinctions depend on a point of view.","zh":"一切区分都取决于视角。"}],"legacy":{"en":"It shaped Chinese religion, painting, poetry, medicine and political thought, and fed Xuanxue and Chan Buddhism; the Daodejing is among the most translated books in the world.","zh":"它影响了中国的宗教、绘画、诗歌、医学与政治思想，也滋养了魏晋玄学与禅宗；《道德经》是世界上译本最多的书之一。"},"works":[{"by":"laozi","t":{"en":"Daodejing (Laozi)","zh":"《道德经》（《老子》）"},"y":-300},{"by":"zhuangzi","t":{"en":"Zhuangzi","zh":"《庄子》"},"y":-290}],"figures":["laozi","zhuangzi"],"tags":"dao tao wuwei laozi zhuangzi spontaneity nature 道家 道 无为 老子 庄子 自然 道德经","wiki":"Taoism"},
  {"id":"school-of-names","tradition":"eastasia","start":-380,"end":-250,"dates":{"en":"c. 380–250 BCE","zh":"约公元前380–前250年"},"name":{"en":"School of Names","zh":"名家"},"branches":["logic","metaphysics"],"idea":{"en":"The relation between names and reality is puzzling, and careful argument and paradox can show how language carves up the world.","zh":"名与实的关系并不简单，严密的辩论与悖论能揭示语言如何划分世界。"},"question":{"en":"How do names relate to the things they name?","zh":"名称与它所指称的事物之间是什么关系？"},"origin":{"en":"In an age of fierce debate between schools, a group of “disputers” (bianzhe) specialised in argument itself. Hui Shi, a statesman of Wei and Zhuangzi’s friend, posed paradoxes about space and time, and Gongsun Long argued that “a white horse is not a horse”.","zh":"在百家激烈论辩的时代，一批“辩者”专门研究论辩本身。魏国的政治家、庄子的朋友惠施提出关于空间与时间的悖论，公孙龙则论证“白马非马”。"},"reasoning":{"en":"A name that picks out a combination, such as “white horse”, is not identical with a name that picks out a broader kind, such as “horse”. Close analysis of terms shows that our judgements of sameness and difference depend on which aspect, and which scale, we attend to.","zh":"指称组合的名（如“白马”）与指称更宽泛类别的名（如“马”）并不等同。对名词的细致分析表明，我们关于同与异的判断，取决于所关注的方面与尺度。"},"claims":[{"en":"“A white horse is not a horse.”","zh":"“白马非马。”"},{"en":"Sameness and difference are relative to the level of comparison.","zh":"同与异取决于比较的层次（合同异）。"},{"en":"Love all things; heaven and earth are one body.","zh":"泛爱万物，天地一体也。"}],"legacy":{"en":"Dismissed for centuries as hair-splitting sophistry and quickly marginalised, it is now studied as early Chinese logic and philosophy of language.","zh":"长期被视为诡辩而迅速边缘化，如今则被当作中国早期逻辑学与语言哲学来研究。"},"works":[{"by":"gongsun-long","t":{"en":"Gongsun Longzi","zh":"《公孙龙子》"},"y":-270},{"by":null,"t":{"en":"“All Under Heaven”, chapter 33 of the Zhuangzi (by an early Han hand; preserves Hui Shi’s paradoxes)","zh":"《庄子·天下》（汉初人所作，保存惠施“历物十事”）"},"y":-180}],"figures":["hui-shi","gongsun-long"],"tags":"school of names logicians paradox white horse hui shi gongsun long 名家 辩者 白马非马 惠施 公孙龙 名实","wiki":"School of Names"},
  {"id":"legalism","tradition":"eastasia","start":-350,"end":-200,"dates":{"en":"c. 350–200 BCE","zh":"约公元前350–前200年"},"name":{"en":"Legalism","zh":"法家"},"branches":["politics"],"idea":{"en":"Order comes not from virtue but from clear public laws, impartial rewards and punishments, and the ruler’s command of power and technique.","zh":"秩序不靠德行，而靠公开明确的法律、不偏不倚的赏罚，以及君主对权势与权术的掌控。"},"question":{"en":"How can a state become rich, strong and orderly?","zh":"国家如何才能富强而有序？"},"origin":{"en":"The Warring States were fighting for survival, and reforming ministers such as Shang Yang in Qin reorganised whole states around farming, war and law. Han Feizi, a student of Xunzi, drew these ideas together shortly before Qin unified China in 221 BCE.","zh":"战国诸国为生存而战，秦国的商鞅等变法者围绕耕战与法令重组了整个国家。荀子的学生韩非在秦于公元前221年统一中国前不久，将这些思想综合为一体。"},"reasoning":{"en":"People reliably seek benefit and avoid harm, while truly virtuous people are rare. So a ruler should not wait for sages but steer ordinary people with fixed laws (fa), rewards and punishments, backed by his position of power (shi) and techniques for controlling ministers (shu).","zh":"人总是趋利避害，而真正有德之人寥寥无几。因此君主不必等待圣贤，而应以明确的“法”、赏罚来引导普通人，并以“势”（权位）和驾驭臣下的“术”作为保障。"},"claims":[{"en":"Publish laws and apply them equally to all below the ruler.","zh":"法令公开，君主之下一律平等适用。"},{"en":"Rewards and punishments steer self-interest.","zh":"以赏罚驾驭人的趋利避害之心。"},{"en":"The ruler must hold on to power and technique.","zh":"君主必须牢握权势与权术。"}],"legacy":{"en":"It guided Qin’s unification and was officially discredited after Qin’s fall, yet its administrative methods lived on inside the imperial state, often summed up as “Confucian outside, Legalist inside”.","zh":"它指导了秦的统一，秦亡后在名义上遭到贬斥，但其行政手段一直存续于帝制国家之中，常被概括为“外儒内法”。"},"works":[{"by":"shang-yang","t":{"en":"The Book of Lord Shang","zh":"《商君书》"},"y":-300},{"by":"han-feizi","t":{"en":"Han Feizi","zh":"《韩非子》"},"y":-240}],"figures":["shang-yang","han-feizi"],"tags":"legalism fa shi shu law punishment qin shang yang han fei 法家 法 势 术 商鞅 韩非 秦","wiki":"Legalism (Chinese philosophy)"},
  {"id":"xuanxue","tradition":"eastasia","start":220,"end":420,"dates":{"en":"3rd–5th c. CE","zh":"公元3–5世纪"},"name":{"en":"Xuanxue (“Profound Learning”)","zh":"玄学"},"branches":["metaphysics","ethics"],"idea":{"en":"Behind the many things lies a formless root, or, as Guo Xiang replied, things simply arise of themselves; the sage combines Confucian conduct with Daoist insight.","zh":"万物背后有一个无形的根本（“无”）；郭象则反驳说万物自生自化。圣人兼具儒家的行止与道家的洞见。"},"question":{"en":"What is the root of all things, and how does the sage live?","zh":"万物的根本是什么？圣人如何处世？"},"origin":{"en":"After the Han dynasty fell in 220, state Confucianism, with its omens and heavy commentaries, lost credibility amid political danger. Scholars turned to the “Three Profound Texts”, the Laozi, Zhuangzi and Book of Changes, and to “pure conversation” (qingtan) in search of a deeper metaphysics.","zh":"220年汉朝灭亡后，充满谶纬与繁琐章句的官方经学在政治险恶中失去公信力。士人转向“三玄”——《老子》《庄子》《周易》——并在“清谈”中寻求更深的形而上学。"},"reasoning":{"en":"Wang Bi argued that anything with a definite form cannot be the source of all forms, so the root must be formless “non-being” (wu). Guo Xiang replied that non-being cannot produce anything, so each thing “self-generates” (zisheng) and is fulfilled by following its own nature.","zh":"王弼认为，凡有确定形态之物都不能成为一切形态的来源，所以根本必然是无形的“无”。郭象反驳说，“无”不能生出任何东西，所以万物“自生”，各自顺其本性便得以圆满。"},"claims":[{"en":"Non-being is the root of being (Wang Bi).","zh":"以无为本（王弼）。"},{"en":"Things arise spontaneously of themselves (Guo Xiang).","zh":"万物自生、独化（郭象）。"},{"en":"Once the meaning is grasped, words and images can be forgotten.","zh":"得意忘言，得意忘象。"}],"legacy":{"en":"It gave Chinese thought an abstract vocabulary, such as substance and function (ti/yong) and being and non-being, used to interpret Buddhism and later taken up by the Neo-Confucians.","zh":"它为中国思想提供了“体用”“有无”等抽象概念，被用来理解佛教，后来又为宋明理学所吸收。"},"works":[{"by":"wang-bi","t":{"en":"Commentary on the Laozi","zh":"《老子注》"},"y":245},{"by":"wang-bi","t":{"en":"Commentary on the Book of Changes","zh":"《周易注》"},"y":247},{"by":"guo-xiang","t":{"en":"Commentary on the Zhuangzi","zh":"《庄子注》"},"y":300}],"figures":["wang-bi","guo-xiang"],"tags":"xuanxue neo-daoism dark learning wang bi guo xiang being non-being qingtan 玄学 魏晋 王弼 郭象 贵无 崇有 独化 清谈","wiki":"Xuanxue"},
  {"id":"chan-zen","tradition":"eastasia","start":600,"end":2026,"dates":{"en":"7th c. – today","zh":"公元7世纪–今"},"name":{"en":"Chan / Zen Buddhism","zh":"禅宗"},"branches":["religion","mind","epistemology"],"idea":{"en":"Awakening is seeing one’s own original nature directly, here and now, not something acquired through scriptures or step-by-step accumulation.","zh":"觉悟就是当下直接见到自己的本性，而不是靠经文或循序积累得来的东西。"},"question":{"en":"How does one awaken to one’s own Buddha-nature?","zh":"人如何觉悟自身的佛性？"},"origin":{"en":"Chinese Buddhists inherited Indian Mahāyāna teachings on emptiness and Buddha-nature, and read them alongside Daoist ideals of spontaneity, seeking a practice centred on meditation (chan, from Sanskrit dhyāna). From the 8th century a Southern School around Huineng stressed “sudden” awakening; in the 13th century Dōgen brought the Caodong line to Japan as Sōtō Zen.","zh":"中国佛教徒继承了印度大乘的空性与佛性学说，又与道家崇尚自然的理想相互参照，发展出以禅定（“禅”，源自梵语dhyāna）为中心的修行。8世纪起，以慧能为宗的南宗强调“顿悟”；13世纪，道元把曹洞宗传入日本，成为曹洞禅。"},"reasoning":{"en":"If all beings already have Buddha-nature and all things are empty, awakening cannot be a new possession gained by effort; it is recognising what is already so. Concepts and texts can only point at it, and practice is not a means to enlightenment but its expression.","zh":"既然众生本具佛性、诸法皆空，觉悟就不是靠努力获得的新东西，而是认出本来如此的东西。概念与经文只能指向它；修行不是通往开悟的手段，而是开悟本身的表现。"},"claims":[{"en":"Seeing one’s own nature is becoming a Buddha.","zh":"见性成佛。"},{"en":"Awakening can be sudden, not only gradual.","zh":"顿悟，而非只能渐修。"},{"en":"Practice and enlightenment are one (Dōgen).","zh":"修证一如（道元）。"}],"legacy":{"en":"It became the dominant elite Buddhism of Song China, shaped Neo-Confucian self-cultivation and Japanese arts, and drove twentieth-century Western interest in Zen.","zh":"它成为宋代中国士大夫阶层最主要的佛教，影响了理学的修身工夫与日本艺术，也引发了20世纪西方对禅的兴趣。"},"works":[{"by":"huineng","t":{"en":"Platform Sutra of the Sixth Patriarch","zh":"《六祖坛经》"},"y":780},{"by":"dogen","t":{"en":"Shōbōgenzō (Treasury of the True Dharma Eye)","zh":"《正法眼藏》"},"y":1240}],"figures":["huineng","dogen"],"tags":"chan zen buddhism huineng dogen sudden awakening buddha-nature meditation koan 禅宗 禅 慧能 道元 顿悟 佛性 坐禅 曹洞","wiki":"Chan Buddhism"},
  {"id":"neo-confucianism","tradition":"eastasia","start":1020,"end":1905,"dates":{"en":"11th c. – early 20th c.","zh":"11世纪–20世纪初"},"name":{"en":"Neo-Confucianism (Cheng–Zhu school)","zh":"理学（程朱理学）"},"branches":["metaphysics","ethics","mind"],"idea":{"en":"All things share one principle (li) expressed through material force (qi); by investigating things and cultivating the mind, a person recovers original goodness and can become a sage.","zh":"万物同具一理，借“气”而显现；通过格物与修心，人可以恢复本然之善，成为圣贤。"},"question":{"en":"How can Confucian ethics rest on a full account of cosmos and mind?","zh":"儒家伦理如何建立在对宇宙与心性的完整说明之上？"},"origin":{"en":"For centuries Buddhism and Daoism had offered sophisticated metaphysics and meditation, while Confucianism looked like mere social ethics. Song scholars such as Zhou Dunyi, Zhang Zai and the Cheng brothers built a Confucian metaphysics of their own; Zhu Xi synthesised it, and from 1313 his commentaries on the Four Books were the standard for the civil-service examinations.","zh":"数百年来，佛道两家提供了精深的形而上学与修行方法，儒学则显得只是社会伦理。周敦颐、张载、二程等宋代学者建立起儒家自己的形而上学；朱熹集其大成，自1313年起，他的《四书》注释成为科举考试的标准。"},"reasoning":{"en":"Everything has a principle that makes it what it is, and all principles are ultimately one. Human nature is that principle, so it is originally good; evil comes from turbid qi and selfish desires. By “investigating things” (gewu) and holding reverent seriousness (jing), one clarifies one’s qi and realises one’s nature.","zh":"每一事物都有使其成为自身的“理”，而万理归于一理。人性即是理，所以本然是善的；恶来自浊杂之气与私欲。通过“格物”与“主敬”，人能澄清气质，实现本性。"},"claims":[{"en":"Principle (li) and material force (qi) together make all things.","zh":"理与气共同构成万物。"},{"en":"Human nature is principle, and therefore good.","zh":"性即理，故性本善。"},{"en":"Investigate things to extend knowledge.","zh":"格物以致知。"}],"legacy":{"en":"It was the orthodoxy of late imperial China, Joseon Korea and, in part, Tokugawa Japan for some six centuries; Korean scholars refined it in debates such as the Four–Seven debate.","zh":"约六百年间，它是中国帝制晚期、朝鲜王朝以及（部分地）德川日本的正统学说；朝鲜学者在“四七之辩”等论争中进一步推进了它。"},"works":[{"by":"zhou-dunyi","t":{"en":"Explanation of the Diagram of the Supreme Ultimate","zh":"《太极图说》"},"y":1070},{"by":"zhang-zai","t":{"en":"Western Inscription","zh":"《西铭》"},"y":1070},{"by":"zhu-xi","t":{"en":"Collected Commentaries on the Four Books","zh":"《四书章句集注》"},"y":1190},{"by":"yi-hwang","t":{"en":"Ten Diagrams on Sage Learning","zh":"《圣学十图》"},"y":1568}],"figures":["zhou-dunyi","zhang-zai","cheng-hao","cheng-yi","zhu-xi","yi-hwang","yi-i"],"tags":"neo-confucianism li qi principle zhu xi cheng investigation of things four books song 理学 程朱 朱熹 二程 理 气 格物 致知 四书 宋明","wiki":"Neo-Confucianism"},
  {"id":"xinxue","tradition":"eastasia","start":1170,"end":1900,"dates":{"en":"12th – late 19th c.","zh":"12世纪–19世纪末"},"name":{"en":"School of Mind (Lu–Wang school)","zh":"心学（陆王心学）"},"branches":["mind","ethics","epistemology"],"idea":{"en":"Moral principle is not out in things but in one’s own mind; everyone has innate good knowing (liangzhi), and true knowing is inseparable from acting.","zh":"道德之理不在外物，而在自己心中；人人皆有良知，真正的知与行不可分离。"},"question":{"en":"Where is moral principle found: in things, or in the mind?","zh":"道德之理在哪里：在外物中，还是在心中？"},"origin":{"en":"Lu Jiuyuan debated Zhu Xi at Goose Lake Temple in 1175, objecting that Zhu’s step-by-step study of external things fragmented moral life. Three centuries later Wang Yangming, after failing to find principle by contemplating bamboo and then enduring exile in Guizhou, had an awakening in 1508 that the mind itself is principle.","zh":"1175年，陆九渊与朱熹在鹅湖寺论辩，批评朱熹逐一考究外物的方法使道德生活支离破碎。三百多年后，王阳明“格竹”不得其理，又被贬谪贵州龙场，于1508年悟到心即是理。"},"reasoning":{"en":"Filial piety is not found in one’s parent but in one’s own caring mind, so moral principles belong to the mind itself. Everyone already has innate good knowing; and to know the good without doing it is not yet to know it, so knowing and acting form one unity.","zh":"孝不在父母身上，而在自己关爱的心中，所以道德之理就是心本身之理。人人本有良知；知善而不行，就还不算真知，所以知与行是一体的。"},"claims":[{"en":"The mind is principle (xin ji li).","zh":"心即理。"},{"en":"Knowing and acting are one.","zh":"知行合一。"},{"en":"Extend your innate good knowing.","zh":"致良知。"}],"legacy":{"en":"It swept through late Ming China and, as Yōmeigaku, inspired activists in Japan up to the Meiji Restoration; twentieth-century New Confucians revived it.","zh":"它风行于晚明，并以“阳明学”之名在日本激励了直至明治维新的行动者；20世纪的现代新儒家又使其复兴。"},"works":[{"by":"wang-yangming","t":{"en":"Instructions for Practical Living","zh":"《传习录》"},"y":1518},{"by":"wang-yangming","t":{"en":"Inquiry on the Great Learning","zh":"《大学问》"},"y":1527}],"figures":["lu-jiuyuan","wang-yangming"],"tags":"school of mind xinxue wang yangming lu jiuyuan liangzhi innate knowledge unity of knowledge and action 心学 陆王 王阳明 陆九渊 良知 知行合一 心即理","wiki":"Lu–Wang school"},
  {"id":"kyoto","tradition":"eastasia","start":1911,"end":2026,"dates":{"en":"1911 – today","zh":"1911年至今"},"name":{"en":"Kyoto School","zh":"京都学派"},"branches":["metaphysics","religion"],"idea":{"en":"Reality is grasped not as an object but through “pure experience” and “absolute nothingness”, a field in which self and world arise together.","zh":"实在不是作为对象被把握的，而是在“纯粹经验”与“绝对无”之中被把握——自我与世界在这一场域中共同生起。"},"question":{"en":"Can Western philosophy be rethought from the Buddhist insight into nothingness?","zh":"能否从佛教关于“无”的洞见出发，重新思考西方哲学？"},"origin":{"en":"Meiji Japan absorbed Western philosophy at speed. At Kyoto Imperial University, Nishida Kitarō, a long-time Zen practitioner, set out to state Zen-inflected insights in the language of James, Bergson, Hegel and the Neo-Kantians; colleagues and students such as Tanabe Hajime and Nishitani Keiji developed and contested his ideas.","zh":"明治日本迅速吸收西方哲学。京都帝国大学的西田几多郎长期习禅，他试图用詹姆士、柏格森、黑格尔与新康德主义的语言表述带有禅意的洞见；田边元、西谷启治等同事与学生继承并质疑了他的思想。"},"reasoning":{"en":"Before the split into subject and object there is immediate “pure experience”. Whatever is determined as a being stands in some “place” (basho); the ultimate place cannot itself be a being, so it must be “absolute nothingness”, in which self and world are both located and define each other.","zh":"在主客分化之前，有直接的“纯粹经验”。凡被规定为“有”的东西，都处在某个“场所”之中；最终的场所本身不能是一个“有”，因此必然是“绝对无”，自我与世界都处于其中并相互规定。"},"claims":[{"en":"Pure experience comes before subject and object.","zh":"纯粹经验先于主客之分。"},{"en":"Absolute nothingness is the ultimate “place” of all beings.","zh":"绝对无是一切存在的最终“场所”。"},{"en":"Nihilism is overcome by passing through it to emptiness.","zh":"穿越虚无主义而达于空，方能克服虚无主义。"}],"legacy":{"en":"The first major modern non-Western school in sustained dialogue with European philosophy, it remains central to comparative philosophy and Buddhist–Christian dialogue, though some members’ wartime nationalist writings are still debated.","zh":"它是第一个与欧洲哲学持续对话的现代非西方哲学学派，至今仍是比较哲学与佛耶对话的重要资源；部分成员战时的民族主义论述至今仍有争议。"},"works":[{"by":"nishida","t":{"en":"An Inquiry into the Good","zh":"《善的研究》"},"y":1911},{"by":"tanabe","t":{"en":"Philosophy as Metanoetics","zh":"《作为忏悔道的哲学》"},"y":1946},{"by":"nishitani","t":{"en":"Religion and Nothingness","zh":"《宗教是什么》"},"y":1961}],"figures":["nishida","tanabe","nishitani"],"tags":"kyoto school nishida pure experience absolute nothingness basho emptiness nihilism zen 京都学派 西田几多郎 纯粹经验 绝对无 场所 空 虚无主义","wiki":"Kyoto School"},
  {"id":"new-confucianism","tradition":"eastasia","start":1921,"end":2026,"dates":{"en":"1920s – today","zh":"1920年代–今"},"name":{"en":"New Confucianism","zh":"现代新儒家"},"branches":["metaphysics","ethics","politics"],"idea":{"en":"Confucian moral metaphysics can be renewed in dialogue with Western philosophy and can ground a Chinese modernity that includes science and democracy.","zh":"儒家的道德形上学可以在与西方哲学的对话中获得更新，并为包含科学与民主的中国现代性奠定基础。"},"question":{"en":"Can Confucian thought survive and guide modern China?","zh":"儒家思想能否延续下去，并引导现代中国？"},"origin":{"en":"The May Fourth Movement of 1919 attacked Confucianism as the root of China’s weakness, and Western science and democracy seemed to make it obsolete. Liang Shuming, Xiong Shili and Feng Youlan responded, and after 1949 Mou Zongsan and others carried the project on in Hong Kong and Taiwan.","zh":"1919年的五四运动把儒家视为中国积弱的根源，西方的科学与民主似乎已使其过时。梁漱溟、熊十力、冯友兰对此作出回应；1949年后，牟宗三等人在香港与台湾继续推进这一事业。"},"reasoning":{"en":"Science answers questions of fact but not of value and meaning. Confucian learning of mind and nature offers a “moral metaphysics” grounded in the moral mind. So China can adopt science and democracy while keeping Confucianism as its spiritual core; Mou argued the moral mind can limit itself to make room for them.","zh":"科学能回答事实问题，却不能回答价值与意义问题；儒家的心性之学提供了以道德本心为根基的“道德形上学”。因此中国可以接纳科学与民主，同时保留儒家作为精神核心——牟宗三称之为良知的“自我坎陷”，为科学与民主开出空间。"},"claims":[{"en":"Moral experience reveals the metaphysical reality of the mind.","zh":"道德经验揭示了本心的形上实在。"},{"en":"Cultures differ in orientation, not merely in stage of development.","zh":"文化之别在于路向，而不只是发展阶段的先后。"},{"en":"Confucianism can “open out” science and democracy.","zh":"由内圣开出新外王：科学与民主。"}],"legacy":{"en":"It shaped Confucian studies in Hong Kong, Taiwan and the diaspora, notably through the 1958 Manifesto for Chinese Culture, and fed the revival of Confucianism in mainland China since the 1980s.","zh":"它塑造了香港、台湾与海外华人的儒学研究（尤以1958年的《为中国文化敬告世界人士宣言》为标志），并推动了1980年代以来中国大陆的儒学复兴。"},"works":[{"by":"liang-shuming","t":{"en":"Eastern and Western Cultures and Their Philosophies","zh":"《东西文化及其哲学》"},"y":1921},{"by":"xiong-shili","t":{"en":"New Treatise on Consciousness-Only","zh":"《新唯识论》"},"y":1932},{"by":"feng-youlan","t":{"en":"A History of Chinese Philosophy","zh":"《中国哲学史》"},"y":1934},{"by":"mou-zongsan","t":{"en":"Phenomenon and Thing-in-Itself","zh":"《现象与物自身》"},"y":1975}],"figures":["xiong-shili","liang-shuming","feng-youlan","mou-zongsan"],"tags":"new confucianism modern xiong shili mou zongsan liang shuming feng youlan moral metaphysics 现代新儒家 新儒学 熊十力 牟宗三 梁漱溟 冯友兰 道德形上学 内圣外王","wiki":"New Confucianism"},
  {"id":"upanishads","tradition":"indian","start":-800,"end":-200,"dates":{"en":"c. 800–200 BCE","zh":"约公元前800–前200年"},"name":{"en":"Vedic & Upanishadic thought","zh":"吠陀与奥义书思想"},"branches":["metaphysics","mind","religion"],"idea":{"en":"The innermost self (ātman) is one with the ultimate reality (Brahman), and knowing this frees a person from the cycle of rebirth.","zh":"人最内在的自我（阿特曼）与终极实在（梵）同一；认识到这一点，人便能摆脱轮回。"},"question":{"en":"What is the one reality behind everything, and what am I?","zh":"万物背后唯一的实在是什么？“我”又是什么？"},"origin":{"en":"Late Vedic ritual specialists began asking what gave the sacrifice its power, and some teachers turned inward, linking the order of the cosmos to breath, mind and self. In the growing towns of the Ganges plain, where wandering renouncers questioned ritual, death, rebirth (saṃsāra) and release moved to the centre of thought.","zh":"吠陀晚期的祭司开始追问：祭祀的力量究竟从何而来？一些导师把目光转向内心，把宇宙秩序与气息、心意和自我联系起来。恒河平原城镇兴起，游方的出家人质疑祭祀，死亡、轮回与解脱于是成了思想的中心。"},"reasoning":{"en":"Everything we see changes, so something must underlie the change; and the seer cannot itself be seen, so the self that knows is not any object it knows. If that knowing self is the very ground of the world, then grasping it ends the fear and bondage that come from mistaking oneself for a body.","zh":"我们所见的一切都在变化，变化背后必有某种不变者；而“能见者”本身不可被见，所以能知的自我不是它所知的任何对象。如果这能知的自我就是世界的根基，那么领悟它，便能终结因把自己当成身体而生的恐惧与束缚。"},"claims":[{"en":"Brahman is the single reality behind the many.","zh":"梵是众多事物背后唯一的实在。"},{"en":"The self is not body or mind but their inner witness.","zh":"自我不是身体或心意，而是它们内在的见证者。"},{"en":"Knowledge, not ritual alone, liberates from rebirth.","zh":"使人脱离轮回的是知识，而不只是祭祀。"}],"legacy":{"en":"The Upanishads became the scriptural foundation of Vedānta and set the shared vocabulary—self, karma, rebirth, liberation—that Buddhists and Jains also argued over.","zh":"奥义书成为吠檀多的经典根基，并确立了自我、业、轮回、解脱这套共同词汇，佛教与耆那教也正是围绕它们展开争论。"},"works":[{"by":"yajnavalkya","t":{"en":"Bṛhadāraṇyaka Upaniṣad (dialogues of Yājñavalkya)","zh":"《广林奥义书》（耶若婆佉的对话）"},"y":-700},{"by":"uddalaka","t":{"en":"Chāndogya Upaniṣad (teachings of Uddālaka)","zh":"《歌者奥义书》（乌达罗迦的教导）"},"y":-650}],"figures":["yajnavalkya","uddalaka"],"tags":"upanishad veda brahman atman tat tvam asi neti neti karma rebirth 奥义书 吠陀 梵 我 梵我一如 轮回","wiki":"Upanishads"},
  {"id":"charvaka","tradition":"indian","start":-600,"end":1400,"dates":{"en":"c. 6th c. BCE – c. 14th c. CE","zh":"约公元前6世纪–公元14世纪"},"name":{"en":"Cārvāka / Lokāyata materialism","zh":"顺世论（遮婆迦派）"},"branches":["epistemology","metaphysics","ethics"],"idea":{"en":"Only perception gives reliable knowledge, so only the material world can be affirmed: no soul survives death, and there is no karma or afterlife.","zh":"只有感知能提供可靠的知识，所以只能肯定物质世界：没有在死后延续的灵魂，也没有业报与来世。"},"question":{"en":"What can we know without trusting priests or scripture?","zh":"不依靠祭司和经典，我们能知道什么？"},"origin":{"en":"In the same ferment of wandering teachers that produced Buddhism and Jainism, some rejected Vedic ritual and the whole idea of rebirth. Their own writings are almost entirely lost; we know them mainly from opponents’ summaries, which makes every reconstruction partial.","zh":"在孕育了佛教与耆那教的那场游方思想家运动中，有一些人彻底否定了吠陀祭祀和轮回观念。他们自己的著作几乎全部失传，今天主要靠论敌的转述来了解，因此任何重建都只是局部的。"},"reasoning":{"en":"An inference needs a universal link (vyāpti) between sign and conclusion, but we can never perceive all cases, so inference cannot prove unseen things such as heaven or a surviving self. What we do perceive is matter: consciousness arises when the elements combine in a body, as intoxicating power arises from fermented ingredients.","zh":"推理需要征象与结论之间的普遍联系（遍充），但我们不可能感知到所有情形，所以推理无法证明天堂或不灭的自我这类看不见的东西。我们真正感知到的是物质：意识在诸元素组成身体时产生，就像酿酒的原料合在一起便产生醉人的力量。"},"claims":[{"en":"Perception is the only valid means of knowledge.","zh":"感知是唯一有效的认识手段。"},{"en":"Consciousness arises from matter and ends with the body.","zh":"意识产生于物质，并随身体一同消亡。"},{"en":"Rituals for the afterlife serve only those who perform them for pay.","zh":"为来世举行的祭祀只是让收钱的祭司受益。"}],"legacy":{"en":"No Cārvāka community survived, but its challenge to inference forced Nyāya, Buddhist and Vedāntic thinkers to sharpen their logic, and it is now read as India’s classic voice of materialism and scepticism.","zh":"顺世论没有留下延续的团体，但它对推理的质疑迫使正理派、佛教与吠檀多学者打磨自己的逻辑；今天它被视为印度唯物论与怀疑论的经典声音。"},"works":[{"by":"jayarashi","t":{"en":"Tattvopaplavasiṃha (The Lion that Devours All Categories)","zh":"《吞噬一切范畴之狮》"},"y":800}],"figures":["ajita","jayarashi"],"tags":"charvaka lokayata materialism skepticism perception inference vyapti 顺世论 唯物论 怀疑论 感知 推理 遍充","wiki":"Charvaka"},
  {"id":"jainism","tradition":"indian","start":-550,"end":2026,"dates":{"en":"c. 6th–5th c. BCE – today","zh":"约公元前6–前5世纪至今"},"name":{"en":"Jain philosophy","zh":"耆那教哲学"},"branches":["ethics","metaphysics","epistemology"],"idea":{"en":"Countless eternal souls are bound by karmic matter and can free themselves through non-violence, restraint and right knowledge; and reality is many-sided (anekāntavāda).","zh":"无数永恒的灵魂被业的物质束缚，可以通过不杀生、自制与正确的知识获得解脱；而实在本身是多面的（非一端论）。"},"question":{"en":"How can a soul free itself from karma without harming any life?","zh":"灵魂怎样才能在不伤害任何生命的前提下摆脱业的束缚？"},"origin":{"en":"Mahāvīra, a contemporary of the Buddha, belonged to the śramaṇa movement of renouncers who left household life and Vedic ritual behind to seek liberation through austerity. Jains regard him as the last of twenty-four ‘ford-makers’ (tīrthaṅkaras), renewing an older teaching linked with Pārśva.","zh":"大雄与佛陀同时代，属于沙门运动：这些出家人抛开家庭生活与吠陀祭祀，以苦行求解脱。耆那教徒视他为二十四位“渡津者”（祖师）中的最后一位，复兴了与巴湿伐那他相关的更古老教法。"},"reasoning":{"en":"Karma is a subtle matter that sticks to the soul whenever we act with passion, above all when we harm; so freedom means stopping new karma from flowing in and burning off the old through restraint. Because any limited viewpoint grasps only some aspects of a complex reality, claims should be qualified as true ‘from some standpoint’ (syāt)—a kind of non-violence in thought.","zh":"业是一种细微的物质，每当我们带着情欲行动、尤其是伤害生命时，它就粘附在灵魂上；因此解脱意味着阻止新业流入，并以自制烧尽旧业。又因为任何有限的视角都只能把握复杂实在的某些方面，判断应限定为“从某种观点看”（或然）成立——这也是思想上的不杀生。"},"claims":[{"en":"Every living thing, down to plants and tiny beings, has a soul.","zh":"一切生物，直到植物和微小的生命，都有灵魂。"},{"en":"Non-violence (ahiṃsā) is the highest duty.","zh":"不杀生（非暴力）是最高的义务。"},{"en":"Every statement is true only from some standpoint.","zh":"任何判断都只在某种观点下成立。"}],"legacy":{"en":"Jain ahiṃsā shaped Indian ethics and, through Gandhi’s Gujarati milieu, modern non-violent politics; its doctrine of standpoints is a distinctive contribution to the logic of perspective.","zh":"耆那教的不杀生塑造了印度伦理，并通过甘地成长的古吉拉特环境影响了现代非暴力政治；它的“观点论”是对视角逻辑的独特贡献。"},"works":[{"by":"mahavira","t":{"en":"Ācārāṅga Sūtra (teachings attributed to Mahāvīra)","zh":"《阿迦朗伽经》（归于大雄的教导）"},"y":-300},{"by":"umasvati","t":{"en":"Tattvārtha Sūtra","zh":"《谛义证得经》"},"y":400}],"figures":["mahavira","umasvati"],"tags":"jain jainism mahavira ahimsa karma jiva anekantavada syadvada tirthankara 耆那教 大雄 不杀生 非一端论 或然论 业","wiki":"Jain philosophy"},
  {"id":"buddhism","tradition":"indian","start":-450,"end":2026,"dates":{"en":"c. 5th c. BCE – today","zh":"约公元前5世纪至今"},"name":{"en":"Early Buddhism & Abhidharma","zh":"早期佛教与阿毗达磨"},"branches":["mind","ethics","metaphysics"],"idea":{"en":"Suffering comes from craving rooted in ignorance of impermanence and non-self, and it can be ended by following the Eightfold Path.","zh":"苦源于渴爱，而渴爱植根于对无常与无我的无知；遵循八正道，苦就可以止息。"},"question":{"en":"Why do we suffer, and how can suffering end?","zh":"我们为什么受苦？苦如何才能止息？"},"origin":{"en":"Siddhārtha Gautama joined the śramaṇa wanderers, tried and rejected both a comfortable life and extreme austerity, and taught a ‘middle way’. After his death his discourses were memorised and later written down; Abhidharma scholars then systematised them into analyses of momentary physical and mental events (dharmas).","zh":"乔达摩·悉达多加入沙门游方者的行列，先后尝试又放弃了安逸生活与极端苦行，转而宣讲“中道”。他去世后，弟子们背诵并在后来写下了他的教说；阿毗达磨论师又把这些教说系统化，分析为刹那生灭的身心现象（法）。"},"reasoning":{"en":"Everything we might call ‘me’—body, feeling, perception, mental formations, consciousness—is impermanent and conditioned, so none of it is a lasting self. Clinging to what cannot last produces suffering; remove the craving through ethics, meditation and insight, and the suffering it feeds ceases (nirvāṇa).","zh":"我们可能称为“我”的一切——色、受、想、行、识——都是无常的、有条件的，所以其中没有一个恒常的自我。执着于不能长久的东西就会生苦；通过戒、定、慧去除渴爱，由它滋养的苦也就止息（涅槃）。"},"claims":[{"en":"Four Noble Truths: suffering, its cause, its cessation, the path.","zh":"四圣谛：苦、集、灭、道。"},{"en":"No permanent self underlies the five aggregates.","zh":"五蕴之中没有恒常的自我（无我）。"},{"en":"All conditioned things arise dependently and pass away.","zh":"一切有为法皆依缘而生，也终将灭去。"}],"legacy":{"en":"Buddhism spread across Asia and gave rise to Madhyamaka, Yogācāra and the East Asian schools; its analysis of the self is now discussed alongside Hume and contemporary philosophy of mind.","zh":"佛教传遍亚洲，孕育了中观、唯识以及东亚诸宗；它对自我的分析，今天常与休谟和当代心灵哲学相提并论。"},"works":[{"by":"buddha","t":{"en":"Dhammapada (verses attributed to the Buddha)","zh":"《法句经》（归于佛陀的偈颂）"},"y":-250},{"by":"buddhaghosa","t":{"en":"Visuddhimagga (The Path of Purification)","zh":"《清净道论》"},"y":430}],"figures":["buddha","buddhaghosa"],"tags":"buddhism buddha dukkha anatta anatman impermanence nirvana eightfold path abhidharma dependent origination 佛教 佛陀 苦 无我 无常 涅槃 八正道 阿毗达磨 缘起","wiki":"Early Buddhism"},
  {"id":"samkhya-yoga","tradition":"indian","start":-400,"end":2026,"dates":{"en":"proto-Sāṃkhya c. 4th c. BCE; classical texts c. 4th–5th c. CE – today","zh":"早期数论约公元前4世纪；经典文本约公元4–5世纪；延续至今"},"name":{"en":"Sāṃkhya & Yoga","zh":"数论与瑜伽派"},"branches":["metaphysics","mind","religion"],"idea":{"en":"Reality has two irreducible principles—pure consciousness (puruṣa) and active matter (prakṛti)—and liberation is consciousness recognising that it was never matter.","zh":"实在有两个不可还原的本原——纯粹意识（神我）与能动的物质（自性）；解脱就是意识认清自己从来不是物质。"},"question":{"en":"How can pure consciousness be freed from the workings of nature?","zh":"纯粹意识如何才能摆脱自然的运作？"},"origin":{"en":"The habit of enumerating the constituents of the world (‘sāṃkhya’ means ‘enumeration’) grew in the later Upanishads and the Mahābhārata. Īśvarakṛṣṇa’s verses gave the classical dualist system, and Patañjali’s Yoga Sūtra paired a similar framework with a method of meditation.","zh":"列举世界构成要素的做法（“数论”即“列举”之意）在晚期奥义书和《摩诃婆罗多》中逐渐成形。自在黑的颂文确立了古典的二元论体系，帕坦伽利的《瑜伽经》则把类似的框架与一套禅修方法结合起来。"},"reasoning":{"en":"Effects already exist latently in their cause (satkāryavāda), so the whole world—including intellect and ego—unfolds from one material source made of three qualities (guṇas). But matter is unconscious and something must witness it, so there are many pure, inactive conscious selves; suffering comes from confusing the witness with the mind, and Yoga’s stilling of the mind ends the confusion.","zh":"果早已潜藏于因中（因中有果论），所以整个世界——包括觉与我慢——都从一个由三德构成的物质本原中展开。但物质没有意识，总得有东西见证它，所以存在许多纯粹而不动的意识主体；苦来自把见证者错认为心，而瑜伽止息心的波动，便终结了这种混淆。"},"claims":[{"en":"Consciousness and matter are wholly distinct.","zh":"意识与物质截然不同。"},{"en":"Intellect and ego are refined forms of matter.","zh":"觉与我慢都是物质的精微形态。"},{"en":"Yoga is the stilling of the mind’s fluctuations.","zh":"瑜伽即止息心的波动。"}],"legacy":{"en":"Its cosmology of the three guṇas shaped the Bhagavad Gītā, Āyurveda and Tantra, and Patañjali’s Yoga, through modern reinterpretations, became a worldwide practice.","zh":"它的三德宇宙论影响了《薄伽梵歌》、阿育吠陀与密教；帕坦伽利的瑜伽经过现代的重新诠释，成为风行全球的修习。"},"works":[{"by":"ishvarakrishna","t":{"en":"Sāṃkhyakārikā","zh":"《数论颂》"},"y":400},{"by":"patanjali","t":{"en":"Yoga Sūtra","zh":"《瑜伽经》"},"y":400}],"figures":["ishvarakrishna","patanjali"],"tags":"samkhya sankhya yoga purusha prakriti gunas dualism satkaryavada patanjali 数论 瑜伽 神我 自性 三德 二元论 帕坦伽利","wiki":"Samkhya"},
  {"id":"mimamsa","tradition":"indian","start":-200,"end":1800,"dates":{"en":"c. 2nd c. BCE – 18th c. CE","zh":"约公元前2世纪–公元18世纪"},"name":{"en":"Mīmāṃsā","zh":"弥曼差派"},"branches":["religion","epistemology","logic"],"idea":{"en":"The Veda is eternal and authorless, its injunctions are the only source of knowledge about duty (dharma), and any cognition is valid unless proved otherwise.","zh":"吠陀是永恒且无作者的，它的命令是关于职责（达磨）的唯一知识来源；任何认识在被推翻之前都是有效的。"},"question":{"en":"How do we know our duty, and why trust the Veda?","zh":"我们如何知道自己的职责？为什么要信任吠陀？"},"origin":{"en":"As Vedic ritual grew complex and was challenged by Buddhists and Jains, ritual specialists needed rules for interpreting the texts and a defence of their authority. Jaimini’s sūtras set out those rules; in the 7th century Kumārila Bhaṭṭa and Prabhākara turned them into a full theory of knowledge.","zh":"吠陀祭祀日益繁复，又受到佛教与耆那教的挑战，祭祀专家需要解释经文的规则，也需要为经文的权威辩护。阇弥尼的经文确立了这些规则；7世纪，鸠摩利罗与波罗跋迦罗把它们发展为完整的认识论。"},"reasoning":{"en":"Duty concerns what ought to be done and what results it brings later, which no perception can reach, so it can be known only from a text. A text with no author has no author’s errors or deceptions, and since no author of the Veda is remembered, it is authorless and reliable. And every cognition must be valid by itself (svataḥ prāmāṇya) unless defeated—otherwise we would need an endless chain of checks.","zh":"职责关乎应当做什么、以及日后会带来什么果报，这些都不是感知能触及的，因此只能从文本中得知。没有作者的文本就不会有作者的错误或欺骗；既然没有人记得吠陀的作者，它便是无作者的、可靠的。而且每个认识都必须自身有效（自量），除非被推翻——否则我们就需要一条无穷的验证链条。"},"claims":[{"en":"The Veda is eternal and authorless (apauruṣeya).","zh":"吠陀是永恒的、非人所作的。"},{"en":"Dharma is known only from Vedic injunction.","zh":"达磨只能从吠陀的命令中得知。"},{"en":"Cognitions are intrinsically valid until defeated.","zh":"认识本身有效，直到被推翻为止。"}],"legacy":{"en":"Its rules of interpretation underlie Hindu legal reasoning (dharmaśāstra) and Vedāntic exegesis, and its default trust in cognition anticipates modern debates on testimony and justification.","zh":"它的诠释规则是印度教法论（法经与法论）和吠檀多释经的基础；它对认识的“默认信任”也预示了现代关于证言与证成的讨论。"},"works":[{"by":"jaimini","t":{"en":"Mīmāṃsā Sūtra","zh":"《弥曼差经》"},"y":-200},{"by":"kumarila","t":{"en":"Ślokavārttika (Verse Commentary)","zh":"《颂释》"},"y":660}],"figures":["jaimini","kumarila"],"tags":"mimamsa purva mimamsa veda dharma ritual hermeneutics apauruseya intrinsic validity kumarila 弥曼差 前弥曼差 吠陀 达磨 祭祀 释经 自量","wiki":"Mimamsa"},
  {"id":"nyaya","tradition":"indian","start":-150,"end":1800,"dates":{"en":"c. 2nd c. BCE – 18th c. CE","zh":"约公元前2世纪–公元18世纪"},"name":{"en":"Nyāya–Vaiśeṣika","zh":"正理–胜论派"},"branches":["logic","epistemology","metaphysics"],"idea":{"en":"The world is made of real, knowable categories—substances, qualities, actions, universals—and disciplined reasoning can prove what perception alone cannot, including a creator God.","zh":"世界由真实可知的范畴构成——实体、性质、运动、共相等；严格的推理能证明单靠感知无法证明的东西，包括一位造物主。"},"question":{"en":"How can we reason correctly about what is real?","zh":"我们怎样才能正确地推论什么是真实的？"},"origin":{"en":"Vaiśeṣika began as a natural philosophy that sorted everything into categories and atoms, while Nyāya grew out of the rules of public debate. Over the first millennium CE they merged into one realist system, sharpened by long controversy with Buddhists who denied substances, universals and lasting selves.","zh":"胜论起初是一种自然哲学，把万物归入范畴与极微；正理则源于公开辩论的规则。公元第一个千年间，两者逐渐融合为一个实在论体系，并在与佛教的长期论战中磨砺成熟——佛教否认实体、共相与持久的自我。"},"reasoning":{"en":"Knowledge comes through four means—perception, inference, comparison and testimony—and an inference is sound when the reason is invariably linked (vyāpti) with what it proves, as smoke with fire. Since we really do perceive pots and cows as wholes sharing common features, the world contains real wholes, universals and enduring selves, and the ordered composition of things points to an intelligent maker.","zh":"知识来自四种量——现量、比量、譬喻量和圣言量；当理由与所证之物之间有不变的联系（遍充），如烟与火，推理就是可靠的。既然我们确实把瓶和牛感知为具有共同特征的整体，世界中就存在真实的整体、共相与持久的自我；而万物井然有序的组合，则指向一位有智慧的创造者。"},"claims":[{"en":"Four means of knowledge: perception, inference, comparison, testimony.","zh":"四种量：现量、比量、譬喻量、圣言量。"},{"en":"Everything falls under a few real categories (padārthas).","zh":"一切都可归入少数几个真实的范畴（句义）。"},{"en":"Material things are composed of indivisible atoms.","zh":"物质事物由不可分的极微构成。"}],"legacy":{"en":"It gave Indian thought its shared technical logic, and Gaṅgeśa’s Navya-Nyāya (‘new logic’) built a precise language that scholars of every school had to master.","zh":"它为印度思想提供了共同的技术性逻辑；甘吉沙开创的新正理派（“新逻辑”）发展出一套精密语言，各派学者都必须掌握。"},"works":[{"by":"kanada","t":{"en":"Vaiśeṣika Sūtra","zh":"《胜论经》"},"y":-150},{"by":"akshapada","t":{"en":"Nyāya Sūtra","zh":"《正理经》"},"y":150},{"by":"gangesha","t":{"en":"Tattvacintāmaṇi (Jewel of Reflection on Reality)","zh":"《真理如意珠》"},"y":1325}],"figures":["akshapada","kanada","gangesha"],"tags":"nyaya vaisheshika logic inference syllogism vyapti atomism categories navya-nyaya realism god 正理 胜论 逻辑 推理 五支论式 遍充 极微 句义 新正理","wiki":"Nyaya"},
  {"id":"madhyamaka","tradition":"indian","start":150,"end":2026,"dates":{"en":"c. 150 CE – today","zh":"约公元150年至今"},"name":{"en":"Madhyamaka","zh":"中观派"},"branches":["metaphysics","epistemology","logic"],"idea":{"en":"Nothing has an intrinsic nature (svabhāva), because everything arises dependently; this ‘emptiness’ is the Middle Way between believing in essences and believing in nothing.","zh":"因为一切都依缘而生，所以没有任何事物具有自性；这种“空”正是介于执有本质与执一切皆无之间的中道。"},"question":{"en":"Does anything exist by its own nature?","zh":"有任何东西是凭自身本性而存在的吗？"},"origin":{"en":"Abhidharma scholars had broken the self down into ultimate elements (dharmas), which they took to have their own nature. Nāgārjuna, drawing on the new Perfection of Wisdom (Prajñāpāramitā) sūtras, argued that this quietly reintroduced the fixation on essences the Buddha had warned against.","zh":"阿毗达磨论师把自我分解为终极的元素（法），并认为这些法各有自性。龙树依据新出现的般若经典指出，这种做法悄悄地把佛陀所警惕的“执着本质”又带了回来。"},"reasoning":{"en":"Whatever depends on causes and parts cannot have a self-standing essence, and anything with a fixed essence could never arise or change. So every thing—including the Abhidharma elements and emptiness itself—is empty: real at the level of convention, but without intrinsic existence at the ultimate level.","zh":"凡是依赖因缘与部分而成的东西，都不可能有独立自存的本质；而真有固定本质的东西，又根本不可能生起或变化。所以一切——包括阿毗达磨的“法”，乃至空本身——都是空的：在世俗层面真实，在胜义层面却没有自性。"},"claims":[{"en":"Dependent origination is emptiness.","zh":"缘起即是性空。"},{"en":"There are two truths: conventional and ultimate.","zh":"真理有二：世俗谛与胜义谛。"},{"en":"Emptiness is itself empty, not a hidden absolute.","zh":"空亦复空，它不是隐藏的绝对者。"}],"legacy":{"en":"Madhyamaka became the leading philosophy of Tibetan Buddhism and shaped East Asian schools such as Sanlun, Tiantai and Chan.","zh":"中观成为藏传佛教中最主要的哲学，并深刻影响了东亚的三论宗、天台宗和禅宗。"},"works":[{"by":"nagarjuna","t":{"en":"Mūlamadhyamakakārikā (Fundamental Verses on the Middle Way)","zh":"《中论》"},"y":200},{"by":"nagarjuna","t":{"en":"Vigrahavyāvartanī (The Dispeller of Disputes)","zh":"《回诤论》"},"y":200},{"by":"chandrakirti","t":{"en":"Prasannapadā (Clear Words)","zh":"《明句论》"},"y":630}],"figures":["nagarjuna","chandrakirti"],"tags":"madhyamaka nagarjuna emptiness sunyata svabhava two truths middle way prasangika 中观 龙树 空 性空 自性 二谛 中道 应成派","wiki":"Madhyamaka"},
  {"id":"yogacara","tradition":"indian","start":350,"end":2026,"dates":{"en":"c. 4th c. CE – today","zh":"约公元4世纪至今"},"name":{"en":"Yogācāra","zh":"瑜伽行派（唯识）"},"branches":["mind","epistemology","metaphysics"],"idea":{"en":"What we experience as an outer world is a transformation of consciousness; liberation comes from seeing through the split between perceiving subject and perceived object.","zh":"我们经验为外部世界的东西，其实是意识的变现；看破能取与所取的二分，便是解脱。"},"question":{"en":"Do we ever know objects, or only our own experience?","zh":"我们认识的究竟是外物，还是只是自己的经验？"},"origin":{"en":"Meditators noticed how much the mind shapes what appears to it, and in the 4th–5th centuries the half-brothers Asaṅga and Vasubandhu, from Gandhāra, systematised this insight. They also wanted a positive account of mind to balance what some read as Madhyamaka’s purely negative emptiness.","zh":"修行者注意到，心在很大程度上塑造了呈现给它的东西。公元4至5世纪，出身犍陀罗的无著与世亲这对同父异母兄弟把这一洞见系统化。他们也想对心给出一个正面的说明，以平衡一些人眼中中观那种纯粹否定的“空”。"},"reasoning":{"en":"In dreams we perceive places, people and even causal effects with no outer objects at all, so perception alone cannot prove a world beyond the mind. Vasubandhu adds that indivisible atoms are incoherent, so material objects cannot be built from them; it is simpler to explain experience by karmic ‘seeds’ ripening in a storehouse consciousness (ālaya-vijñāna).","zh":"梦中我们也会感知到地点、人物乃至因果作用，却并无外物，所以单凭感知无法证明心外有世界。世亲进一步论证：不可分的极微是自相矛盾的，物体不可能由它们构成；与其设想外物，不如用阿赖耶识中业的“种子”成熟来解释经验，更为简洁。"},"claims":[{"en":"Appearances are ‘mere representation’ (vijñaptimātra).","zh":"一切显现皆是“唯识”（唯了别）。"},{"en":"A storehouse consciousness carries karmic seeds.","zh":"阿赖耶识摄藏业的种子。"},{"en":"Experience has three natures: imagined, dependent, perfected.","zh":"经验有三性：遍计所执、依他起、圆成实。"}],"legacy":{"en":"Its analysis of consciousness passed to China through Xuanzang’s Weishi (Faxiang) school and to Tibet, and its theory of perception laid the ground for Dignāga’s epistemology.","zh":"它对意识的分析经玄奘的唯识宗（法相宗）传入中国，也传入西藏；它的知觉理论为陈那的量论奠定了基础。"},"works":[{"by":"asanga","t":{"en":"Mahāyānasaṃgraha (Compendium of the Mahāyāna)","zh":"《摄大乘论》"},"y":370},{"by":"vasubandhu","t":{"en":"Viṃśatikā (Twenty Verses)","zh":"《唯识二十论》"},"y":400},{"by":"vasubandhu","t":{"en":"Triṃśikā (Thirty Verses)","zh":"《唯识三十颂》"},"y":400}],"figures":["asanga","vasubandhu"],"tags":"yogacara vijnanavada mind-only consciousness alaya storehouse three natures vasubandhu asanga 瑜伽行派 唯识 阿赖耶识 种子 三性 世亲 无著 玄奘","wiki":"Yogachara"},
  {"id":"pramana","tradition":"indian","start":480,"end":1200,"dates":{"en":"c. 480–1200 CE in India; continued in Tibet","zh":"约公元480–1200年（印度）；此后延续于西藏"},"name":{"en":"Buddhist epistemology (Pramāṇa school)","zh":"佛教量论（因明）"},"branches":["epistemology","logic"],"idea":{"en":"There are only two valid means of knowledge: perception, which grasps unique particulars, and inference, which works through general concepts.","zh":"有效的认识手段只有两种：把握独特个别物的现量（感知），和借助一般概念进行的比量（推理）。"},"question":{"en":"What counts as valid knowledge, and how does sound reasoning work?","zh":"什么才算有效的知识？正确的推理如何进行？"},"origin":{"en":"Public debates between Buddhists, Nyāya logicians and Mīmāṃsakas required shared rules of proof. Dignāga, working from Yogācāra and earlier Nyāya logic, reorganised the field around valid cognition (pramāṇa); Dharmakīrti deepened it about a century later.","zh":"佛教徒、正理派逻辑学家与弥曼差派之间的公开辩论，需要一套共同的论证规则。陈那以瑜伽行派思想和此前的正理派逻辑为基础，围绕“量”（有效认识）重组了这一领域；约一个世纪后，法称又把它推向深入。"},"reasoning":{"en":"Perception is free of concepts and reaches only momentary particulars; concepts work by exclusion (apoha)—‘cow’ means ‘not non-cow’—so universals are mental constructions, not real things. A valid inference needs a reason present in the subject, present in similar cases and absent from dissimilar ones, and Dharmakīrti grounds that necessity in real relations of identity and causation.","zh":"现量不带概念，只触及刹那的个别物；概念则通过“遮遣”（apoha）起作用——“牛”的意思是“非非牛”——所以共相只是心的构造，而不是实在之物。有效的推理要求理由存在于论题之中、存在于同类事例、不存在于异类事例（因三相）；法称又把这种必然性建立在同一性与因果这两种真实关系之上。"},"claims":[{"en":"Only two means of knowledge: perception and inference.","zh":"量只有两种：现量与比量。"},{"en":"Universals are conceptual exclusions, not real entities.","zh":"共相是概念上的遮遣，而非实在。"},{"en":"Valid cognition is what reliably guides successful action.","zh":"有效的认识，是能可靠地引导成功行动的认识。"}],"legacy":{"en":"It set the agenda for Indian epistemology for centuries—Nyāya and Mīmāṃsā wrote against it—and remains central to Tibetan monastic education; in China its logic became known as yinming.","zh":"它在数百年间主导了印度认识论的议题——正理派与弥曼差派都撰文反驳它——至今仍是藏传寺院教育的核心；在中国，它的逻辑被称为“因明”。"},"works":[{"by":"dignaga","t":{"en":"Pramāṇasamuccaya (Compendium of Valid Cognition)","zh":"《集量论》"},"y":520},{"by":"dignaga","t":{"en":"Nyāyamukha (Introduction to Logic)","zh":"《因明正理门论》"},"y":500},{"by":"dharmakirti","t":{"en":"Pramāṇavārttika (Commentary on Valid Cognition)","zh":"《释量论》"},"y":630}],"figures":["dignaga","dharmakirti"],"tags":"pramana buddhist logic epistemology dignaga dharmakirti apoha perception inference hetu yinming 量论 因明 陈那 法称 现量 比量 遮遣 因三相","wiki":"Buddhist logico-epistemology"},
  {"id":"advaita","tradition":"indian","start":550,"end":2026,"dates":{"en":"c. 6th c. CE – today","zh":"约公元6世纪至今"},"name":{"en":"Advaita Vedānta","zh":"不二论吠檀多"},"branches":["metaphysics","mind","religion"],"idea":{"en":"Brahman, pure consciousness, is the only reality; the self is Brahman, and the world of many things is an appearance produced by ignorance (avidyā).","zh":"梵即纯粹意识，是唯一的实在；自我就是梵，而由众多事物构成的世界只是无明所生的显现。"},"question":{"en":"If the self is Brahman, why do we experience a world of many things?","zh":"如果自我就是梵，我们为什么会经验到一个纷繁多样的世界？"},"origin":{"en":"Vedānta (‘the end of the Veda’) schools interpreted the Upanishads, the Bhagavad Gītā and the Brahma Sūtra. Gauḍapāda and Śaṅkara read them as teaching strict non-duality, in sharp debate with Buddhists and with Mīmāṃsakas, whose ritual-first view Śaṅkara rejected.","zh":"吠檀多（“吠陀的终结”）诸派诠释奥义书、《薄伽梵歌》与《梵经》。乔荼波陀与商羯罗把它们解读为严格的不二之教，并与佛教徒和弥曼差派展开激烈辩论——商羯罗拒绝了后者以祭祀为先的立场。"},"reasoning":{"en":"Only what never changes and is never negated is ultimately real; objects come and go, but the awareness to which they appear is never absent. As a rope in dim light is mistaken for a snake, Brahman is mistaken for the world and the self for a limited person; knowledge removes the error, as seeing the rope removes the snake.","zh":"只有永不变化、永不被否定的东西才是终极真实的；对象来来去去，而对象所显现给它的那份觉知却从不缺席。正如昏暗中把绳子错看成蛇，人也把梵错认为世界，把自我错认为有限的个人；知识消除错误，就像看清绳子，蛇便消失。"},"claims":[{"en":"Brahman alone is real; the world is appearance.","zh":"唯梵真实，世界是显现。"},{"en":"The individual self is not different from Brahman.","zh":"个体自我与梵无别。"},{"en":"Liberation comes from knowledge, not ritual action.","zh":"解脱来自知识，而非祭祀行为。"}],"legacy":{"en":"It became the best-known Indian philosophy, shaping Hindu monastic orders and, through Vivekananda and others, modern global ideas of Hindu spirituality.","zh":"它成为最广为人知的印度哲学，塑造了印度教的出家僧团，并经由辨喜等人影响了现代世界对印度教灵性的理解。"},"works":[{"by":"gaudapada","t":{"en":"Māṇḍūkya Kārikā","zh":"《蛙氏奥义颂》"},"y":550},{"by":"shankara","t":{"en":"Brahmasūtra-bhāṣya (Commentary on the Brahma Sūtra)","zh":"《梵经注》"},"y":720},{"by":"shankara","t":{"en":"Upadeśasāhasrī (A Thousand Teachings)","zh":"《示教千则》"},"y":720}],"figures":["gaudapada","shankara"],"tags":"advaita vedanta non-dualism brahman atman maya avidya shankara rope snake 不二论 吠檀多 梵 我 摩耶 无明 商羯罗 绳蛇","wiki":"Advaita Vedanta"},
  {"id":"theistic-vedanta","tradition":"indian","start":1050,"end":2026,"dates":{"en":"11th c. CE – today","zh":"公元11世纪至今"},"name":{"en":"Theistic Vedānta (Viśiṣṭādvaita & Dvaita)","zh":"有神论吠檀多（限定不二论与二元论）"},"branches":["religion","metaphysics","ethics"],"idea":{"en":"Brahman is a personal God (Viṣṇu), souls and the world are real, and liberation comes through loving devotion (bhakti) and God’s grace.","zh":"梵是人格神（毗湿奴），灵魂与世界都是真实的；解脱来自虔爱（巴克提）与神的恩典。"},"question":{"en":"How can finite souls be real and still depend on one God?","zh":"有限的灵魂如何既是真实的，又依赖于唯一的神？"},"origin":{"en":"In South India the devotional poetry of the Ālvār saints had made love of Viṣṇu central to religious life. Rāmānuja, and later Madhva, gave that devotion a philosophical defence by rereading the same Upanishads that Śaṅkara had read as strictly non-dual.","zh":"在南印度，阿尔瓦尔圣者的虔爱诗歌已使对毗湿奴的爱成为宗教生活的中心。罗摩奴阇以及后来的摩陀婆，通过重新诠释商羯罗曾解读为严格不二的那些奥义书，为这种虔爱提供了哲学辩护。"},"reasoning":{"en":"Rāmānuja argued that all knowledge has an object and involves distinctions, so a pure, featureless consciousness and an illusory world make no sense; souls and matter are real, as the ‘body’ of God, qualifying a single Brahman. Madhva went further: God, souls and matter are eternally different, just as scripture’s plain meaning and ordinary perception say.","zh":"罗摩奴阇论证说，一切认识都有对象、都包含区分，所以“无差别的纯粹意识”和“虚幻的世界”都讲不通；灵魂与物质是真实的，作为神的“身体”限定着唯一的梵。摩陀婆走得更远：神、灵魂与物质永远彼此不同，正如经典的字面意义和日常感知所告诉我们的那样。"},"claims":[{"en":"The world is real, not an illusion.","zh":"世界是真实的，而非幻象。"},{"en":"Souls are distinct from, and dependent on, God.","zh":"灵魂有别于神，并依赖于神。"},{"en":"Devotion (bhakti) and grace lead to liberation.","zh":"虔爱与恩典引向解脱。"}],"legacy":{"en":"It underlies the major Vaiṣṇava traditions, including the Śrī Vaiṣṇava community, and fed later devotional movements across India.","zh":"它是吉祥毗湿奴派等主要毗湿奴信仰传统的哲学基础，也滋养了此后遍及印度的虔爱运动。"},"works":[{"by":"ramanuja","t":{"en":"Śrībhāṣya (commentary on the Brahma Sūtra)","zh":"《吉祥注》（梵经注）"},"y":1100},{"by":"ramanuja","t":{"en":"Vedārthasaṃgraha (Summary of the Meaning of the Veda)","zh":"《吠陀义摄》"},"y":1100},{"by":"madhva","t":{"en":"Brahmasūtra-bhāṣya (commentary on the Brahma Sūtra)","zh":"《梵经注》"},"y":1280}],"figures":["ramanuja","madhva"],"tags":"vishishtadvaita dvaita vedanta ramanuja madhva bhakti vishnu grace devotion theism 限定不二论 二元论 吠檀多 罗摩奴阇 摩陀婆 虔爱 毗湿奴 恩典","wiki":"Vishishtadvaita"},
  {"id":"neo-vedanta","tradition":"indian","start":1880,"end":2026,"dates":{"en":"late 19th c. – today","zh":"19世纪晚期至今"},"name":{"en":"Neo-Vedānta & modern Indian thought","zh":"新吠檀多与近代印度思想"},"branches":["religion","ethics","politics"],"idea":{"en":"The Vedāntic insight that all beings share one divine reality should be lived out as practical service, religious tolerance and national renewal.","zh":"一切众生共有同一神圣实在——这一吠檀多洞见，应当落实为实际的服务、宗教宽容与民族复兴。"},"question":{"en":"What can India’s ancient philosophy offer a colonised, modernising world?","zh":"印度的古老哲学，能为一个被殖民、正在现代化的世界提供什么？"},"origin":{"en":"Under British rule, Indian intellectuals faced missionary criticism and Western science. Reformers from Ram Mohan Roy onward, then Vivekananda and Aurobindo, recast Vedānta as a rational, universal spirituality that could also ground social reform and nationalism.","zh":"在英国统治下，印度知识分子面对传教士的批评与西方科学的冲击。从拉姆·莫汉·罗伊开始，到辨喜与阿罗频多，改革者把吠檀多重塑为一种理性的、普世的灵性，并以此支撑社会改革与民族主义。"},"reasoning":{"en":"If every person is ultimately divine, then serving people is serving God, caste and sectarian divisions lose their basis, and the religions are many paths to one truth. Aurobindo added an evolutionary turn: consciousness hidden in matter is unfolding through life and mind toward a higher ‘supermind’, so spiritual life should transform the world rather than flee it.","zh":"如果每个人归根到底都是神圣的，那么服务众人就是服务神，种姓与宗派的隔阂便失去依据，各宗教也只是通往同一真理的不同道路。阿罗频多又加上了进化的维度：潜藏于物质中的意识正经由生命与心智，向更高的“超心”展开，所以灵性生活应当改造世界，而不是逃离世界。"},"claims":[{"en":"All religions are paths to the same truth.","zh":"一切宗教都是通往同一真理的道路。"},{"en":"Service to humanity is worship of the divine.","zh":"服务人类即是敬奉神明。"},{"en":"Spirit evolves through matter toward higher consciousness (Aurobindo).","zh":"精神经由物质向更高的意识进化（阿罗频多）。"}],"legacy":{"en":"It shaped Indian nationalism and the worldwide image of yoga and Vedānta; critics argue it reshaped classical Advaita in Western, Protestant-influenced terms.","zh":"它塑造了印度民族主义，以及世界对瑜伽和吠檀多的印象；批评者认为，它是用受西方新教影响的方式改写了古典不二论。"},"works":[{"by":"vivekananda","t":{"en":"Raja Yoga","zh":"《胜王瑜伽》"},"y":1896},{"by":"aurobindo","t":{"en":"The Life Divine","zh":"《神圣人生论》"},"y":1940}],"figures":["vivekananda","aurobindo"],"tags":"neo-vedanta vivekananda aurobindo ramakrishna hindu reform universal religion integral yoga supermind nationalism 新吠檀多 辨喜 阿罗频多 罗摩克里希纳 印度教改革 整体瑜伽 超心 民族主义","wiki":"Neo-Vedanta"},
  {"id":"milesian","tradition":"greek","start":-585,"end":-525,"dates":{"en":"c. 585–525 BCE","zh":"约公元前585–前525年"},"name":{"en":"Milesian school","zh":"米利都学派"},"branches":["metaphysics"],"idea":{"en":"Everything is made of one underlying stuff, and nature can be explained by natural causes rather than the whims of gods.","zh":"万物出自同一种基本质料；自然可以用自然原因来解释，而不必诉诸神灵的意志。"},"question":{"en":"What is the world ultimately made of?","zh":"世界最终由什么构成？"},"origin":{"en":"Miletus was a rich Ionian trading port in contact with Egypt, Babylon and Lydia, where myths of the gods’ origins sat beside practical astronomy and geometry. Thales and his successors began asking for the archē, the single origin or principle behind the many things we see, and answered with reasons that others could argue against.","zh":"米利都是爱奥尼亚一座富庶的贸易港口，与埃及、巴比伦和吕底亚往来频繁；在这里，关于诸神起源的神话与实用的天文、几何知识并存。泰勒斯及其后继者开始追问“本原”（archē）——众多事物背后那个唯一的起源或原理，并用别人可以反驳的理由来作答。"},"reasoning":{"en":"Things change into one another: water freezes and evaporates, food becomes flesh. If change is transformation rather than creation from nothing, something must persist through it. Thales proposed water, Anaximander an unbounded “apeiron”, Anaximenes air that thickens and thins.","zh":"事物会相互转化：水会结冰、蒸发，食物会变成血肉。如果变化是转化而非无中生有，那么变化中必定有某种持存的东西。泰勒斯认为是水，阿那克西曼德认为是“无定”（apeiron），阿那克西美尼则认为是会凝聚与稀散的气。"},"claims":[{"en":"There is a single underlying principle (archē) of all things.","zh":"万物有一个共同的本原。"},{"en":"Nature runs by regular processes, not divine caprice.","zh":"自然按规律运行，而非出于神灵的任性。"},{"en":"Change is one substance transforming, not something from nothing.","zh":"变化是同一种质料的转化，而非无中生有。"}],"legacy":{"en":"It began the Greek habit of explaining nature by stated, criticisable reasons, the common root of Western philosophy and natural science.","zh":"它开创了以明确、可批评的理由解释自然的希腊传统，这是西方哲学与自然科学的共同源头。"},"works":[{"by":"anaximander","t":{"en":"On Nature (one fragment survives)","zh":"《论自然》（仅存一则残篇）"},"y":-550},{"by":"aristotle","t":{"en":"Metaphysics, Book A (our main ancient report)","zh":"《形而上学》第一卷（最主要的古代记述）"},"y":-330}],"figures":["thales","anaximander","anaximenes"],"tags":"miletus arche water apeiron air ionia natural philosophy presocratic 米利都 本原 水 无定 气 爱奥尼亚 自然哲学 前苏格拉底","wiki":"Milesian school"},
  {"id":"pythagorean","tradition":"greek","start":-530,"end":-350,"dates":{"en":"c. 530–350 BCE","zh":"约公元前530–前350年"},"name":{"en":"Pythagoreanism","zh":"毕达哥拉斯学派"},"branches":["metaphysics","religion","ethics"],"idea":{"en":"The cosmos is an ordered harmony structured by number, and the immortal soul is purified by understanding that order.","zh":"宇宙是由数构成的有序和谐；不朽的灵魂通过理解这种秩序而得到净化。"},"question":{"en":"What gives the world its order, and how should the soul live?","zh":"是什么赋予世界秩序？灵魂应当如何生活？"},"origin":{"en":"Around 530 BCE Pythagoras left Samos for Croton in southern Italy and founded a community that was at once a religious brotherhood, a way of life and a circle of inquiry. Discoveries such as the numerical ratios of musical concords suggested that mathematics could reveal hidden structure in nature.","zh":"约公元前530年，毕达哥拉斯离开萨摩斯岛，来到南意大利的克罗顿，建立起一个团体——它既是宗教兄弟会，也是一种生活方式和一个研究圈子。和谐的音程对应简单的数字比例，这类发现让人想到：数学可以揭示自然中隐藏的结构。"},"reasoning":{"en":"If the octave, fifth and fourth correspond to the ratios 2:1, 3:2 and 4:3, then beauty and order are, at bottom, number. Philolaus argued that nothing could be known without number, since knowing means grasping limit and proportion. A soul that studies this order becomes ordered itself.","zh":"如果八度、五度、四度分别对应2:1、3:2、4:3的比例，那么美与秩序归根结底就是数。菲洛劳斯论证说，没有数便无从认识任何事物，因为认识就是把握界限与比例。研究这种秩序的灵魂，自身也会变得有序。"},"claims":[{"en":"Number and proportion are the principles of all things.","zh":"数与比例是万物的原理。"},{"en":"The soul is immortal and passes into new bodies.","zh":"灵魂不朽，会转入新的身体。"},{"en":"Philosophy is a way of life that purifies the soul.","zh":"哲学是一种净化灵魂的生活方式。"}],"legacy":{"en":"Through Plato it passed on the conviction that reality is mathematically structured, an idea that still drives physics; it was revived as Neopythagoreanism from the 1st century BCE.","zh":"它经由柏拉图传下“实在具有数学结构”的信念，这一观念至今仍推动着物理学；公元前1世纪起又复兴为新毕达哥拉斯主义。"},"works":[{"by":"philolaus","t":{"en":"On Nature (fragments)","zh":"《论自然》（残篇）"},"y":-420}],"figures":["pythagoras","philolaus"],"tags":"pythagoras number harmony music ratio transmigration croton tetractys mathematics 毕达哥拉斯 数 和谐 音乐 比例 灵魂轮回 克罗顿 数学","wiki":"Pythagoreanism"},
  {"id":"eleatic","tradition":"greek","start":-490,"end":-430,"dates":{"en":"c. 490–430 BCE","zh":"约公元前490–前430年"},"name":{"en":"Eleatic school","zh":"埃利亚学派"},"branches":["metaphysics","logic","epistemology"],"idea":{"en":"Reason shows that what is cannot come to be, change or be many, so the changing world of the senses is an illusion.","zh":"理性表明，“存在”不能生成、不能变化，也不能是多；因此感官所见的变动世界只是幻象。"},"question":{"en":"Can what is ever come from what is not?","zh":"“存在”能否出自“非存在”？"},"origin":{"en":"The Milesians and Heraclitus had described a world of constant transformation. In Elea, a Greek colony in southern Italy, Parmenides asked whether such talk was even coherent, and in a poem gave the first sustained deductive argument in Western thought. His pupil Zeno defended him with paradoxes against plurality and motion.","zh":"米利都学派与赫拉克利特描绘了一个不断转化的世界。在南意大利的希腊殖民地埃利亚，巴门尼德追问：这样的说法本身是否融贯？他在一首诗中提出了西方思想中第一个持续展开的演绎论证。他的学生芝诺则以反驳“多”与“运动”的悖论为老师辩护。"},"reasoning":{"en":"You cannot think or say what is not, because there is nothing there to think. So what is cannot come from nothing, pass into nothing, or change, since change means becoming what one was not. Zeno added that if motion were real, a runner would have to cross infinitely many half-distances, which seemed impossible.","zh":"我们无法思考或言说“不存在者”，因为那里没有任何可供思考的东西。所以存在者不能出自无，不能归于无，也不能变化——变化就意味着成为自己原本不是的东西。芝诺补充说：如果运动真实存在，奔跑者就必须越过无穷多个“一半的距离”，而这似乎不可能。"},"claims":[{"en":"What is, is; what is not cannot be thought.","zh":"存在者存在，不存在者不可被思考。"},{"en":"Coming-to-be, change and plurality are illusions of the senses.","zh":"生成、变化与多，都是感官的幻象。"},{"en":"Reason, not perception, is the judge of truth.","zh":"判断真理的是理性，而不是感知。"}],"legacy":{"en":"It forced every later Greek physics to explain change without creation from nothing, and Zeno’s paradoxes carried debates about infinity into modern mathematics.","zh":"它迫使此后所有的希腊自然哲学都必须在不承认“无中生有”的前提下解释变化；芝诺悖论则把关于无限的争论一直带进了现代数学。"},"works":[{"by":"parmenides","t":{"en":"On Nature (poem)","zh":"《论自然》（诗）"},"y":-475},{"by":"zeno-elea","t":{"en":"Paradoxes (book lost; reported by Aristotle and Simplicius)","zh":"《悖论》（原书已佚，见于亚里士多德与辛普里丘的转述）"},"y":null}],"figures":["parmenides","zeno-elea"],"tags":"elea parmenides being not-being zeno paradox achilles tortoise arrow motion one monism 埃利亚 巴门尼德 存在 非存在 芝诺悖论 阿基里斯 飞矢 运动 一元论","wiki":"Eleatics"},
  {"id":"pluralists","tradition":"greek","start":-460,"end":-428,"dates":{"en":"c. 460–428 BCE","zh":"约公元前460–前428年"},"name":{"en":"Pluralists","zh":"多元论者"},"branches":["metaphysics"],"idea":{"en":"Parmenides was right that nothing comes from nothing, but the world is many unchanging elements whose mixing and separating is what we call change.","zh":"巴门尼德说得对，无物出自无；但世界由多种不变的元素组成，它们的混合与分离，就是我们所说的变化。"},"question":{"en":"How can change be real if nothing comes from nothing?","zh":"如果无中不能生有，变化如何可能是真实的？"},"origin":{"en":"After Parmenides, simply naming one changing stuff was no longer an option. Empedocles in Sicily and Anaxagoras, who brought philosophy to Athens, accepted the Eleatic ban on absolute coming-to-be but tried to save the visible world by multiplying the ultimate realities.","zh":"巴门尼德之后，再简单地指认某一种会变化的本原已经行不通了。西西里的恩培多克勒，以及把哲学带到雅典的阿那克萨戈拉，都接受埃利亚学派对“绝对生成”的禁令，却试图通过增加终极实在的数量来挽救可见的世界。"},"reasoning":{"en":"If each basic ingredient is eternal and unchanging, nothing truly comes into being or perishes; only arrangements change. Empedocles named four “roots” (earth, water, air and fire) moved by Love and Strife. Anaxagoras held that “in everything there is a portion of everything”, set in motion by Mind (nous).","zh":"如果每一种基本成分都永恒不变，那么就没有什么真正生成或消亡，改变的只是组合方式。恩培多克勒提出土、水、气、火四种“根”，由“爱”与“争”推动；阿那克萨戈拉则主张“万物之中都有万物的一份”，由“心灵”（努斯）推动运转。"},"claims":[{"en":"There are many eternal elements, not one.","zh":"终极元素有多种，而非一种。"},{"en":"Change is the mixing and separating of what already exists.","zh":"变化是已存在之物的混合与分离。"},{"en":"A moving cause is needed: Love and Strife, or Mind.","zh":"需要一种推动的原因：爱与争，或心灵。"}],"legacy":{"en":"Empedocles’ four elements dominated European and Islamic science until the 17th century, and Anaxagoras’ cosmic Mind prompted Socrates and Plato to look for purpose in nature.","zh":"恩培多克勒的四元素说在欧洲和伊斯兰科学中一直占据主导，直到17世纪；阿那克萨戈拉以心灵为宇宙原因，促使苏格拉底与柏拉图去寻找自然中的目的。"},"works":[{"by":"empedocles","t":{"en":"On Nature and Purifications (fragments)","zh":"《论自然》与《净化》（残篇）"},"y":-450},{"by":"anaxagoras","t":{"en":"On Nature (fragments)","zh":"《论自然》（残篇）"},"y":-460}],"figures":["empedocles","anaxagoras"],"tags":"empedocles anaxagoras four elements roots love strife nous mind mixture presocratic 恩培多克勒 阿那克萨戈拉 四元素 四根 爱与争 努斯 心灵 前苏格拉底","wiki":"Pluralist school"},
  {"id":"sophists","tradition":"greek","start":-460,"end":-380,"dates":{"en":"c. 460–380 BCE","zh":"约公元前460–前380年"},"name":{"en":"Sophists","zh":"智者学派"},"branches":["epistemology","politics","logic"],"idea":{"en":"Human beings make their own measures: laws, values and even truths vary between communities, and skilled speech can make any case persuasive.","zh":"人为自己制定尺度：法律、价值乃至真理都随共同体而变；高明的言辞可以让任何一方的主张显得有说服力。"},"question":{"en":"Are justice and truth natural, or human conventions?","zh":"正义与真理是自然的，还是人为的约定？"},"origin":{"en":"Democratic Athens in the 5th century BCE rewarded anyone who could speak well in the assembly and the law courts. Travelling teachers such as Protagoras and Gorgias charged fees to teach rhetoric and “virtue” for public life, and their experience of many cities’ customs made them doubt that any one code was natural.","zh":"公元前5世纪的民主雅典，奖赏那些能在公民大会和法庭上善于言辞的人。普罗泰戈拉、高尔吉亚等游走各城邦的教师收费传授修辞术和公共生活所需的“德性”；见识过各城邦不同的风俗后，他们怀疑任何一套规范是出于自然的。"},"reasoning":{"en":"Customs differ from city to city, so they rest on agreement (nomos) rather than nature (physis). If “man is the measure of all things”, as Protagoras said, there is no neutral standpoint to settle disputes, and persuasion takes the place of proof. Gorgias went further, arguing that nothing exists, that if it did it could not be known, and that if known it could not be communicated.","zh":"风俗因城邦而异，所以它们建立在约定（nomos）而非自然（physis）之上。如果像普罗泰戈拉所说“人是万物的尺度”，就不存在一个中立的立场来裁决争论，说服便取代了证明。高尔吉亚走得更远：他论证说无物存在；即使存在也无法认识；即使能认识也无法传达。"},"claims":[{"en":"“Man is the measure of all things.”","zh":"“人是万物的尺度。”"},{"en":"Law and morality are conventions (nomos), not nature (physis).","zh":"法律与道德是约定，而非自然。"},{"en":"Rhetoric is a teachable power over belief.","zh":"修辞是一种可以传授的、左右信念的力量。"}],"legacy":{"en":"They put relativism, the nature–convention debate and the ethics of persuasion on the agenda; Plato’s hostility made “sophist” an insult, but modern scholars read them more sympathetically.","zh":"他们把相对主义、自然与约定之争以及说服的伦理问题摆上议程；柏拉图的敌意让“智者”成了贬义词，但现代学者对他们的评价要公允得多。"},"works":[{"by":"protagoras","t":{"en":"Truth (lost)","zh":"《论真理》（已佚）"},"y":-440},{"by":"gorgias","t":{"en":"On Non-Being","zh":"《论非存在》"},"y":-440},{"by":"gorgias","t":{"en":"Encomium of Helen","zh":"《海伦颂》"},"y":-415}],"figures":["protagoras","gorgias"],"tags":"sophist protagoras gorgias relativism rhetoric nomos physis convention measure 智者 普罗泰戈拉 高尔吉亚 相对主义 修辞 约定 自然 尺度","wiki":"Sophist"},
  {"id":"atomism","tradition":"greek","start":-440,"end":-370,"dates":{"en":"c. 440–370 BCE","zh":"约公元前440–前370年"},"name":{"en":"Atomism","zh":"原子论"},"branches":["metaphysics","ethics"],"idea":{"en":"Reality is nothing but indivisible bodies moving in empty space; everything we perceive arises from their shapes, positions and arrangements.","zh":"实在不过是在虚空中运动的不可分割的微粒；我们感知到的一切，都来自它们的形状、位置与排列。"},"question":{"en":"What must exist for motion and change to be possible?","zh":"要让运动与变化成为可能，必须存在什么？"},"origin":{"en":"Leucippus and Democritus of Abdera took up the Eleatic challenge directly. Parmenides had denied empty space and therefore motion; the atomists accepted his logic about being but boldly asserted that “what is not”, the void, exists too.","zh":"留基伯与阿布德拉的德谟克利特正面接下了埃利亚学派的挑战。巴门尼德否认虚空，因而否认运动；原子论者接受他关于“存在”的逻辑，却大胆断言：“非存在”——也就是虚空——同样存在。"},"reasoning":{"en":"If matter could be divided forever, it would dissolve into nothing, so there must be uncuttable (atomos) units, each as changeless as Parmenides’ being. If there is void between them, they can move, collide and combine. Colours and tastes exist “by convention”; “in reality there are atoms and void”.","zh":"如果物质可以被无限分割，它就会化为乌有；因此必定存在“不可切分的”（atomos）单元，每一个都像巴门尼德的“存在”一样不变。只要它们之间有虚空，它们就能运动、碰撞与结合。颜色和味道“出于约定”，“实际上只有原子和虚空”。"},"claims":[{"en":"Only atoms and void are real.","zh":"真实存在的只有原子和虚空。"},{"en":"Everything happens by necessity, without design.","zh":"一切都出于必然，而非出于设计。"},{"en":"Sense qualities such as colour exist by convention.","zh":"颜色等感官性质只是约定。"}],"legacy":{"en":"Revived by Epicurus and Lucretius, and again by Gassendi and Boyle in the 17th century, it became the template for mechanistic science.","zh":"它先由伊壁鸠鲁和卢克莱修复兴，17世纪又由伽桑狄与波义耳重新拾起，成为机械论科学的范本。"},"works":[{"by":"leucippus","t":{"en":"The Great World-System (attributed, lost)","zh":"《大宇宙系统》（传为其作，已佚）"},"y":-440},{"by":"democritus","t":{"en":"Fragments on ethics and nature","zh":"伦理与自然残篇"},"y":null}],"figures":["leucippus","democritus"],"tags":"atom atomos void democritus leucippus abdera materialism necessity mechanism 原子 虚空 德谟克利特 留基伯 阿布德拉 唯物论 必然 机械论","wiki":"Atomism"},
  {"id":"socratic","tradition":"greek","start":-430,"end":-399,"dates":{"en":"c. 430–399 BCE","zh":"约公元前430–前399年"},"name":{"en":"Socratic philosophy","zh":"苏格拉底哲学"},"branches":["ethics","epistemology"],"idea":{"en":"The unexamined life is not worth living: by questioning what we think we know about virtue, we discover our ignorance and begin to live well.","zh":"未经省察的人生不值得过：通过追问我们自以为懂得的德性，我们发现自己的无知，并由此开始好好生活。"},"question":{"en":"How should one live, and what is virtue?","zh":"人应当如何生活？德性是什么？"},"origin":{"en":"Socrates turned philosophy from the heavens to human life amid Athens’ war with Sparta, political upheaval and the sophists’ claim to teach virtue for money. He wrote nothing; we know him through Plato, Xenophon and Aristophanes. In 399 BCE Athens executed him for impiety and corrupting the young.","zh":"在雅典与斯巴达交战、政局动荡、智者收费教授德性的背景下，苏格拉底把哲学从天上拉回到人的生活。他没有留下任何著作，我们通过柏拉图、色诺芬和阿里斯托芬了解他。公元前399年，雅典以不敬神和败坏青年的罪名处死了他。"},"reasoning":{"en":"People act badly because they mistake what is good for them; no one does wrong knowingly. So virtue is a kind of knowledge, and the way to it is the elenchus: ask someone to define courage or justice, show that their answers contradict each other, and the shared perplexity clears the ground for real understanding.","zh":"人之所以作恶，是因为误把不好的东西当作对自己好的东西；没有人明知故犯。所以德性是一种知识，而通往它的道路是“诘问法”：请对方定义勇敢或正义，指出其回答自相矛盾，共同的困惑会为真正的理解扫清地面。"},"claims":[{"en":"Virtue is knowledge; no one does wrong willingly.","zh":"德性即知识；无人自愿作恶。"},{"en":"Wisdom begins in recognising one’s own ignorance.","zh":"智慧始于认识到自己的无知。"},{"en":"Care for the soul matters more than wealth or reputation.","zh":"关心灵魂比财富与名声更重要。"}],"legacy":{"en":"Almost every later Greek school claimed Socrates as its ancestor, and his questioning method remains the model of philosophical dialogue and teaching.","zh":"后来几乎每一个希腊学派都奉苏格拉底为祖师；他的追问方法至今仍是哲学对话与教学的范式。"},"works":[{"by":"plato","t":{"en":"Apology","zh":"《申辩篇》"},"y":-390},{"by":"plato","t":{"en":"Euthyphro","zh":"《游叙弗伦篇》"},"y":-390}],"figures":["socrates"],"tags":"socrates elenchus irony virtue knowledge examined life athens trial gadfly 苏格拉底 诘问法 反讽 德性 知识 省察 审判 牛虻","wiki":"Socrates"},
  {"id":"cynicism","tradition":"greek","start":-400,"end":450,"dates":{"en":"c. 400 BCE – 5th c. CE","zh":"约公元前400年–公元5世纪"},"name":{"en":"Cynicism","zh":"犬儒主义"},"branches":["ethics","politics"],"idea":{"en":"Virtue alone is enough for happiness, and it is found by living simply according to nature, scorning wealth, status and social convention.","zh":"仅凭德性就足以获得幸福；而德性在于顺应自然、简朴地生活，蔑视财富、地位与社会习俗。"},"question":{"en":"What do we really need to live well?","zh":"要好好生活，我们真正需要什么？"},"origin":{"en":"Antisthenes, a follower of Socrates, took his master’s indifference to comfort and opinion as the heart of philosophy. Diogenes of Sinope, exiled and poor, turned it into public performance in Athens and Corinth, living in a storage jar and mocking the powerful; the name comes from kyōn, “dog”.","zh":"苏格拉底的追随者安提斯泰尼，把老师对舒适与名声的漠然视为哲学的核心。被流放、一贫如洗的锡诺普的第欧根尼，又把它变成在雅典和科林斯街头的公开表演：他住在一只大陶瓮里，嘲弄权贵。“犬儒”之名来自希腊语 kyōn（狗）。"},"reasoning":{"en":"If virtue is all that matters for happiness, as Socrates suggested, then everything else, such as money, fame, family and city, is at best indifferent and often a chain. Animals live well with almost nothing; so can we, once we strip away artificial needs. Shamelessness becomes a teaching tool that exposes how arbitrary conventions are.","zh":"如果像苏格拉底暗示的那样，幸福只取决于德性，那么其余一切——金钱、名声、家庭、城邦——充其量无关紧要，往往还是枷锁。动物几乎一无所有也活得很好；只要剥除人为的需求，我们也可以。“无耻”于是成为一种教学手段，用来揭露习俗的任意性。"},"claims":[{"en":"Virtue is sufficient for happiness.","zh":"德性足以带来幸福。"},{"en":"Live according to nature, not convention.","zh":"依自然而非依习俗生活。"},{"en":"“I am a citizen of the world” (kosmopolitēs).","zh":"“我是世界公民。”"}],"legacy":{"en":"Cynicism handed Stoicism its ethical core and coined the ideal of the cosmopolitan; its provocative style lives on in satire and protest, though modern “cynical” means something quite different.","zh":"犬儒主义把伦理核心交给了斯多葛主义，并提出了“世界公民”的理想；它挑衅的风格在讽刺文学和抗议中延续，不过现代汉语与英语中的“犬儒”含义已大不相同。"},"works":[],"figures":["antisthenes","diogenes"],"tags":"cynic diogenes antisthenes crates dog jar barrel cosmopolitan nature convention shamelessness 犬儒 第欧根尼 安提斯泰尼 克拉特斯 狗 陶瓮 世界公民 自然 习俗","wiki":"Cynicism (philosophy)"},
  {"id":"platonism","tradition":"greek","start":-387,"end":529,"dates":{"en":"387 BCE – 6th c. CE","zh":"公元前387年–公元6世纪"},"name":{"en":"Platonism","zh":"柏拉图主义"},"branches":["metaphysics","epistemology","politics"],"idea":{"en":"Beyond the changing world of the senses lie eternal, perfect Forms, such as Justice and Beauty themselves, which only reason can know and which make things what they are.","zh":"在变动的感官世界之外，存在着永恒完美的“理念”，如正义本身、美本身；只有理性能认识它们，而事物正是因分有它们才成为其所是。"},"question":{"en":"What is truly real, and how can we know it?","zh":"什么才是真正实在的？我们如何认识它？"},"origin":{"en":"Plato watched Athens execute Socrates and heard the sophists teach that values are convention. He wanted to show that Socrates’ search for definitions had a real object, and drew on Parmenides’ unchanging being, Heraclitus’ flux and Pythagorean mathematics. Around 387 BCE he founded the Academy, whose tradition lasted in various forms for centuries.","zh":"柏拉图目睹雅典处死苏格拉底，又听到智者宣称价值只是约定。他想证明苏格拉底追寻的定义确有其对象，并汲取了巴门尼德不变的“存在”、赫拉克利特的流变与毕达哥拉斯学派的数学。约公元前387年，他创办学园，其传统以不同形式延续了数百年。"},"reasoning":{"en":"No drawn circle is perfectly round and no act perfectly just, yet we recognise imperfection, so we must know the standard from somewhere. Sensible things change, but knowledge must be of what is stable. Therefore there are unchanging Forms, grasped by the intellect and perhaps recollected by an immortal soul; the visible world is like shadows on the wall of a cave.","zh":"没有哪个画出来的圆是完美的圆，也没有哪个行为是完美的正义，但我们能认出不完美，这说明我们必定从某处知道了标准。可感事物不断变化，而知识必须关乎稳定之物。所以必定存在不变的“理念”，由理智把握，或许是不朽灵魂的回忆；可见世界就像洞穴墙壁上的影子。"},"claims":[{"en":"Eternal Forms are more real than sensible things.","zh":"永恒的理念比可感事物更真实。"},{"en":"Learning is the recollection of an immortal soul.","zh":"学习是不朽灵魂的回忆。"},{"en":"A just city is ruled by those who know the Good.","zh":"正义的城邦应由认识“善”的人统治。"}],"legacy":{"en":"Whitehead called European philosophy “a series of footnotes to Plato”; through Neoplatonism it shaped Christian, Jewish and Islamic theology, and debates over abstract objects in mathematics are still argued in its terms.","zh":"怀特海说，欧洲哲学是“对柏拉图的一系列注脚”；经由新柏拉图主义，它塑造了基督教、犹太教与伊斯兰教的神学，关于数学抽象对象的争论至今仍以它的语汇展开。"},"works":[{"by":"plato","t":{"en":"Republic","zh":"《理想国》"},"y":-375},{"by":"plato","t":{"en":"Symposium","zh":"《会饮篇》"},"y":-385},{"by":"plato","t":{"en":"Phaedo","zh":"《斐多篇》"},"y":-380},{"by":"plato","t":{"en":"Timaeus","zh":"《蒂迈欧篇》"},"y":-360}],"figures":["plato"],"tags":"plato forms ideas academy cave recollection republic philosopher king good idealism 柏拉图 理念 形式 学园 洞穴 回忆说 理想国 哲学王 善","wiki":"Platonism"},
  {"id":"aristotelianism","tradition":"greek","start":-335,"end":200,"dates":{"en":"335 BCE – c. 200 CE (and long after)","zh":"公元前335年–约公元200年（影响远不止于此）"},"name":{"en":"Aristotelianism","zh":"亚里士多德主义（逍遥学派）"},"branches":["logic","metaphysics","ethics"],"idea":{"en":"Forms are not in a separate heaven but in things themselves; to understand anything is to grasp its matter, form, source of change and purpose.","zh":"形式不在另一个天界，而就在事物之中；理解任何事物，就是把握它的质料、形式、运动的来源与目的。"},"question":{"en":"What is it for a thing to be, and how do we explain it?","zh":"一个事物“存在”是什么意思？我们如何解释它？"},"origin":{"en":"Aristotle studied in Plato’s Academy for about twenty years but came to doubt that separate Forms explain the living, changing world he loved to observe. After tutoring the young Alexander the Great, he founded the Lyceum in Athens in 335 BCE, where the “Peripatetics” pursued research in logic, biology, physics, ethics and politics.","zh":"亚里士多德在柏拉图学园学习了约二十年，却逐渐怀疑：分离的理念究竟能否解释他热衷观察的那个生生不息、变动不居的世界？在担任少年亚历山大大帝的老师之后，他于公元前335年在雅典创办吕克昂学园，“逍遥学派”在那里研究逻辑、生物、物理、伦理与政治。"},"reasoning":{"en":"A separate Form of Horse explains nothing about why this foal grows into a horse. Better to say that each substance is matter shaped by form, explained by four causes: what it is made of, what it is, what started it, and what it is for. Humans also have a function, rational activity, and living it out excellently over a whole life is happiness (eudaimonia).","zh":"一个分离的“马的理念”无法解释这匹小马为何长成一匹马。更好的说法是：每个实体都是被形式塑造的质料，可由四因来解释——它由什么构成、它是什么、是什么使它开始运动、它为了什么。人也有其功能，即理性的活动；终其一生卓越地实现这种功能，就是幸福（eudaimonia）。"},"claims":[{"en":"Substances are matter informed by form; forms are in things.","zh":"实体是被形式赋形的质料；形式就在事物之中。"},{"en":"Explanation needs four causes, including purpose.","zh":"解释需要四因，其中包括目的因。"},{"en":"Happiness is virtuous rational activity over a whole life.","zh":"幸福是终其一生合乎德性的理性活动。"}],"legacy":{"en":"His logic ruled for two thousand years, and through Arabic and Latin commentators he became simply “the Philosopher” for Averroes and Aquinas; virtue ethics and biology still draw on him.","zh":"他的逻辑学统治了两千年；经由阿拉伯与拉丁注释家，他在阿威罗伊和阿奎那那里被直接称为“那位哲学家”。今天的德性伦理学与生物学仍在借用他的思想。"},"works":[{"by":"aristotle","t":{"en":"Nicomachean Ethics","zh":"《尼各马可伦理学》"},"y":-340},{"by":"aristotle","t":{"en":"Metaphysics","zh":"《形而上学》"},"y":-330},{"by":"aristotle","t":{"en":"Politics","zh":"《政治学》"},"y":-330},{"by":"theophrastus","t":{"en":"Enquiry into Plants","zh":"《植物志》"},"y":-300}],"figures":["aristotle","theophrastus"],"tags":"aristotle lyceum peripatetic four causes substance form matter hylomorphism logic syllogism organon eudaimonia golden mean teleology 亚里士多德 吕克昂 逍遥学派 四因 实体 形式 质料 三段论 工具论 幸福 中道 目的论","wiki":"Aristotelianism"},
  {"id":"skepticism","tradition":"greek","start":-320,"end":210,"dates":{"en":"c. 320 BCE – c. 200 CE","zh":"约公元前320年–约公元200年"},"name":{"en":"Pyrrhonism & Academic skepticism","zh":"怀疑主义（皮浪主义与学园派怀疑论）"},"branches":["epistemology","ethics"],"idea":{"en":"For every argument an equally strong opposing argument can be found, so we should suspend judgement, and tranquillity follows.","zh":"每个论证都能找到一个同样有力的反论证，因此我们应当悬置判断，而宁静随之而来。"},"question":{"en":"Can we know anything for certain?","zh":"我们能确定地知道任何事情吗？"},"origin":{"en":"Pyrrho of Elis travelled with Alexander’s army as far as India and returned teaching that things are undecidable; he wrote nothing. Separately, around 268 BCE Arcesilaus turned Plato’s Academy toward Socratic doubt, attacking the Stoics’ claim to certain knowledge. Centuries later Sextus Empiricus, a physician, systematised Pyrrhonism in books that survive.","zh":"埃利斯的皮浪随亚历山大的军队远至印度，归来后教导说事物是不可判定的；他没有留下著作。另一方面，约公元前268年，阿凯西劳斯使柏拉图学园转向苏格拉底式的怀疑，攻击斯多葛派对确定知识的主张。数百年后，医生塞克斯都·恩披里柯在传世著作中系统整理了皮浪主义。"},"reasoning":{"en":"Appearances conflict: honey tastes sweet to the healthy and bitter to the sick, and customs differ between peoples. To prove any criterion of truth you need another criterion, and so on to infinity, or in a circle, or by bare assumption. Since we cannot decide, the wise suspend judgement (epochē), live by appearances and custom, and find that peace of mind (ataraxia) follows like a shadow.","zh":"现象彼此冲突：健康的人尝蜂蜜是甜的，病人尝来却是苦的；各民族的习俗也各不相同。要证明任何真理标准，都需要另一个标准，于是陷入无穷后退、循环论证或纯粹假定。既然无法判定，智者就悬置判断（epochē），依照现象与习俗生活，并发现心灵的宁静（ataraxia）如影随形。"},"claims":[{"en":"Every argument can be balanced by an equal counter-argument.","zh":"每个论证都可被同等有力的反论证抵消。"},{"en":"The wise suspend judgement (epochē).","zh":"智者悬置判断。"},{"en":"Tranquillity follows the suspension of belief.","zh":"宁静随悬置判断而来。"}],"legacy":{"en":"The rediscovery of Sextus in the 16th century set off the early modern “skeptical crisis” that Montaigne explored and Descartes tried to answer; the regress problem is still central to epistemology.","zh":"16世纪塞克斯都著作的重新发现，引发了早期现代的“怀疑主义危机”——蒙田探索了它，笛卡尔试图回应它；无穷后退问题至今仍是认识论的核心问题。"},"works":[{"by":"sextus-empiricus","t":{"en":"Outlines of Pyrrhonism","zh":"《皮浪学说概要》"},"y":200},{"by":"sextus-empiricus","t":{"en":"Against the Mathematicians","zh":"《反数学家》"},"y":200},{"by":"cicero","t":{"en":"Academica","zh":"《学园派》"},"y":-45}],"figures":["pyrrho","sextus-empiricus","cicero"],"tags":"skeptic sceptic pyrrho pyrrhonism sextus empiricus epoche suspension judgement academic arcesilaus carneades regress modes 怀疑论 怀疑主义 皮浪 塞克斯都 悬置判断 学园派 阿凯西劳斯 卡尔涅阿德斯 无穷后退","wiki":"Pyrrhonism"},
  {"id":"epicureanism","tradition":"greek","start":-306,"end":250,"dates":{"en":"306 BCE – 3rd c. CE","zh":"公元前306年–公元3世纪"},"name":{"en":"Epicureanism","zh":"伊壁鸠鲁主义"},"branches":["ethics","metaphysics"],"idea":{"en":"The goal of life is pleasure understood as tranquillity: freedom from bodily pain and mental fear, reached through simple living, friendship and a true understanding of nature.","zh":"人生的目的在于快乐，而快乐即宁静：身体无痛苦、心灵无恐惧；通往它的是简朴的生活、友谊，以及对自然的真实理解。"},"question":{"en":"How can we live free from fear and pain?","zh":"我们如何摆脱恐惧与痛苦地生活？"},"origin":{"en":"After Alexander’s death the Greek world was ruled by vast, unstable kingdoms, and citizens had little control over public life. Around 306 BCE Epicurus founded a community, the Garden, outside Athens, open to women and slaves, offering a therapy for anxiety built on Democritus’ atomism.","zh":"亚历山大死后，希腊世界由庞大而动荡的王国统治，公民对公共生活几乎没有掌控力。约公元前306年，伊壁鸠鲁在雅典城外建立名为“花园”的团体，接纳女性和奴隶，以德谟克利特的原子论为基础，提供一种治疗焦虑的哲学。"},"reasoning":{"en":"Everything, including the soul, is atoms that disperse at death, so “death is nothing to us”: where death is, we are not. The gods, if they exist, do not meddle in the world, so there is nothing to fear from them either. Remove these fears and limit desires to the natural and necessary, and what remains is ataraxia, a stable and deep pleasure.","zh":"万物包括灵魂都由原子构成，死时原子散去，所以“死亡与我们无关”：死亡在时，我们已不在。神即使存在，也不干预世界，因此也不必畏惧神。消除这些恐惧，把欲望限制在自然而必要的范围内，剩下的就是“不受扰动”（ataraxia）——一种稳定而深沉的快乐。"},"claims":[{"en":"Pleasure, as absence of pain and fear, is the good.","zh":"快乐——即没有痛苦与恐惧——就是善。"},{"en":"Death is nothing to us.","zh":"死亡与我们无关。"},{"en":"Friendship is among the greatest goods.","zh":"友谊是最大的善之一。"}],"legacy":{"en":"Lucretius’ poem preserved it for the Renaissance, where its rediscovery fed early modern science and secular ethics; utilitarianism inherits its view that pleasure and pain are what matter.","zh":"卢克莱修的长诗把它保存下来，文艺复兴时期重新被发现，滋养了早期现代科学与世俗伦理；功利主义继承了它“快乐与痛苦才是要紧的”这一观点。"},"works":[{"by":"epicurus","t":{"en":"Letter to Menoeceus","zh":"《致美诺寇的信》"},"y":-300},{"by":"epicurus","t":{"en":"Principal Doctrines","zh":"《基本要道》"},"y":-300},{"by":"lucretius","t":{"en":"On the Nature of Things","zh":"《物性论》"},"y":-55}],"figures":["epicurus","lucretius"],"tags":"epicurus garden pleasure hedonism ataraxia atom swerve death lucretius tranquillity friendship 伊壁鸠鲁 花园 快乐主义 宁静 原子 偏斜 死亡 卢克莱修 友谊","wiki":"Epicureanism"},
  {"id":"stoicism","tradition":"greek","start":-300,"end":250,"dates":{"en":"c. 300 BCE – 3rd c. CE","zh":"约公元前300年–公元3世纪"},"name":{"en":"Stoicism","zh":"斯多葛主义"},"branches":["ethics","logic","metaphysics"],"idea":{"en":"Virtue is the only good; by living in agreement with nature’s rational order and judging events rightly, we can be free and at peace whatever happens.","zh":"德性是唯一的善；只要顺应自然的理性秩序生活、正确地判断所发生的事，无论遭遇什么，我们都能获得自由与安宁。"},"question":{"en":"How can we be happy in a world we cannot control?","zh":"在一个我们无法掌控的世界里，如何获得幸福？"},"origin":{"en":"Zeno of Citium, a merchant who by ancient anecdote was shipwrecked near Athens, studied with the Cynic Crates and with Platonists before teaching in the Painted Porch (Stoa Poikilē) around 300 BCE. In the uncertain Hellenistic world, and later in Rome, Stoicism offered a complete system of logic, physics and ethics for living under fortune.","zh":"季蒂昂的芝诺原是商人，据古代轶事在雅典附近遭遇海难，随后师从犬儒克拉特斯，也向柏拉图派学习，约公元前300年开始在“画廊”（Stoa Poikilē）讲学。在动荡的希腊化世界以及后来的罗马，斯多葛主义提供了一套完整的逻辑、物理与伦理体系，教人如何在命运之下生活。"},"reasoning":{"en":"The cosmos is ordered by logos, a divine reason, and we share in that reason. Health, wealth and reputation can be taken away, so they are not truly good; only our own judgements and choices are fully up to us. Passions such as fear and anger are mistaken judgements, so by correcting our judgements we can reach apatheia, freedom from disturbing passion.","zh":"宇宙由逻各斯——一种神圣的理性——安排，而我们也分有这种理性。健康、财富、名声都可能被夺走，所以它们并非真正的善；只有我们自己的判断与选择完全取决于我们。恐惧、愤怒等激情是错误的判断，因此通过纠正判断，就能达到“不动心”（apatheia），摆脱扰人的激情。"},"claims":[{"en":"Virtue is the only good; externals are “indifferent”.","zh":"德性是唯一的善；外物“无关善恶”。"},{"en":"Distinguish what is up to us from what is not.","zh":"区分哪些事取决于我们，哪些不取决于我们。"},{"en":"All humans share reason and form one world community.","zh":"所有人都分有理性，构成同一个世界共同体。"}],"legacy":{"en":"It shaped Roman law, Christian ethics and the ideas of natural law and universal human dignity; today it is revived in cognitive behavioural therapy and popular “Stoic” self-help.","zh":"它塑造了罗马法、基督教伦理，以及自然法与普遍人类尊严的观念；今天它又在认知行为疗法和流行的“斯多葛”自助读物中复兴。"},"works":[{"by":"epictetus","t":{"en":"Discourses","zh":"《论说集》"},"y":108},{"by":"epictetus","t":{"en":"Enchiridion","zh":"《道德手册》"},"y":125},{"by":"seneca","t":{"en":"Letters to Lucilius","zh":"《致鲁基里乌斯的道德书简》"},"y":65},{"by":"marcus-aurelius","t":{"en":"Meditations","zh":"《沉思录》"},"y":175}],"figures":["zeno-citium","chrysippus","seneca","epictetus","marcus-aurelius"],"tags":"stoa stoic logos virtue apatheia fate zeno chrysippus seneca epictetus marcus aurelius cosmopolitan natural law 斯多葛 逻各斯 美德 不动心 命运 塞涅卡 爱比克泰德 马可·奥勒留 世界主义 自然法","wiki":"Stoicism"},
  {"id":"neoplatonism","tradition":"greek","start":245,"end":600,"dates":{"en":"c. 245 – 6th c. CE","zh":"约公元245年–6世纪"},"name":{"en":"Neoplatonism","zh":"新柏拉图主义"},"branches":["metaphysics","religion","mind"],"idea":{"en":"All reality flows from a single, ineffable source, the One, through Intellect and Soul down to matter, and the soul’s task is to turn back and return to it.","zh":"一切实在都从一个不可言说的源头——“太一”——流溢而出，经由理智与灵魂一直下降到质料；灵魂的使命是回转，回归太一。"},"question":{"en":"How does the many come from the One, and how do we return?","zh":"多如何出自一？我们又如何回归？"},"origin":{"en":"In 3rd-century Rome, amid political crisis and competing salvation religions, Plotinus reread Plato as a unified system, absorbing Aristotle’s theory of intellect. His pupil Porphyry edited his treatises, and later teachers in Athens and Alexandria, such as Proclus and Hypatia, made it the last great school of pagan philosophy.","zh":"3世纪的罗马政治危机深重，各种救赎宗教相互竞争。普罗提诺把柏拉图重新解读为一个统一的体系，并吸收了亚里士多德的理智学说。他的学生波菲利编订了他的论著；此后雅典和亚历山大里亚的教师，如普罗克洛和希帕提娅，使之成为异教哲学最后一个伟大的学派。"},"reasoning":{"en":"Every multiplicity depends on a unity that holds it together, so the first principle must be absolutely one, beyond being and thought. It does not create by choice but overflows, as light radiates from the sun, producing Intellect (the realm of Forms), which produces Soul, which produces the visible world. Because we came from the One, we can return through philosophy, virtue and contemplation.","zh":"每一种“多”都依赖于把它维系起来的“一”，所以第一原理必须是绝对的一，超越存在与思想。它不是出于选择去创造，而是像阳光从太阳辐射那样自然流溢，产生理智（理念的领域），理智产生灵魂，灵魂产生可见世界。既然我们来自太一，就可以通过哲学、德性与静观回归太一。"},"claims":[{"en":"The One, beyond being, is the source of all things.","zh":"超越存在的太一是万物之源。"},{"en":"Reality is a hierarchy of emanation: One, Intellect, Soul, matter.","zh":"实在是流溢的层级：太一、理智、灵魂、质料。"},{"en":"The soul can ascend back to union with the One.","zh":"灵魂可以上升，复归与太一的合一。"}],"legacy":{"en":"Through Augustine, Pseudo-Dionysius, al-Farabi and Avicenna it became the metaphysical framework of medieval Christian, Islamic and Jewish thought, and it inspired Renaissance Florence and many mystical traditions.","zh":"经由奥古斯丁、伪狄奥尼修斯、法拉比与阿维森纳，它成为中世纪基督教、伊斯兰教与犹太教思想的形而上学框架，并启发了文艺复兴时期的佛罗伦萨和众多神秘主义传统。"},"works":[{"by":"plotinus","t":{"en":"Enneads","zh":"《九章集》"},"y":270},{"by":"porphyry","t":{"en":"Isagoge","zh":"《导论》"},"y":270},{"by":"proclus","t":{"en":"Elements of Theology","zh":"《神学要素》"},"y":450}],"figures":["plotinus","porphyry","proclus","hypatia"],"tags":"plotinus one emanation intellect nous soul enneads porphyry proclus hypatia alexandria mysticism late antiquity 普罗提诺 太一 流溢 理智 灵魂 九章集 波菲利 普罗克洛 希帕提娅 亚历山大里亚 神秘主义","wiki":"Neoplatonism"},
  {"id":"kalam","tradition":"islamic","start":730,"end":2026,"dates":{"en":"8th c. – present","zh":"8世纪至今"},"name":{"en":"Kalām (Muʿtazila & Ashʿarism)","zh":"凯拉姆：穆尔太齐赖派与艾什尔里派"},"branches":["religion","metaphysics","ethics"],"idea":{"en":"Faith must be defended by rational argument; the Muʿtazila made God’s justice and unity the measure, while the Ashʿarites made God’s unlimited power and will the measure.","zh":"信仰必须以理性论证来捍卫；穆尔太齐赖派以真主的公正与独一为尺度，艾什尔里派则以真主无限的权能与意志为尺度。"},"question":{"en":"Is something good because God commands it, or does God command it because it is good?","zh":"某事之所以善，是因为真主命令它，还是真主因它善而命令它？"},"origin":{"en":"Early Islamic disputes after the civil wars, over free will, the status of grave sinners and God’s attributes, met the arguments of Christian, Jewish and Manichaean debaters. Muslims developed a dialectical theology to answer them; the Abbasid inquisition (833–c. 848) briefly made Muʿtazili doctrine state policy.","zh":"早期伊斯兰内战之后，围绕自由意志、犯大罪者的地位和真主属性的争论，又遇上基督徒、犹太人和摩尼教徒的辩难。穆斯林发展出一套辩证神学来回应；阿拔斯王朝的“米哈奈”审查（833–约848年）一度把穆尔太齐赖派教义定为官方立场。"},"reasoning":{"en":"The Muʿtazila argued that a just God cannot punish acts humans do not freely choose, and that reason can know good and evil. Al-Ashʿari replied that nothing limits God: God creates every event at each instant, so causes are only God’s habits, and good is whatever God commands.","zh":"穆尔太齐赖派认为，公正的真主不会惩罚人并非自由选择的行为，而理性能认识善恶。艾什尔里反驳说，没有什么能限制真主：真主在每一瞬间创造每一件事，所谓因果只是真主的惯例，善就是真主所命令的。"},"claims":[{"en":"Muʿtazila: reason can know good and evil without revelation.","zh":"穆尔太齐赖派：理性无需启示即可认识善恶。"},{"en":"Ashʿarites: God directly creates every event; causes are only habits.","zh":"艾什尔里派：真主直接创造一切事件，因果只是惯例。"},{"en":"The world was created in time, out of nothing.","zh":"世界是在时间中从无中被创造的。"}],"legacy":{"en":"Ashʿarism, alongside Māturīdism, became the main theology of Sunni Islam, and Muʿtazili ideas lived on in Shiʿi and Jewish thought; its occasionalism anticipated later European debates on causation.","zh":"艾什尔里派与马图里迪派一起成为逊尼派伊斯兰的主流神学，穆尔太齐赖派思想则在什叶派与犹太思想中延续；其偶因论预示了后来欧洲关于因果的争论。"},"works":[{"by":"al-ashari","t":{"en":"Doctrines of the Muslims (Maqālāt al-Islāmiyyīn)","zh":"《伊斯兰教派言论集》"},"y":null},{"by":"al-ghazali","t":{"en":"The Incoherence of the Philosophers","zh":"《哲学家的矛盾》"},"y":1095}],"figures":["al-ashari","al-ghazali"],"tags":"kalam mutazila ashari asharism occasionalism divine command theology islamic 凯拉姆 教义学 穆尔太齐赖 艾什尔里 偶因论 伊斯兰神学","wiki":"Kalam"},
  {"id":"falsafa","tradition":"islamic","start":830,"end":1200,"dates":{"en":"c. 830 – 12th c.","zh":"约830年–12世纪"},"name":{"en":"Falsafa (Arabic Aristotelianism)","zh":"法尔萨法：阿拉伯亚里士多德主义"},"branches":["metaphysics","logic","mind"],"idea":{"en":"Greek philosophy, mainly Aristotle with a Neoplatonic frame, is the highest form of human knowledge, and its demonstrated truths agree with the inner meaning of revelation.","zh":"以新柏拉图主义为框架的亚里士多德哲学是人类知识的最高形式，它所证明的真理与启示的内在意义相一致。"},"question":{"en":"Can demonstrative reason reach the truths revelation teaches in images?","zh":"证明性的理性能否抵达启示以形象所教导的真理？"},"origin":{"en":"Under the Abbasid caliphs, translators in Baghdad rendered much of Greek science and philosophy into Arabic from the 8th to 10th centuries. A line of philosophers absorbed this corpus and built systems that rivalled the theologians’ kalām.","zh":"在阿拔斯王朝哈里发的支持下，8至10世纪巴格达的译者把大量希腊科学与哲学译成阿拉伯文。一批哲学家吸收了这套文献，建立起足以与神学家的凯拉姆相抗衡的体系。"},"reasoning":{"en":"Everything that exists either exists necessarily or only possibly; possible things need a cause, and the chain must end in a Necessary Existent, which is God. From God the world flows eternally through a hierarchy of intellects, the lowest of which illuminates human minds.","zh":"凡存在者，要么必然存在，要么仅仅可能存在；可能之物需要原因，而原因之链必须止于一个“必然存在者”，即真主。世界从真主那里经由一系列理智永恒地流出，其中最低的理智照亮人的心灵。"},"claims":[{"en":"God is the Necessary Existent, the cause of all else.","zh":"真主是必然存在者，是一切他物的原因。"},{"en":"The world proceeds eternally from God through intellects.","zh":"世界经由诸理智永恒地从真主流出。"},{"en":"Philosophy and true religion express one truth differently.","zh":"哲学与真宗教以不同方式表达同一真理。"}],"legacy":{"en":"Latin translations of Avicenna and Averroes transformed medieval European philosophy; in the Islamic East, Avicenna’s system remained the backbone of philosophy for centuries.","zh":"阿维森纳与阿威罗伊的拉丁译本改变了中世纪欧洲哲学；在伊斯兰东方，阿维森纳的体系数百年间一直是哲学的骨架。"},"works":[{"by":"al-farabi","t":{"en":"The Opinions of the People of the Virtuous City","zh":"《美德城邦居民意见书》"},"y":942},{"by":"ibn-sina","t":{"en":"The Book of Healing (al-Shifāʾ)","zh":"《治疗论》"},"y":1027},{"by":"ibn-tufayl","t":{"en":"Ḥayy ibn Yaqẓān","zh":"《哈伊·本·叶格赞》"},"y":1175},{"by":"ibn-rushd","t":{"en":"The Incoherence of the Incoherence","zh":"《矛盾的矛盾》"},"y":1180}],"figures":["al-kindi","al-farabi","ibn-sina","ibn-tufayl","ibn-rushd"],"tags":"falsafa avicenna averroes kindi farabi necessary existent house of wisdom translation 法尔萨法 阿维森纳 阿威罗伊 必然存在者 智慧宫 翻译运动","wiki":"Early Islamic philosophy"},
  {"id":"sufism","tradition":"islamic","start":850,"end":2026,"dates":{"en":"9th c. – present","zh":"9世纪至今"},"name":{"en":"Sufi metaphysics","zh":"苏非形而上学"},"branches":["religion","metaphysics","epistemology"],"idea":{"en":"The deepest knowledge of God comes by tasting and unveiling, not by argument; for Ibn ʿArabī, God alone truly is, and creatures are God’s self-disclosures.","zh":"对真主最深的认识来自体味与揭示，而非论证；在伊本·阿拉比看来，唯有真主真正存在，万物都是真主的自我显现。"},"question":{"en":"Can God be known directly, beyond reason?","zh":"真主能否超越理性被直接认识？"},"origin":{"en":"Sufism began as an ascetic and devotional movement seeking closeness to God. As it matured, thinkers set out the theory behind the practice: how the self is purified, and what the world must be if a mystic can find God in it.","zh":"苏非主义起初是追求亲近真主的苦修与虔敬运动。随着它的成熟，思想家们开始阐明实践背后的理论：自我如何被净化，以及若神秘者能在世界中找到真主，世界本身应当是什么。"},"reasoning":{"en":"Reason works by concepts that divide and limit, so it cannot grasp an infinite God; only a purified heart can receive that knowledge. And if God is the only true being, everything else exists only as a mirror in which God’s names are shown.","zh":"理性借助区分与限定的概念运作，因而无法把握无限的真主；唯有被净化的心灵能接受这种知识。而如果真主是唯一真实的存在，其余一切就只是映现真主诸名的镜子。"},"claims":[{"en":"Direct experiential knowledge surpasses rational proof.","zh":"直接的体验之知胜过理性证明。"},{"en":"The self must die to itself to find God.","zh":"自我必须“寂灭”于自身，才能找到真主。"},{"en":"Creation is God’s self-disclosure in many forms.","zh":"受造世界是真主以多种形式的自我显现。"}],"legacy":{"en":"It shaped Persian, Turkish and Urdu poetry and the later Islamic philosophy of Mullā Ṣadrā; the term “unity of being” (waḥdat al-wujūd) was attached to Ibn ʿArabī’s thought by later followers and critics.","zh":"它塑造了波斯语、土耳其语和乌尔都语诗歌，也影响了穆拉·萨德拉等后期伊斯兰哲学；“存在单一论”这一说法是后来的追随者与批评者加给伊本·阿拉比思想的。"},"works":[{"by":"al-ghazali","t":{"en":"Deliverance from Error","zh":"《摆脱迷误》"},"y":1108},{"by":"ibn-arabi","t":{"en":"The Bezels of Wisdom (Fuṣūṣ al-Ḥikam)","zh":"《智慧的珍宝》"},"y":1229},{"by":"rumi","t":{"en":"Masnavi","zh":"《玛斯纳维》"},"y":1273}],"figures":["ibn-arabi","rumi","al-ghazali"],"tags":"sufism mysticism ibn arabi rumi unity of being wahdat al-wujud fana unveiling 苏非 神秘主义 伊本·阿拉比 鲁米 存在单一论 寂灭","wiki":"Sufi metaphysics"},
  {"id":"illuminationism","tradition":"islamic","start":1186,"end":2026,"dates":{"en":"1186 – present","zh":"1186年至今"},"name":{"en":"Illuminationism & Transcendent Theosophy","zh":"照明学派与超验神智学"},"branches":["metaphysics","epistemology","mind"],"idea":{"en":"Reality is a gradation of light (Suhrawardī), or of existence itself (Mullā Ṣadrā), and the most basic knowledge is the self’s direct presence to itself.","zh":"实在是光的等级（苏赫拉瓦迪），或存在本身的等级（穆拉·萨德拉）；最基本的知识是自我对自身的直接临在。"},"question":{"en":"What is most real, and how do we know it without concepts?","zh":"什么最真实？我们如何不借概念认识它？"},"origin":{"en":"By the 12th century Avicenna’s system dominated philosophy in Persia, but its definitions and its account of knowledge as abstraction left some unsatisfied. Suhrawardī turned to Plato and ancient Persian wisdom; four centuries later in Safavid Iran, Mullā Ṣadrā combined Avicenna, Suhrawardī and Ibn ʿArabī.","zh":"到12世纪，阿维森纳的体系主导了波斯的哲学，但它的定义方法以及把知识理解为抽象的说法，令一些人不满。苏赫拉瓦迪转向柏拉图与古波斯智慧；四百年后，萨法维王朝的穆拉·萨德拉把阿维森纳、苏赫拉瓦迪与伊本·阿拉比融为一体。"},"reasoning":{"en":"I know myself not through a concept of myself but by my own presence, so knowledge by presence comes before knowledge by representation. Mullā Ṣadrā went further: existence, not essence, is what is real, it comes in degrees, and things constantly change in their very substance.","zh":"我认识自己，不是通过关于自己的概念，而是凭借我自身的临在，所以“临在之知”先于“表象之知”。穆拉·萨德拉更进一步：真实的是存在而非本质；存在有强弱等级，事物在其实体本身中不断运动。"},"claims":[{"en":"Self-knowledge is direct presence, not representation.","zh":"自我认识是直接临在，而非表象。"},{"en":"Existence, not essence, is fundamentally real (Ṣadrā).","zh":"根本真实的是存在而非本质（萨德拉）。"},{"en":"Reality differs only by degrees of intensity.","zh":"实在之间只有强度等级的差别。"}],"legacy":{"en":"Ṣadrā’s philosophy is still taught in Iranian seminaries and remains the main living school of Islamic philosophy.","zh":"萨德拉的哲学至今仍在伊朗的经学院中讲授，是伊斯兰哲学中最主要的活传统。"},"works":[{"by":"suhrawardi","t":{"en":"The Philosophy of Illumination (Ḥikmat al-Ishrāq)","zh":"《照明哲学》"},"y":1186},{"by":"mulla-sadra","t":{"en":"The Four Journeys (al-Asfār al-Arbaʿa)","zh":"《心灵四旅》"},"y":1628}],"figures":["suhrawardi","mulla-sadra"],"tags":"illuminationism ishraq suhrawardi mulla sadra transcendent theosophy primacy of existence substantial motion light 照明学派 苏赫拉瓦迪 穆拉·萨德拉 存在优先 实体运动 光","wiki":"Illuminationism"},
  {"id":"patristic","tradition":"medieval","start":150,"end":750,"dates":{"en":"c. 2nd – 8th c. CE","zh":"约公元2–8世纪"},"name":{"en":"Patristic & Augustinian philosophy","zh":"教父哲学与奥古斯丁主义"},"branches":["religion","metaphysics","ethics"],"idea":{"en":"Christian faith can be understood with the tools of Greek philosophy, above all Platonism: God is the eternal Good, and evil is a lack of good.","zh":"可以借助希腊哲学，尤其是柏拉图主义，来理解基督教信仰：上帝是永恒的至善，恶只是善的缺乏。"},"question":{"en":"How can revealed faith and pagan reason be reconciled?","zh":"启示的信仰与异教的理性如何调和？"},"origin":{"en":"As Christianity spread through an educated Roman world, its teachers had to defend it against pagan critics and settle disputes about God, Christ and evil. The philosophical language at hand was Greek, especially the Platonism of Plotinus and Porphyry.","zh":"基督教在受过教育的罗马世界中传播，教父们必须回应异教批评者，并解决关于上帝、基督与恶的争论。当时可用的哲学语言是希腊的，尤其是普罗提诺与波菲利的柏拉图主义。"},"reasoning":{"en":"If God is wholly good and created everything, evil cannot be a substance in its own right; it must be a privation, a good thing turned away from its source by a free will. Truth, unchanging and shared by all minds, points beyond the mind to God, who illuminates it.","zh":"如果上帝全善且创造万物，恶就不可能是独立的实体，只能是一种缺失：好的事物因自由意志而背离了源头。真理不变且为所有心灵共有，这指向心灵之外的上帝，是祂照亮了心灵。"},"claims":[{"en":"Evil is the privation of good, not a thing in itself.","zh":"恶是善的缺乏，而非自身存在之物。"},{"en":"Faith comes first, and understanding follows from it.","zh":"信仰在先，理解随后。"},{"en":"God sees all of time at once, in an eternal present.","zh":"上帝在永恒的当下一眼看尽全部时间。"}],"legacy":{"en":"Augustine shaped Latin theology, the medieval idea of the self and later debates on grace and will; Boethius handed Aristotle’s logic to the Latin Middle Ages.","zh":"奥古斯丁塑造了拉丁神学、中世纪的自我观念，以及后世关于恩典与意志的争论；波爱修斯把亚里士多德的逻辑交给了拉丁中世纪。"},"works":[{"by":"augustine","t":{"en":"Confessions","zh":"《忏悔录》"},"y":400},{"by":"augustine","t":{"en":"The City of God","zh":"《上帝之城》"},"y":426},{"by":"boethius","t":{"en":"The Consolation of Philosophy","zh":"《哲学的慰藉》"},"y":524}],"figures":["augustine","boethius"],"tags":"church fathers augustine boethius privation evil grace illumination 教父 奥古斯丁 波爱修斯 恶 恩典 光照","wiki":"Augustinianism"},
  {"id":"jewish-medieval","tradition":"medieval","start":900,"end":1400,"dates":{"en":"c. 900 – 15th c.","zh":"约900年–15世纪"},"name":{"en":"Medieval Jewish philosophy","zh":"中世纪犹太哲学"},"branches":["religion","metaphysics","ethics"],"idea":{"en":"The Torah, rightly read, agrees with demonstrated reason; much of its language about God is figurative, because God is beyond all human description.","zh":"正确理解的《托拉》与经过证明的理性相一致；经文中许多描述上帝的语言是比喻性的，因为上帝超出一切人类描述。"},"question":{"en":"How should a believer read scripture in light of philosophy?","zh":"信徒该如何借哲学之光来阅读经典？"},"origin":{"en":"Jewish communities living in the Islamic world wrote in Arabic and shared its intellectual life. Challenged by Muslim theologians, Karaites, sceptics and Aristotelian science, rabbis set out to show that Jewish belief was rational.","zh":"生活在伊斯兰世界的犹太社群用阿拉伯语写作，共享那里的思想生活。面对穆斯林神学家、卡拉派、怀疑论者和亚里士多德科学的挑战，拉比们着手证明犹太信仰是合乎理性的。"},"reasoning":{"en":"God is one and incorporeal, so biblical phrases about God’s hand or anger cannot be literal. The safest way to speak of God is negatively, saying what God is not; where reason cannot decide, as on whether the world is eternal, scripture may.","zh":"上帝是独一且无形体的，所以《圣经》中关于上帝之手或上帝之怒的说法不可能是字面意义。谈论上帝最稳妥的方式是否定式的，即说上帝不是什么；在理性无法裁决的地方，比如世界是否永恒，可以由经典来决定。"},"claims":[{"en":"Reason and revelation, properly understood, agree.","zh":"正确理解的理性与启示彼此一致。"},{"en":"We can say only what God is not.","zh":"我们只能说上帝不是什么。"},{"en":"Scripture’s bodily language about God is figurative.","zh":"经文对上帝的形体化描述是比喻。"}],"legacy":{"en":"Maimonides became a standard authority in Jewish law and thought, and Latin scholastics, including Aquinas, read him closely.","zh":"迈蒙尼德成为犹太律法与思想的标准权威，包括阿奎那在内的拉丁经院学者也细读他的著作。"},"works":[{"by":"saadia","t":{"en":"The Book of Beliefs and Opinions","zh":"《信仰与见解之书》"},"y":933},{"by":"maimonides","t":{"en":"Mishneh Torah","zh":"《重述托拉》"},"y":1180},{"by":"maimonides","t":{"en":"The Guide for the Perplexed","zh":"《迷途指津》"},"y":1190}],"figures":["saadia","maimonides"],"tags":"jewish philosophy saadia maimonides guide negative theology torah 犹太哲学 萨阿迪亚 迈蒙尼德 迷途指津 否定神学","wiki":"Jewish philosophy"},
  {"id":"scholasticism","tradition":"medieval","start":1070,"end":1620,"dates":{"en":"c. 1070 – early 17th c.","zh":"约1070年–17世纪初"},"name":{"en":"Scholasticism","zh":"经院哲学"},"branches":["religion","metaphysics","logic"],"idea":{"en":"Reason, trained by Aristotle’s logic, can prove much of what faith believes and clarify the rest, because truth cannot contradict truth.","zh":"经亚里士多德逻辑训练的理性，能证明信仰所信的许多内容并澄清其余部分，因为真理不会与真理相矛盾。"},"question":{"en":"How far can reason go in understanding what faith holds?","zh":"理性在理解信仰时能走多远？"},"origin":{"en":"Cathedral schools and then the new universities of Paris and Oxford needed a method for teaching theology. From the 12th century, Latin translations of Aristotle and of Arabic and Jewish philosophers arrived, and scholars had to fit this powerful pagan system into Christian doctrine.","zh":"主教座堂学校以及后来的巴黎、牛津等新兴大学需要一套讲授神学的方法。12世纪起，亚里士多德以及阿拉伯与犹太哲学家的拉丁译本陆续传入，学者们必须把这套强大的异教体系纳入基督教教义。"},"reasoning":{"en":"God is the author of both nature and scripture, so what reason demonstrates and what revelation teaches must agree. The way to resolve apparent conflicts is the disputation: state the objections, give the authorities, then distinguish senses until the contradiction disappears.","zh":"上帝既是自然的作者，也是经典的作者，因此理性所证明的与启示所教导的必然一致。化解表面冲突的方法是论辩：先列出反对意见，再引用权威，然后区分不同含义，直到矛盾消失。"},"claims":[{"en":"Faith and reason are distinct but cannot truly conflict.","zh":"信仰与理性彼此有别，但不会真正冲突。"},{"en":"God’s existence can be shown by argument.","zh":"上帝的存在可以通过论证来说明。"},{"en":"Hard questions are settled by disputation and careful distinctions.","zh":"难题通过论辩与细致的区分来解决。"}],"legacy":{"en":"It created the university disputation and much of Western philosophical vocabulary; Thomism was revived in the 19th century and is still taught.","zh":"它创立了大学论辩制度和西方哲学的大量术语；托马斯主义在19世纪复兴，至今仍有传授。"},"works":[{"by":"anselm","t":{"en":"Proslogion","zh":"《宣讲》"},"y":1078},{"by":"abelard","t":{"en":"Sic et Non (Yes and No)","zh":"《是与否》"},"y":1121},{"by":"aquinas","t":{"en":"Summa Theologiae","zh":"《神学大全》"},"y":1273},{"by":"duns-scotus","t":{"en":"Ordinatio","zh":"《〈箴言集〉评注》"},"y":1300}],"figures":["anselm","abelard","aquinas","duns-scotus"],"tags":"scholastic schoolmen disputation summa thomism universities faith reason 经院 托马斯主义 论辩 大全 信仰 理性","wiki":"Scholasticism"},
  {"id":"latin-averroism","tradition":"medieval","start":1260,"end":1600,"dates":{"en":"c. 1260 – 16th c.","zh":"约1260年–16世纪"},"name":{"en":"Latin Averroism","zh":"拉丁阿威罗伊主义"},"branches":["mind","metaphysics","religion"],"idea":{"en":"Philosophy should follow Aristotle as read by Averroes wherever the argument leads, even to conclusions that contradict Christian doctrine.","zh":"哲学应当沿着阿威罗伊所解读的亚里士多德一路推论下去，即使结论与基督教教义相冲突。"},"question":{"en":"What should a philosopher do when reason contradicts faith?","zh":"当理性与信仰相冲突时，哲学家该怎么办？"},"origin":{"en":"In the arts faculty at Paris in the 1260s, masters teaching Aristotle with Averroes’ commentaries found that the text seemed to imply an eternal world and a single intellect shared by all humans. Their bishops and the theologians took alarm.","zh":"13世纪60年代，巴黎大学艺学院的教师借助阿威罗伊的评注讲授亚里士多德，发现文本似乎蕴含着世界永恒、全人类共享同一个理智等结论，这引起了主教与神学家的警觉。"},"reasoning":{"en":"If the intellect knows universals, it cannot be a bodily, individual faculty; so, following Averroes, there is one separate intellect in which all humans share. A philosopher’s task is to report what follows from Aristotle’s principles, while holding by faith what the Church teaches.","zh":"如果理智认识的是共相，它就不可能是有形的、个别的官能；因此按照阿威罗伊的看法，只有一个分离的理智，所有人共同分有。哲学家的任务是报告从亚里士多德原理中推出什么，而以信仰持守教会的教导。"},"claims":[{"en":"All humans share one separate intellect.","zh":"全人类共享同一个分离的理智。"},{"en":"By natural reason, the world has no beginning.","zh":"按自然理性，世界没有开端。"},{"en":"Philosophy may reach conclusions faith rejects.","zh":"哲学可以得出信仰所拒绝的结论。"}],"legacy":{"en":"It provoked the Paris condemnations of 1270 and 1277; opponents accused it of a “double truth”, a label its masters did not use. Averroist Aristotelianism lasted at Padua into the 16th century.","zh":"它引发了1270年和1277年的巴黎禁令；论敌指责它主张“双重真理”，但这些教师本人并未使用这一说法。阿威罗伊式的亚里士多德主义在帕多瓦一直延续到16世纪。"},"works":[{"by":"siger","t":{"en":"On the Intellective Soul","zh":"《论理智灵魂》"},"y":1272},{"by":"aquinas","t":{"en":"On the Unity of the Intellect against the Averroists","zh":"《论理智的单一性：驳阿威罗伊主义者》"},"y":1270}],"figures":["siger"],"tags":"averroism averroes siger brabant unity of the intellect condemnation 1277 double truth padua 阿威罗伊 西格尔 理智单一 禁令 双重真理 帕多瓦","wiki":"Averroism"},
  {"id":"nominalism","tradition":"medieval","start":1320,"end":1500,"dates":{"en":"c. 1320 – 15th c.","zh":"约1320年–15世纪"},"name":{"en":"Late-medieval nominalism","zh":"中世纪晚期唯名论"},"branches":["metaphysics","logic","epistemology"],"idea":{"en":"Only individual things exist; universals like “humanity” are signs in the mind and in language, not real natures shared by things.","zh":"只有个别事物存在；“人性”之类的共相只是心灵与语言中的符号，而不是事物共有的实在本性。"},"question":{"en":"Do universals exist outside the mind?","zh":"共相存在于心灵之外吗？"},"origin":{"en":"By 1300 scholastic metaphysics had multiplied entities: common natures, formal distinctions, intelligible species. Theologians who stressed God’s absolute freedom also distrusted claims that creatures share necessary essences.","zh":"到1300年前后，经院形而上学设定的实体越来越多：共同本性、形式区分、可理解的种相等等。强调上帝绝对自由的神学家，也不信任“受造物共享必然本质”这类说法。"},"reasoning":{"en":"Whatever exists is individual, and a thing cannot be both one and in many places at once, so a universal cannot be a thing. We explain general knowledge more simply by concepts that signify many individuals, and we should not posit entities beyond necessity.","zh":"凡存在者都是个别的，一个东西不可能同时是一个又存在于许多地方，所以共相不可能是一个东西。用“指称许多个体的概念”来解释普遍知识更为简单，而如无必要，勿增实体。"},"claims":[{"en":"Only individuals exist.","zh":"只有个体存在。"},{"en":"Universals are concepts or words that signify many things.","zh":"共相是指称多个事物的概念或语词。"},{"en":"Do not multiply entities beyond necessity.","zh":"如无必要，勿增实体。"}],"legacy":{"en":"The “modern way” (via moderna) dominated many universities, sharpened logic and semantics, and prepared ground for early modern empiricism and science.","zh":"这条“现代路线”在许多大学占据主导，推进了逻辑与语义学，也为近代经验论与科学铺了路。"},"works":[{"by":"ockham","t":{"en":"Summa Logicae","zh":"《逻辑大全》"},"y":1323},{"by":"buridan","t":{"en":"Summulae de Dialectica","zh":"《辩证法纲要》"},"y":1340}],"figures":["ockham","buridan"],"tags":"nominalism universals ockham razor via moderna terminism 唯名论 共相 奥卡姆剃刀 现代路线","wiki":"Nominalism"},
  {"id":"renaissance","tradition":"modern","start":1350,"end":1600,"dates":{"en":"c. 1350–1600","zh":"约1350–1600年"},"name":{"en":"Renaissance humanism","zh":"文艺复兴人文主义"},"branches":["ethics","politics","epistemology"],"idea":{"en":"The recovered classics of Greece and Rome show what human beings can become, so learning should centre on human life, language and civic action.","zh":"重新发现的希腊罗马经典昭示了人的可能，因此学问应当以人的生活、语言与公共行动为中心。"},"question":{"en":"What can human beings make of themselves?","zh":"人能把自己造就成什么？"},"origin":{"en":"In fourteenth- and fifteenth-century Italy, rich city-states, the hunt for lost classical manuscripts and Greek scholars arriving from Byzantium gave readers direct access to Plato, Cicero and the ancient historians. Many found late scholastic philosophy narrow and technical, and wanted a learning that would train citizens, preachers and princes.","zh":"十四、十五世纪的意大利，富庶的城邦、搜寻失传古典手稿的热潮，以及从拜占庭来的希腊学者，让人们得以直接阅读柏拉图、西塞罗和古代史家。许多人觉得晚期经院哲学狭隘而琐细，希望有一种能够培养公民、布道者与君主的学问。"},"reasoning":{"en":"If the ancients reached such heights of eloquence, virtue and statecraft without Christian revelation, then human nature itself must be capable of greatness. The way to cultivate it is the studia humanitatis — grammar, rhetoric, history, poetry and moral philosophy — read in the original texts rather than through layers of commentary.","zh":"既然古人在没有基督教启示的情况下，已在雄辩、德性与治国上达到如此高度，那么人性本身必定蕴含伟大的可能。培养它的途径是“人文学科”——语法、修辞、历史、诗歌与道德哲学——而且要读原典，而不是隔着层层注疏去读。"},"claims":[{"en":"Return to the ancient sources themselves, not later commentaries.","zh":"回到古代原典本身，而不是后人的注疏。"},{"en":"Human dignity lies in our freedom to shape ourselves.","zh":"人的尊严在于能够自由地塑造自己。"},{"en":"Morals and politics are learned from history and experience.","zh":"道德与政治要从历史和经验中学习。"}],"legacy":{"en":"Its return to original sources fed the Reformation and modern textual scholarship, while Montaigne’s doubt and Machiavelli’s realism set the problems that Descartes and Hobbes took up.","zh":"它“回到原典”的精神滋养了宗教改革和近代文献学；蒙田的怀疑与马基雅维利的现实主义，则为笛卡尔和霍布斯留下了要回答的问题。"},"works":[{"by":"pico","t":{"en":"Oration on the Dignity of Man","zh":"《论人的尊严》"},"y":1486},{"by":"erasmus","t":{"en":"The Praise of Folly","zh":"《愚人颂》"},"y":1511},{"by":"machiavelli","t":{"en":"The Prince","zh":"《君主论》"},"y":1513},{"by":"montaigne","t":{"en":"Essays","zh":"《随笔集》"},"y":1580}],"figures":["pico","erasmus","machiavelli","montaigne"],"tags":"humanism renaissance studia humanitatis dignity petrarch ficino ad fontes 人文主义 文艺复兴 人的尊严 回到本源","wiki":"Renaissance humanism"},
  {"id":"empiricism","tradition":"modern","start":1620,"end":1776,"dates":{"en":"1620 – 1776","zh":"1620–1776年"},"name":{"en":"British empiricism","zh":"英国经验主义"},"branches":["epistemology","mind","metaphysics"],"idea":{"en":"All our ideas and knowledge come from experience, so claims that reach beyond any possible experience deserve doubt.","zh":"我们的一切观念和知识都来自经验，因此超出一切可能经验的主张都值得怀疑。"},"question":{"en":"Where do our ideas come from, and how far can they reach?","zh":"我们的观念从何而来，又能走多远？"},"origin":{"en":"Francis Bacon called for a new science built on observation and experiment rather than Aristotelian syllogism, and the Royal Society put that programme into practice. Locke, a physician and friend of the chemist Robert Boyle, wanted to map the limits of human understanding before people argued over questions it could not settle.","zh":"弗朗西斯·培根呼吁以观察和实验而非亚里士多德式三段论来建立新科学，英国皇家学会把这一纲领付诸实践。洛克是医生，也是化学家波义耳的朋友，他想先弄清人类理解力的界限，免得人们为它根本无法解决的问题争论不休。"},"reasoning":{"en":"Trace any idea in the mind and it leads back to sensation or to reflection on our own mental operations; there is no evidence of ideas present at birth. If so, knowledge can reach only as far as experience goes. Hume pushed this to the end: since we never perceive a necessary connection between cause and effect, our belief in causation rests on habit, not reason.","zh":"追溯心中任何一个观念，最终都会回到感觉，或回到对自身心理活动的反省；没有证据表明有生来就有的观念。既然如此，知识只能延伸到经验所及之处。休谟把这一思路推到尽头：我们从未知觉到因果之间的必然联系，所以对因果的信念依靠的是习惯，而不是理性。"},"claims":[{"en":"The mind begins as a blank slate, furnished by experience.","zh":"心灵起初是一块白板，由经验来填充。"},{"en":"An idea has meaning only if it traces back to experience.","zh":"一个观念只有能追溯到经验才有意义。"},{"en":"Causal necessity is never perceived; it is a habit of expectation.","zh":"因果必然性从未被知觉到，它只是一种预期的习惯。"}],"legacy":{"en":"It shaped scientific method and modern psychology, inspired the Enlightenment, and through Hume’s skepticism woke Kant and later fed logical positivism.","zh":"它塑造了科学方法与近代心理学，启发了启蒙运动；休谟的怀疑论惊醒了康德，后来又滋养了逻辑实证主义。"},"works":[{"by":"bacon","t":{"en":"Novum Organum","zh":"《新工具》"},"y":1620},{"by":"locke","t":{"en":"An Essay Concerning Human Understanding","zh":"《人类理解论》"},"y":1689},{"by":"berkeley","t":{"en":"A Treatise Concerning the Principles of Human Knowledge","zh":"《人类知识原理》"},"y":1710},{"by":"hume","t":{"en":"A Treatise of Human Nature","zh":"《人性论》"},"y":1739}],"figures":["bacon","locke","berkeley","hume"],"tags":"empiricism experience tabula rasa blank slate induction causation idea impression 经验主义 经验论 白板 归纳 因果 观念 印象","wiki":"British empiricism"},
  {"id":"rationalism","tradition":"modern","start":1637,"end":1750,"dates":{"en":"1637 – mid-18th c.","zh":"1637年–18世纪中叶"},"name":{"en":"Rationalism","zh":"理性主义（唯理论）"},"branches":["metaphysics","epistemology","mind"],"idea":{"en":"Reason alone, reasoning from clear and certain first principles as geometry does, can reveal the basic structure of reality.","zh":"单凭理性，像几何学那样从清楚而确定的第一原理出发进行推理，就能揭示实在的基本结构。"},"question":{"en":"Can reason alone give us certain knowledge of the world?","zh":"单凭理性，能否获得关于世界的确定知识？"},"origin":{"en":"The new science of Galileo and Kepler was undermining Aristotle’s physics, and the revival of ancient skepticism made many doubt that anything could be known for sure. Descartes set out to rebuild knowledge on a foundation that no doubt could shake, taking mathematics as the model of certainty.","zh":"伽利略和开普勒的新科学正在动摇亚里士多德的物理学，古代怀疑论的复兴又让许多人怀疑人究竟能否确知任何事。笛卡尔决心把知识重建在任何怀疑都无法动摇的基础上，并以数学作为确定性的典范。"},"reasoning":{"en":"The senses sometimes deceive us, so knowledge built on them alone cannot be certain. Yet some truths — that I think, that I exist, the axioms of mathematics — are grasped by reason with a clarity that resists all doubt. From such innate or self-evident principles, careful deduction can reach truths about mind, God and nature.","zh":"感官有时会欺骗我们，所以仅建立在感官上的知识不可能确定。但有些真理——我在思考、我存在、数学公理——理性以抗拒一切怀疑的清晰性把握到它们。从这些天赋的或自明的原理出发，经过严谨推演，就能获得关于心灵、上帝与自然的真理。"},"claims":[{"en":"Some ideas are innate, not learned from experience.","zh":"有些观念是天赋的，而不是从经验中学来的。"},{"en":"Clear and distinct reasoning, modelled on geometry, yields certainty.","zh":"以几何学为范本的清楚分明的推理能带来确定性。"},{"en":"Reality is rationally ordered: nothing happens without a reason.","zh":"实在具有理性秩序：没有什么事情是没有理由的。"}],"legacy":{"en":"Rationalism set the agenda of modern philosophy — the mind–body problem, the foundations of knowledge — and its clash with empiricism is what Kant tried to resolve.","zh":"理性主义为近代哲学设定了议程——心身问题、知识的基础——它与经验主义的冲突，正是康德试图化解的难题。"},"works":[{"by":"descartes","t":{"en":"Meditations on First Philosophy","zh":"《第一哲学沉思集》"},"y":1641},{"by":"spinoza","t":{"en":"Ethics","zh":"《伦理学》"},"y":1677},{"by":"leibniz","t":{"en":"Monadology","zh":"《单子论》"},"y":1714}],"figures":["descartes","spinoza","leibniz"],"tags":"rationalism cogito innate ideas reason deduction substance monad sufficient reason 理性主义 唯理论 我思 天赋观念 实体 单子 充足理由律","wiki":"Rationalism"},
  {"id":"social-contract","tradition":"modern","start":1642,"end":1790,"dates":{"en":"1642 – late 18th c.","zh":"1642年–18世纪末"},"name":{"en":"Social contract theory","zh":"社会契约论"},"branches":["politics","ethics"],"idea":{"en":"Political authority is legitimate only because free and equal individuals would agree, or have agreed, to create it.","zh":"政治权威之所以正当，只是因为自由而平等的个人会同意或已经同意建立它。"},"question":{"en":"Why should anyone obey the state?","zh":"人为什么应当服从国家？"},"origin":{"en":"Seventeenth-century Europe was torn by wars of religion and England by civil war, and the old answer — that kings rule by divine right — was itself in dispute. Hobbes, writing amid that civil war, sought a foundation for government that did not depend on contested theology.","zh":"十七世纪的欧洲饱受宗教战争撕裂，英国陷入内战，而“君权神授”这一旧答案本身也成了争议焦点。霍布斯在内战中写作，想为政府找到一个不依赖于充满争议的神学的基础。"},"reasoning":{"en":"Imagine people with no government at all, in a “state of nature”. Hobbes argued such a life would be insecure and violent, so rational people would agree to hand power to a sovereign who keeps the peace. Locke and Rousseau kept the method but changed the terms: if authority comes from the people’s consent, it is limited by what they could reasonably agree to.","zh":"设想人们处在完全没有政府的“自然状态”中。霍布斯认为那样的生活不安全而充满暴力，所以理性的人会同意把权力交给一个维持和平的主权者。洛克和卢梭沿用这一方法，却改变了条款：既然权威来自人民的同意，它就受限于人们能够合理同意的范围。"},"claims":[{"en":"No one is born with a natural right to rule others.","zh":"没有人生来就拥有统治他人的自然权利。"},{"en":"Legitimate government rests on the consent of the governed.","zh":"正当的政府建立在被统治者的同意之上。"},{"en":"For Locke, rulers who betray their trust may be resisted.","zh":"在洛克看来，背弃信托的统治者可以被反抗。"}],"legacy":{"en":"Its language of consent, natural rights and popular sovereignty shaped the American and French revolutions, and John Rawls revived its method in 1971.","zh":"它关于同意、自然权利与人民主权的语言塑造了美国革命和法国大革命；1971年，罗尔斯又复兴了它的方法。"},"works":[{"by":"hobbes","t":{"en":"Leviathan","zh":"《利维坦》"},"y":1651},{"by":"locke","t":{"en":"Two Treatises of Government","zh":"《政府论》"},"y":1689},{"by":"rousseau","t":{"en":"The Social Contract","zh":"《社会契约论》"},"y":1762}],"figures":["hobbes","locke","rousseau"],"tags":"social contract state of nature consent sovereignty natural rights general will leviathan 社会契约 自然状态 同意 主权 自然权利 公意 利维坦","wiki":"Social contract"},
  {"id":"enlightenment","tradition":"modern","start":1685,"end":1800,"dates":{"en":"c. 1685–1800","zh":"约1685–1800年"},"name":{"en":"The Enlightenment","zh":"启蒙运动"},"branches":["politics","religion","ethics"],"idea":{"en":"Human reason, freely and publicly used, can criticise tradition and authority and make human life better.","zh":"人的理性一旦被自由而公开地运用，就能批判传统与权威，并改善人类的生活。"},"question":{"en":"Can reason free humanity from superstition and tyranny?","zh":"理性能否让人类摆脱迷信与暴政？"},"origin":{"en":"Newton’s physics seemed to show that the universe obeys knowable laws, and Locke’s philosophy that the mind is formed by experience and education. In eighteenth-century France, Britain and beyond, writers in salons, coffee houses and a growing press turned these ideas against censorship, religious persecution and absolute monarchy.","zh":"牛顿的物理学似乎表明宇宙遵循可知的规律，洛克的哲学则表明心灵由经验和教育塑造。十八世纪的法国、英国及其他地方，作家们在沙龙、咖啡馆和日益壮大的出版界，把这些思想用来对抗审查、宗教迫害与绝对君主制。"},"reasoning":{"en":"If nature runs on discoverable laws, so may society, morals and government; customs that cannot justify themselves before reason have no claim to obedience. And if people are shaped by their surroundings rather than born corrupt, better laws, education and knowledge can make them freer and happier.","zh":"如果自然遵循可以发现的规律，那么社会、道德与政府也可能如此；无法在理性面前为自己辩护的习俗，就无权要求人们服从。而如果人是由环境塑造的，而非生来败坏，那么更好的法律、教育与知识就能让人更自由、更幸福。"},"claims":[{"en":"Knowledge should be gathered, organised and shared with everyone.","zh":"知识应当被汇集、整理，并与所有人分享。"},{"en":"Religious toleration and free expression are essential to a decent society.","zh":"宗教宽容与言论自由是良好社会所必需的。"},{"en":"Power is safest when divided so that power checks power.","zh":"权力分立、以权力制约权力，才最安全。"}],"legacy":{"en":"It left the ideals of human rights, toleration, separation of powers and progress through science — and the long line of critiques, from Romanticism to the Frankfurt School, of what its reason overlooked.","zh":"它留下了人权、宽容、三权分立和以科学促进步的理想；也引来了从浪漫主义到法兰克福学派的一长串批判，指出这种理性所忽视的东西。"},"works":[{"by":"montesquieu","t":{"en":"The Spirit of the Laws","zh":"《论法的精神》"},"y":1748},{"by":"diderot","t":{"en":"Encyclopédie (with d’Alembert)","zh":"《百科全书》（与达朗贝尔合编）"},"y":1751},{"by":"voltaire","t":{"en":"Candide","zh":"《老实人》"},"y":1759},{"by":"adam-smith","t":{"en":"The Wealth of Nations","zh":"《国富论》"},"y":1776}],"figures":["montesquieu","voltaire","diderot","adam-smith"],"tags":"enlightenment lumieres aufklarung reason tolerance encyclopedie progress separation of powers philosophes 启蒙运动 理性 宽容 百科全书 进步 三权分立","wiki":"Age of Enlightenment"},
  {"id":"kantianism","tradition":"modern","start":1781,"end":1930,"dates":{"en":"1781 – c. 1930 (Neo-Kantianism)","zh":"1781年–约1930年（含新康德主义）"},"name":{"en":"Kant’s critical philosophy","zh":"康德批判哲学"},"branches":["epistemology","metaphysics","ethics"],"idea":{"en":"Our minds do not passively copy the world: space, time and concepts such as cause are forms we bring to all experience.","zh":"心灵并非被动地复制世界：空间、时间以及因果等概念，是我们带给一切经验的形式。"},"question":{"en":"What can I know? What ought I to do? What may I hope?","zh":"我能知道什么？我应当做什么？我可以希望什么？"},"origin":{"en":"By the 1770s rationalist metaphysics seemed to produce endless unresolved disputes, while Hume’s empiricism threatened to dissolve causation and with it the certainty of Newtonian science. Kant, trained in the Leibniz–Wolff school, said Hume had woken him from his “dogmatic slumber”, and set out to examine the powers and limits of reason itself.","zh":"到了1770年代，理性主义形而上学似乎只会制造无休止的争论，而休谟的经验主义则可能瓦解因果性，连带瓦解牛顿科学的确定性。受莱布尼茨—沃尔夫学派训练的康德说，是休谟把他从“独断论的迷梦”中唤醒，于是他着手考察理性本身的能力与界限。"},"reasoning":{"en":"We have knowledge that is both necessary and about the world — in geometry, and in the principle that every event has a cause — yet experience can never show necessity. Kant concluded that such knowledge is possible only because the mind supplies the forms through which anything can appear to us; the price is that we know things only as they appear, never as they are in themselves.","zh":"我们拥有既必然又关于世界的知识——几何学，以及“凡事皆有原因”的原理——可经验永远无法证明必然性。康德的结论是：这种知识之所以可能，只因为心灵提供了任何事物得以向我们显现的形式；代价是，我们只能认识事物的显现，永远无法认识物自体。"},"claims":[{"en":"Experience is shaped by forms the mind contributes a priori.","zh":"经验由心灵先天提供的形式所塑造。"},{"en":"We know appearances, never things as they are in themselves.","zh":"我们认识的是现象，而不是物自体。"},{"en":"Morality is a law of reason: treat persons always as ends.","zh":"道德是理性的法则：始终把人当作目的。"}],"legacy":{"en":"Kant’s “Copernican revolution” framed nearly all later philosophy: German idealism grew from it, Neo-Kantians led German universities until about 1930, and Kantian ethics underlies modern ideas of human dignity.","zh":"康德的“哥白尼式革命”几乎为此后所有哲学设定了框架：德国观念论由它生长而出，新康德主义者直到约1930年仍主导德国大学，康德伦理学则奠定了现代人性尊严观念的基础。"},"works":[{"by":"kant","t":{"en":"Critique of Pure Reason","zh":"《纯粹理性批判》"},"y":1781},{"by":"kant","t":{"en":"Groundwork of the Metaphysics of Morals","zh":"《道德形而上学奠基》"},"y":1785},{"by":"kant","t":{"en":"Critique of Judgment","zh":"《判断力批判》"},"y":1790}],"figures":["kant"],"tags":"kant critique a priori synthetic categorical imperative transcendental idealism noumenon thing in itself neo-kantianism 康德 批判哲学 先天 先验 绝对命令 物自体 新康德主义","wiki":"Kantianism"},
  {"id":"utilitarianism","tradition":"modern","start":1789,"end":2026,"dates":{"en":"1789 – today","zh":"1789年至今"},"name":{"en":"Utilitarianism","zh":"功利主义"},"branches":["ethics","politics"],"idea":{"en":"The right action is the one that produces the greatest total happiness, with everyone’s happiness counting equally.","zh":"正确的行为就是带来最大总体幸福的行为，而每个人的幸福都同等重要。"},"question":{"en":"What makes an action or a law right?","zh":"是什么让一个行为或一条法律成为正确的？"},"origin":{"en":"Late eighteenth-century Britain had a chaotic legal system full of savage punishments defended by custom and tradition. Bentham, a legal reformer who had read Hume, Helvétius and Beccaria, wanted a single rational test by which every law and institution could be judged.","zh":"十八世纪末的英国法律体系杂乱无章，充斥着以习俗和传统为名的残酷刑罚。读过休谟、爱尔维修和贝卡里亚的法律改革家边沁，想要一个统一而理性的标准，用来检验每一条法律和每一项制度。"},"reasoning":{"en":"Pleasure and pain are what we all, in the end, care about, so the sensible measure of a law or act is its effect on happiness. Since no one’s happiness matters more than anyone else’s, we should add up the consequences for all affected and choose the greatest net good. Mill refined this, holding that some pleasures are higher than others and that liberty itself serves the general good.","zh":"快乐与痛苦是我们归根结底都在乎的东西，所以衡量一条法律或一个行为的合理标准，就是它对幸福的影响。既然没有谁的幸福比别人的更重要，我们就应当把对所有相关者的后果加总，选择净收益最大的那一个。密尔加以修正，认为快乐有高下之分，而自由本身就有助于公共的善。"},"claims":[{"en":"Only consequences matter in judging actions and laws.","zh":"评判行为与法律，只看后果。"},{"en":"Each to count for one, and none for more than one.","zh":"每个人都算作一个，没有人多于一个。"},{"en":"Any being that can suffer deserves moral consideration.","zh":"凡能感受痛苦的存在，都值得道德上的考虑。"}],"legacy":{"en":"It drove reforms of law, prisons, voting and welfare, underlies cost–benefit reasoning in economics and policy, and through Peter Singer inspired the animal-rights and effective-altruism movements.","zh":"它推动了法律、监狱、选举与福利制度的改革，是经济学和公共政策中成本—收益推理的基础，并经由彼得·辛格催生了动物权利运动和有效利他主义运动。"},"works":[{"by":"bentham","t":{"en":"An Introduction to the Principles of Morals and Legislation","zh":"《道德与立法原理导论》"},"y":1789},{"by":"mill","t":{"en":"On Liberty","zh":"《论自由》"},"y":1859},{"by":"mill","t":{"en":"Utilitarianism","zh":"《功利主义》"},"y":1861}],"figures":["bentham","mill","singer"],"tags":"utilitarianism utility greatest happiness consequentialism pleasure hedonism bentham mill singer 功利主义 效用 最大幸福 后果主义 快乐","wiki":"Utilitarianism"},
  {"id":"german-idealism","tradition":"modern","start":1794,"end":1844,"dates":{"en":"1790s – 1840s","zh":"1790年代–1840年代"},"name":{"en":"German Idealism","zh":"德国观念论"},"branches":["metaphysics","epistemology","politics"],"idea":{"en":"Reality is not a heap of dead things but the self-unfolding activity of reason or spirit, which comes to know itself through nature and history.","zh":"实在不是一堆僵死的事物，而是理性或精神自我展开的活动，它通过自然与历史逐步认识自身。"},"question":{"en":"If the mind shapes experience, can it also know the absolute?","zh":"既然心灵塑造经验，它能否也认识绝对者？"},"origin":{"en":"Kant left two gaps: unknowable “things in themselves” behind appearances, and a split between nature ruled by necessity and humans as free moral agents. Young philosophers of the 1790s, stirred by the French Revolution and a revival of interest in Spinoza, set out to close these gaps with a single system grounded in freedom.","zh":"康德留下了两道裂缝：现象背后不可知的“物自体”，以及受必然性支配的自然与作为自由道德主体的人之间的分裂。1790年代的年轻哲学家们受法国大革命鼓舞，又重新燃起对斯宾诺莎的兴趣，决心以一个奠基于自由的统一体系来弥合这些裂缝。"},"reasoning":{"en":"If the thing in itself is unknowable, we have no right even to say it exists; so the forms of thought are not merely ours but the forms of reality. Fichte began from the self’s free activity, Schelling from an absolute in which nature and mind are one, and Hegel argued that reality is a rational process that develops through contradictions, each position revealing its limits and being overcome, until spirit understands itself.","zh":"如果物自体不可知，我们就连说它存在的权利都没有；因此思维的形式不只是我们的，也是实在本身的形式。费希特从自我的自由活动出发，谢林从自然与心灵合一的绝对者出发，黑格尔则主张：实在是一个通过矛盾发展的理性过程，每个立场都暴露出自身的局限而被扬弃，直到精神理解它自己。"},"claims":[{"en":"What is rational is actual, and what is actual is rational.","zh":"凡是合乎理性的都是现实的，凡是现实的都是合乎理性的。"},{"en":"Truth unfolds historically through contradiction and its resolution.","zh":"真理通过矛盾及其解决在历史中展开。"},{"en":"Freedom is realised in social institutions, not in isolated individuals.","zh":"自由在社会制度中实现，而不在孤立的个人身上。"}],"legacy":{"en":"Hegel’s dialectic passed, turned upside down, to Marx, and provoked Kierkegaard and Schopenhauer; British Idealism ruled Oxford until Russell and Moore revolted against it.","zh":"黑格尔的辩证法被马克思“颠倒过来”继承，又激起了克尔凯郭尔和叔本华的反抗；英国观念论曾主导牛津，直到罗素和摩尔起而反叛。"},"works":[{"by":"fichte","t":{"en":"Foundations of the Entire Science of Knowledge","zh":"《全部知识学的基础》"},"y":1794},{"by":"schelling","t":{"en":"System of Transcendental Idealism","zh":"《先验唯心论体系》"},"y":1800},{"by":"hegel","t":{"en":"Phenomenology of Spirit","zh":"《精神现象学》"},"y":1807},{"by":"hegel","t":{"en":"Science of Logic","zh":"《逻辑学》"},"y":1812}],"figures":["fichte","schelling","hegel"],"tags":"german idealism absolute spirit geist dialectic aufhebung hegel fichte schelling 德国观念论 德国唯心主义 绝对精神 辩证法 扬弃","wiki":"German idealism"},
  {"id":"feminism","tradition":"continental","start":1792,"end":2026,"dates":{"en":"1792 – today","zh":"1792年至今"},"name":{"en":"Feminist philosophy","zh":"女性主义哲学"},"branches":["politics","ethics","epistemology"],"idea":{"en":"The subordination of women is not natural but made by society and thought, and philosophy must examine how gender shapes knowledge, ethics and politics.","zh":"女性的从属地位并非天然，而是由社会与思想造成的；哲学必须审视性别如何塑造知识、伦理与政治。"},"question":{"en":"Is the difference between women and men natural, or made?","zh":"男女之间的差别是天生的，还是被造就的？"},"origin":{"en":"Enlightenment thinkers proclaimed universal reason and rights, yet most, Rousseau included, excluded women from both. Wollstonecraft answered in 1792; after women won the vote in many countries, Beauvoir asked in 1949 why woman was still defined as man’s “Other”, and later thinkers questioned the categories of sex and gender themselves.","zh":"启蒙思想家宣称普遍的理性与权利，但包括卢梭在内，大多数人把女性排除在外。1792年，沃斯通克拉夫特作出回应；许多国家的女性获得选举权之后，波伏瓦在1949年追问：为什么女人仍被界定为男人的“他者”？此后的思想家更进一步，质疑“生理性别”与“社会性别”这两个范畴本身。"},"reasoning":{"en":"If reason and rights belong to humans as such, denying them to women needs a justification; Wollstonecraft showed that women’s supposed inferiority was the product of their education. Beauvoir argued that “woman” is a social situation one is made into, not an essence. Butler went further: gender is a performance repeated until it seems natural.","zh":"如果理性与权利属于人本身，那么剥夺女性的这些权利就需要理由；沃斯通克拉夫特指出，所谓女性的低劣，不过是她们所受教育的产物。波伏瓦认为，“女人”是一个人被塑造进去的社会处境，而不是一种本质。巴特勒更进一步：性别是一种不断重复的表演，重复到它看起来像是天然的。"},"claims":[{"en":"Women’s apparent inferiority is a product of education and circumstance.","zh":"女性看似低人一等，是教育与处境的产物。"},{"en":"One is not born, but rather becomes, a woman.","zh":"女人不是天生的，而是后天形成的。"},{"en":"Gender is performative, not a fixed essence.","zh":"性别是述行的，而非固定的本质。"}],"legacy":{"en":"It changed law, ethics, epistemology and political theory, and opened the way for care ethics, standpoint theory and gender studies.","zh":"它改变了法律、伦理学、认识论与政治理论，并为关怀伦理、立场理论和性别研究开辟了道路。"},"works":[{"by":"wollstonecraft","t":{"en":"A Vindication of the Rights of Woman","zh":"《女权辩护》"},"y":1792},{"by":"beauvoir","t":{"en":"The Second Sex","zh":"《第二性》"},"y":1949},{"by":"butler","t":{"en":"Gender Trouble","zh":"《性别麻烦》"},"y":1990}],"figures":["wollstonecraft","beauvoir","butler"],"tags":"feminism gender sex women equality other patriarchy performativity rights 女性主义 女权 性别 平等 他者 父权 述行 权利","wiki":"Feminist philosophy"},
  {"id":"hermeneutics","tradition":"continental","start":1805,"end":2026,"dates":{"en":"c. 1805 – today","zh":"约1805年至今"},"name":{"en":"Hermeneutics","zh":"诠释学"},"branches":["epistemology","logic"],"idea":{"en":"Understanding is interpretation: we grasp texts, people and history by moving between parts and whole, always from within a tradition.","zh":"理解即诠释：我们在部分与整体之间往返，并且总是站在某个传统之内，去理解文本、他人与历史。"},"question":{"en":"What happens when we understand a text, a person or a past?","zh":"当我们理解一段文本、一个人或一段过去时，究竟发生了什么？"},"origin":{"en":"Interpretation began as a craft for reading scripture and law. Schleiermacher, amid the Romantic interest in language and individuality, turned it into a general theory of understanding; Dilthey then used it to argue that the human sciences need their own method, not the methods of physics.","zh":"诠释最初是一门解读经文与法律的技艺。在浪漫主义重视语言与个性的氛围中，施莱尔马赫把它发展为一般的理解理论；狄尔泰随后借此论证：人文科学需要自己的方法，而不是照搬物理学的方法。"},"reasoning":{"en":"We understand a sentence only through the whole text, and the whole only through its sentences: the “hermeneutic circle”. Gadamer added that we never stand outside history; our prejudices are not just errors but the starting point of understanding, which happens as a “fusion of horizons” between our world and the text’s.","zh":"我们只有通过整个文本才能理解一句话，又只有通过一句句话才能理解整体，这就是“诠释学循环”。伽达默尔进一步指出，我们从不站在历史之外；成见不只是错误，也是理解的起点，而理解发生于我们的世界与文本的世界之间的“视域融合”。"},"claims":[{"en":"Parts and whole illuminate each other in the hermeneutic circle.","zh":"部分与整体在诠释学循环中相互照亮。"},{"en":"The human sciences aim at understanding, not causal explanation.","zh":"人文科学追求理解，而非因果说明。"},{"en":"All understanding is shaped by history and tradition.","zh":"一切理解都受历史与传统的塑造。"}],"legacy":{"en":"It reshaped literary theory, theology, law and the social sciences, and underlies debates about whether objectivity is possible in the humanities.","zh":"它重塑了文学理论、神学、法学与社会科学，也是“人文学科能否客观”这一争论的基础。"},"works":[{"by":"schleiermacher","t":{"en":"Hermeneutics and Criticism","zh":"《诠释学与批判》"},"y":1838},{"by":"dilthey","t":{"en":"Introduction to the Human Sciences","zh":"《精神科学引论》"},"y":1883},{"by":"gadamer","t":{"en":"Truth and Method","zh":"《真理与方法》"},"y":1960},{"by":"ricoeur","t":{"en":"Time and Narrative","zh":"《时间与叙事》"},"y":1983}],"figures":["schleiermacher","dilthey","gadamer","ricoeur"],"tags":"interpretation understanding hermeneutic circle fusion of horizons verstehen tradition prejudice text 诠释学 解释学 理解 诠释学循环 视域融合 传统 成见 文本","wiki":"Hermeneutics"},
  {"id":"existentialism","tradition":"continental","start":1843,"end":1980,"dates":{"en":"1840s forerunners; heyday 1940s–1960s","zh":"19世纪40年代发端；20世纪40–60年代鼎盛"},"name":{"en":"Existentialism","zh":"存在主义"},"branches":["ethics","metaphysics"],"idea":{"en":"Existence precedes essence: humans are not born with a fixed nature but make themselves through free choices for which they alone are responsible.","zh":"存在先于本质：人生来没有固定的本性，而是通过自由的选择塑造自己，并独自为此负责。"},"question":{"en":"How should I live if no given nature or order tells me?","zh":"如果没有现成的本性或秩序告诉我，我该如何生活？"},"origin":{"en":"Kierkegaard rebelled against Hegel’s all-embracing system, which he thought left no room for the anxious, choosing individual; Nietzsche announced that “God is dead”. After two world wars, occupation and the Holocaust, French writers such as Sartre, Beauvoir and Camus turned these themes into a philosophy of freedom in a world without given meaning.","zh":"克尔凯郭尔反抗黑格尔包罗万象的体系，认为其中没有焦虑而必须抉择的个人的位置；尼采宣告“上帝死了”。经历两次世界大战、占领与大屠杀之后，萨特、波伏瓦、加缪等法国作家把这些主题发展成一种在没有既定意义的世界里谈论自由的哲学。"},"reasoning":{"en":"A paper knife is designed before it is made, so its essence comes first. If there is no designer of human nature, Sartre argued, we exist first and define ourselves afterwards by what we do. So we cannot blame nature, God or society for our choices; pretending we have no choice is “bad faith”.","zh":"裁纸刀在被制造之前就已被设计，所以它的本质先于存在。萨特论证说，如果人性没有设计者，那么人先存在，然后才通过自己的行动来界定自己。因此，我们不能把自己的选择归咎于本性、上帝或社会；假装自己别无选择，就是“自欺”。"},"claims":[{"en":"Existence precedes essence.","zh":"存在先于本质。"},{"en":"We are condemned to be free and responsible for what we make of ourselves.","zh":"人注定是自由的，并要为自己成为什么样的人负责。"},{"en":"Anxiety and absurdity are honest responses to a world without given meaning.","zh":"焦虑与荒诞感，是对一个没有既定意义的世界的诚实回应。"}],"legacy":{"en":"It shaped postwar literature, theatre, psychotherapy and feminism, and its vocabulary of authenticity, anxiety and the absurd entered everyday speech.","zh":"它影响了战后的文学、戏剧、心理治疗与女性主义；“本真”“焦虑”“荒诞”等词汇也进入了日常语言。"},"works":[{"by":"kierkegaard","t":{"en":"Fear and Trembling","zh":"《恐惧与战栗》"},"y":1843},{"by":"nietzsche","t":{"en":"Thus Spoke Zarathustra","zh":"《查拉图斯特拉如是说》"},"y":1883},{"by":"sartre","t":{"en":"Being and Nothingness","zh":"《存在与虚无》"},"y":1943},{"by":"camus","t":{"en":"The Myth of Sisyphus","zh":"《西西弗神话》"},"y":1942}],"figures":["kierkegaard","nietzsche","sartre","beauvoir","camus"],"tags":"existence essence freedom anxiety angst absurd authenticity bad faith choice 存在主义 存在 本质 自由 焦虑 荒诞 本真 自欺 选择","wiki":"Existentialism"},
  {"id":"marxism","tradition":"continental","start":1844,"end":2026,"dates":{"en":"1840s – today","zh":"19世纪40年代至今"},"name":{"en":"Marxism","zh":"马克思主义"},"branches":["politics","metaphysics"],"idea":{"en":"History is driven by material production and class struggle, and capitalism, which exploits wage labour, will give way to a classless society.","zh":"历史由物质生产与阶级斗争推动；剥削雇佣劳动的资本主义终将让位于无阶级社会。"},"question":{"en":"Why are the people who produce wealth so poor, and how can that change?","zh":"为什么创造财富的人如此贫穷？这一切如何改变？"},"origin":{"en":"Industrial capitalism in 1840s Britain and Germany produced unprecedented wealth beside slums, child labour and failed revolutions. Young Hegelians such as Marx inherited Hegel’s idea that history unfolds through contradiction, but found his account too abstract to explain real misery.","zh":"19世纪40年代的英国与德国，工业资本主义在制造空前财富的同时，也制造了贫民窟、童工与一次次失败的革命。马克思等青年黑格尔派继承了黑格尔“历史经由矛盾展开”的思想，却认为它太抽象，解释不了现实的苦难。"},"reasoning":{"en":"Humans survive by working on nature, so how a society produces (its tools and property relations) shapes its laws, politics and ideas. Under capitalism workers sell their labour power for less than the value it creates, and the surplus becomes profit. Because this conflict is built into the system, Marx argued, it generates crises and eventually its own overthrow.","zh":"人靠改造自然而生存，所以一个社会如何生产——它的工具与所有制关系——塑造着它的法律、政治与观念。在资本主义下，工人出卖劳动力，得到的报酬少于其创造的价值，差额成为利润。马克思认为，这种冲突内在于制度本身，必然引发危机，最终导致制度被推翻。"},"claims":[{"en":"Material conditions shape consciousness, not the other way round.","zh":"不是意识决定存在，而是社会存在决定意识。"},{"en":"History is the history of class struggles.","zh":"迄今一切社会的历史都是阶级斗争的历史。"},{"en":"Capitalism alienates workers from their labour, its products and each other.","zh":"资本主义使劳动者同自己的劳动、劳动产品以及彼此相异化。"}],"legacy":{"en":"It inspired labour movements, revolutions and twentieth-century socialist states, and remains a core tool in sociology, history and the critique of capitalism.","zh":"它激发了工人运动、革命和20世纪的社会主义国家，至今仍是社会学、历史学与资本主义批判的核心工具。"},"works":[{"by":"marx","t":{"en":"The Communist Manifesto (with Engels)","zh":"《共产党宣言》（与恩格斯合著）"},"y":1848},{"by":"marx","t":{"en":"Capital, Volume I","zh":"《资本论》第一卷"},"y":1867},{"by":"gramsci","t":{"en":"Prison Notebooks","zh":"《狱中札记》"},"y":1935}],"figures":["marx","engels","gramsci"],"tags":"marx class capital labour alienation materialism dialectic revolution hegemony communism 马克思主义 阶级 资本 异化 唯物史观 辩证法 革命 霸权 共产主义","wiki":"Marxism"},
  {"id":"phenomenology","tradition":"continental","start":1900,"end":2026,"dates":{"en":"1900 – today","zh":"1900年至今"},"name":{"en":"Phenomenology","zh":"现象学"},"branches":["epistemology","mind","metaphysics"],"idea":{"en":"Philosophy should begin by describing experience exactly as it is lived, setting aside assumptions about what lies behind it.","zh":"哲学应当从如实描述亲历的经验开始，悬置对经验背后之物的种种预设。"},"question":{"en":"How do things show up for us in experience?","zh":"事物是如何在经验中向我们显现的？"},"origin":{"en":"Around 1900, psychology was claiming logic and knowledge as its own territory, and positivists held that only natural science gives truth. Husserl, trained in mathematics and taught by Franz Brentano, wanted a rigorous science of consciousness itself, under the rallying cry “back to the things themselves”.","zh":"1900年前后，心理学试图把逻辑与知识纳入自己的领地，实证主义者则主张只有自然科学提供真理。受过数学训练、师从布伦塔诺的胡塞尔，想要建立一门研究意识本身的严格科学，并提出口号：“回到事情本身！”"},"reasoning":{"en":"All consciousness is consciousness of something (intentionality), so mind and world are always given together. If we suspend (“bracket”) the question of whether things exist independently, we can describe the structures through which anything appears at all: perception, time, the body, other people. Those structures come before, and underlie, the theories of science.","zh":"一切意识都是关于某物的意识（意向性），因此心灵与世界总是一同被给予的。如果我们把“事物是否独立存在”这个问题悬置起来（“加括号”），就能描述任何东西得以显现的结构：知觉、时间、身体、他人。这些结构先于并支撑着科学的理论。"},"claims":[{"en":"Consciousness is always directed at something.","zh":"意识总是指向某物的意识。"},{"en":"Suspend assumptions and describe what appears.","zh":"悬置预设，描述显现者。"},{"en":"Lived experience comes before scientific abstraction.","zh":"亲历的经验先于科学的抽象。"}],"legacy":{"en":"Through Heidegger, Sartre, Merleau-Ponty and Levinas it became the backbone of continental philosophy, and it still informs cognitive science, nursing and studies of embodiment.","zh":"经由海德格尔、萨特、梅洛-庞蒂与列维纳斯，它成为欧陆哲学的骨架，今天仍影响着认知科学、护理学与具身性研究。"},"works":[{"by":"husserl","t":{"en":"Logical Investigations","zh":"《逻辑研究》"},"y":1900},{"by":"husserl","t":{"en":"Ideas I","zh":"《纯粹现象学通论》（《观念I》）"},"y":1913},{"by":"heidegger","t":{"en":"Being and Time","zh":"《存在与时间》"},"y":1927},{"by":"merleau-ponty","t":{"en":"Phenomenology of Perception","zh":"《知觉现象学》"},"y":1945}],"figures":["husserl","heidegger","merleau-ponty","levinas"],"tags":"husserl intentionality epoche bracketing reduction lived experience embodiment lifeworld 现象学 意向性 悬置 还原 生活世界 具身 胡塞尔","wiki":"Phenomenology (philosophy)"},
  {"id":"structuralism","tradition":"continental","start":1916,"end":1980,"dates":{"en":"1916 – 1970s","zh":"1916年–20世纪70年代"},"name":{"en":"Structuralism","zh":"结构主义"},"branches":["logic","epistemology"],"idea":{"en":"Meaning comes not from things in themselves but from their differences within a system, so culture, like language, can be read as structure.","zh":"意义并非来自事物本身，而是来自它们在一个系统中的差异；因此文化可以像语言一样，被当作结构来解读。"},"question":{"en":"What hidden systems give words, myths and customs their meaning?","zh":"是什么隐藏的系统赋予词语、神话与习俗以意义？"},"origin":{"en":"Saussure’s lectures, published by his students in 1916, studied language as a system at one moment rather than as a history of words. Lévi-Strauss, who learned structural linguistics from Roman Jakobson in wartime New York, applied the method to kinship and myth, and in 1950s–60s Paris it became the main alternative to existentialism’s focus on the free subject.","zh":"索绪尔的讲课内容于1916年由学生整理出版，它把语言当作某一时刻的系统来研究，而不是词语的演变史。二战期间在纽约从雅各布森那里学到结构语言学的列维-斯特劳斯，把这一方法用于亲属关系与神话研究；20世纪五六十年代的巴黎，它成为存在主义那种以自由主体为中心的思想之外的主要选择。"},"reasoning":{"en":"The sign “cat” means what it does not because of any natural link to cats but because it differs from “cap”, “bat” and “dog”. If meaning is relational, then to understand a myth, a menu or a fashion we should map the system of oppositions behind it (raw/cooked, nature/culture), which operates mostly without the awareness of those who use it.","zh":"英语里的“cat”（猫）之所以有意义，并非因为它与猫有天然联系，而是因为它区别于“cap”“bat”“dog”。如果意义是关系性的，那么要理解一个神话、一份菜单或一种时尚，就应描绘出其背后的对立系统（生/熟、自然/文化）；这一系统大多在使用者毫无察觉的情况下运作。"},"claims":[{"en":"The link between signifier and signified is arbitrary.","zh":"能指与所指之间的联系是任意的。"},{"en":"In language there are only differences.","zh":"语言中只有差异。"},{"en":"Deep structures, not individual intentions, organise culture.","zh":"组织文化的是深层结构，而非个人意图。"}],"legacy":{"en":"It founded semiotics and transformed anthropology, literary criticism and psychoanalysis, and its critics became the post-structuralists.","zh":"它奠定了符号学，改造了人类学、文学批评与精神分析；它的批评者后来成为后结构主义者。"},"works":[{"by":"saussure","t":{"en":"Course in General Linguistics","zh":"《普通语言学教程》"},"y":1916},{"by":"levi-strauss","t":{"en":"The Elementary Structures of Kinship","zh":"《亲属关系的基本结构》"},"y":1949},{"by":"barthes","t":{"en":"Mythologies","zh":"《神话学》"},"y":1957},{"by":"levi-strauss","t":{"en":"The Savage Mind","zh":"《野性的思维》"},"y":1962}],"figures":["saussure","levi-strauss","barthes"],"tags":"saussure sign signifier signified langue parole structure myth semiotics binary opposition kinship 结构主义 符号 能指 所指 语言 结构 神话 符号学 二元对立 亲属","wiki":"Structuralism"},
  {"id":"critical-theory","tradition":"continental","start":1923,"end":2026,"dates":{"en":"1923 – today","zh":"1923年至今"},"name":{"en":"Critical theory (Frankfurt School)","zh":"批判理论（法兰克福学派）"},"branches":["politics","epistemology"],"idea":{"en":"Social theory should not just describe society but expose the forms of domination it hides, with a view to human emancipation.","zh":"社会理论不应只描述社会，还应揭示其中隐藏的支配形式，以人的解放为目标。"},"question":{"en":"Why did reason and progress produce new forms of domination?","zh":"为什么理性与进步反而带来了新的支配形式？"},"origin":{"en":"The Institute for Social Research was founded in Frankfurt in 1923, and its thinkers soon asked why the socialist revolution Marx predicted had not come in the West. Mostly Jewish, they watched workers turn to fascism and fled Nazi Germany; in American exile they confronted mass culture and advertising.","zh":"社会研究所于1923年在法兰克福成立，其成员很快追问：马克思预言的社会主义革命为何没有在西方到来？他们多为犹太人，目睹工人转向法西斯主义，随后逃离纳粹德国；流亡美国期间，又直面大众文化与广告。"},"reasoning":{"en":"Horkheimer distinguished “traditional” theory, which treats society as a given object, from “critical” theory, which asks whose interests the existing order serves. Horkheimer and Adorno argued that Enlightenment reason, reduced to a tool for controlling nature and people, can turn into its opposite. Habermas later found a counterweight in communication: norms are legitimate only if all affected could agree to them in free discussion.","zh":"霍克海默区分了“传统理论”与“批判理论”：前者把社会当作既定对象来研究，后者追问现存秩序服务于谁的利益。霍克海默与阿多诺认为，启蒙理性一旦沦为控制自然与人的工具，就可能走向自身的反面。哈贝马斯后来在交往中找到了制衡：只有所有相关者在自由讨论中都能同意的规范，才是正当的。"},"claims":[{"en":"Theory should serve emancipation, not just description.","zh":"理论应服务于解放，而不只是描述。"},{"en":"Instrumental reason can turn enlightenment into new domination.","zh":"工具理性可能使启蒙沦为新的支配。"},{"en":"The culture industry manufactures conformity.","zh":"文化工业制造顺从。"}],"legacy":{"en":"It shaped the New Left, media and cultural studies, and theories of democracy built on public discussion.","zh":"它影响了新左派、媒介与文化研究，以及以公共讨论为基础的民主理论。"},"works":[{"by":"horkheimer","t":{"en":"Dialectic of Enlightenment (with Adorno)","zh":"《启蒙辩证法》（与阿多诺合著）"},"y":1947},{"by":"marcuse","t":{"en":"One-Dimensional Man","zh":"《单向度的人》"},"y":1964},{"by":"adorno","t":{"en":"Negative Dialectics","zh":"《否定的辩证法》"},"y":1966},{"by":"habermas","t":{"en":"The Theory of Communicative Action","zh":"《交往行为理论》"},"y":1981}],"figures":["horkheimer","adorno","benjamin","marcuse","habermas"],"tags":"frankfurt school critical theory culture industry instrumental reason emancipation public sphere communicative action 法兰克福学派 批判理论 文化工业 工具理性 解放 公共领域 交往行为","wiki":"Frankfurt School"},
  {"id":"postcolonial","tradition":"continental","start":1952,"end":2026,"dates":{"en":"1950s – today","zh":"20世纪50年代至今"},"name":{"en":"Postcolonial thought","zh":"后殖民思想"},"branches":["politics","epistemology"],"idea":{"en":"Colonialism ruled minds as well as lands, so liberation requires undoing the categories through which the West described and governed others.","zh":"殖民主义不只统治土地，也统治心灵；因此解放需要拆解西方用来描述并统治他者的那些范畴。"},"question":{"en":"How did empire shape the way we know and see others?","zh":"帝国如何塑造了我们认识与看待他者的方式？"},"origin":{"en":"After 1945, struggles for independence swept Asia and Africa. Fanon, a psychiatrist from Martinique working in Algeria during its war against France, analysed racism and colonial violence from the inside; later Said and Spivak, teaching in American universities, turned literary and philosophical theory on the archive of empire.","zh":"1945年后，独立运动席卷亚洲与非洲。来自马提尼克的精神科医生法农在阿尔及利亚抗法战争期间工作，从内部剖析了种族主义与殖民暴力；后来，任教于美国大学的萨义德与斯皮瓦克，把文学与哲学理论用于审视帝国的档案。"},"reasoning":{"en":"Colonial rule depended on knowledge: maps, grammars, censuses and novels that described the colonised as backward, timeless or silent. If that knowledge was a form of power, independence alone would not end it; it survives in self-images, school curricula and Western scholarship, and must be dismantled by critique.","zh":"殖民统治依赖知识：地图、语法书、人口普查与小说，把被殖民者描绘成落后、停滞或沉默的人。如果这些知识本身就是一种权力，那么仅有政治独立并不能终结它；它延续在人们的自我形象、学校课程与西方学术之中，必须通过批判来拆解。"},"claims":[{"en":"Colonialism dehumanises both colonised and coloniser.","zh":"殖民主义使被殖民者与殖民者双双丧失人性。"},{"en":"“The Orient” is a Western construction serving power.","zh":"“东方”是服务于权力的西方建构。"},{"en":"The subaltern is spoken for, rarely heard.","zh":"底层人总被代言，却很少被倾听。"}],"legacy":{"en":"It transformed literary studies, history and anthropology, and feeds today’s debates on decolonising universities, museums and philosophy itself.","zh":"它改变了文学研究、历史学与人类学，也为今天关于大学、博物馆乃至哲学本身“去殖民化”的讨论提供了养分。"},"works":[{"by":"fanon","t":{"en":"Black Skin, White Masks","zh":"《黑皮肤，白面具》"},"y":1952},{"by":"fanon","t":{"en":"The Wretched of the Earth","zh":"《全世界受苦的人》"},"y":1961},{"by":"said","t":{"en":"Orientalism","zh":"《东方学》"},"y":1978},{"by":"spivak","t":{"en":"Can the Subaltern Speak?","zh":"《底层人能说话吗？》"},"y":1988}],"figures":["fanon","said","spivak"],"tags":"postcolonial colonialism orientalism subaltern decolonisation race empire 后殖民 殖民主义 东方学 底层 去殖民化 种族 帝国","wiki":"Postcolonialism"},
  {"id":"poststructuralism","tradition":"continental","start":1966,"end":2026,"dates":{"en":"1966 – today","zh":"1966年至今"},"name":{"en":"Post-structuralism","zh":"后结构主义"},"branches":["logic","politics","epistemology"],"idea":{"en":"Structures of meaning and knowledge are never closed or neutral: they shift, exclude and exercise power, so no foundation escapes critique.","zh":"意义与知识的结构从不封闭、也从不中立：它们不断滑动、有所排斥并施行权力，因此没有任何根基能免于批判。"},"question":{"en":"Can any system of meaning or knowledge be stable, neutral or final?","zh":"任何意义或知识的系统能够稳定、中立或终极吗？"},"origin":{"en":"By the mid-1960s structuralism dominated Paris, and its promise of a science of culture met the upheavals of decolonisation and May 1968. Thinkers trained in it, and in Nietzsche, Heidegger and Freud, began asking what structuralism itself assumed: a fixed centre, a neutral observer, an order outside history.","zh":"到20世纪60年代中期，结构主义主导了巴黎思想界，它所许诺的“文化科学”又遭遇了去殖民化与1968年“五月风暴”的冲击。受过结构主义以及尼采、海德格尔、弗洛伊德熏陶的思想家开始追问：结构主义自身预设了什么——一个固定的中心、一个中立的观察者、一种外在于历史的秩序？"},"reasoning":{"en":"If meaning arises from differences, it is never fully present in any sign but always deferred to other signs (Derrida’s différance), so texts undo their own oppositions. Foucault argued that what counts as knowledge, madness or normality is produced by historical practices bound up with power. The task, then, is not to find the true foundation but to show how apparent necessities were made and could be otherwise.","zh":"如果意义来自差异，那么它就从不完整地在场于任何一个符号中，而是不断被推延到其他符号（德里达的“延异”），因此文本会瓦解自身的二元对立。福柯则论证，什么算作知识、疯癫或正常，是由与权力纠缠在一起的历史实践所生产的。所以，哲学的任务不是寻找真正的根基，而是揭示那些看似必然的东西是如何被造就的，又如何可能是另一种样子。"},"claims":[{"en":"Meaning is always deferred and never fully present.","zh":"意义总是被推延，从不完全在场。"},{"en":"Knowledge and power produce each other.","zh":"知识与权力相互生产。"},{"en":"Grand narratives of progress deserve incredulity.","zh":"对进步的宏大叙事应当保持怀疑。"}],"legacy":{"en":"It reshaped literary studies, gender and queer theory, postcolonial studies and the history of science, and remains a lightning rod in debates about truth and relativism.","zh":"它重塑了文学研究、性别与酷儿理论、后殖民研究与科学史，至今仍是真理与相对主义之争的焦点。"},"works":[{"by":"derrida","t":{"en":"Of Grammatology","zh":"《论文字学》"},"y":1967},{"by":"deleuze","t":{"en":"Anti-Oedipus (with Félix Guattari)","zh":"《反俄狄浦斯》（与加塔利合著）"},"y":1972},{"by":"foucault","t":{"en":"Discipline and Punish","zh":"《规训与惩罚》"},"y":1975},{"by":"lyotard","t":{"en":"The Postmodern Condition","zh":"《后现代状况》"},"y":1979}],"figures":["foucault","derrida","deleuze","lyotard"],"tags":"deconstruction différance difference genealogy discourse power knowledge postmodern rhizome 后结构主义 解构 延异 差异 谱系学 话语 权力 知识 后现代 块茎","wiki":"Post-structuralism"},
  {"id":"pragmatism","tradition":"analytic","start":1870,"end":2026,"dates":{"en":"1870s – today","zh":"19世纪70年代至今"},"name":{"en":"Pragmatism","zh":"实用主义"},"branches":["epistemology","metaphysics","ethics"],"idea":{"en":"The meaning and truth of an idea lie in its practical consequences: ideas are tools for coping with experience, tested by how they work.","zh":"一个观念的意义与真理在于它的实际效果：观念是应对经验的工具，要看它在实践中是否行得通。"},"question":{"en":"What difference does it make if an idea is true?","zh":"一个观念是真是假，究竟有什么实际差别？"},"origin":{"en":"In the years after the American Civil War and Darwin’s Origin of Species, a circle in Cambridge, Massachusetts (the “Metaphysical Club” of the early 1870s) looked for a philosophy fit for a world of change, science and democratic experiment. They distrusted both Descartes’s quest for certainty and the grand metaphysical systems of the past.","zh":"美国内战与达尔文《物种起源》之后，马萨诸塞州剑桥的一群人（19世纪70年代初的“形而上学俱乐部”）想要一种适合变化、科学与民主实验时代的哲学。他们既不信任笛卡尔式对绝对确定性的追求，也不信任过去那些宏大的形而上学体系。"},"reasoning":{"en":"If two ideas would make no difference to any possible experience or action, they do not really differ in meaning. A belief is a habit of action: inquiry starts from real doubt and ends when a belief holds up in practice. So truth is not a static copy of reality but what inquiry would settle on, or what proves itself in use.","zh":"如果两个观念对任何可能的经验或行动都不造成差别，那么它们的意义其实并无不同。信念是一种行动习惯：探究始于真实的怀疑，终于一个在实践中站得住的信念。因此，真理不是对实在的静态摹写，而是探究最终会达成的结论，或在使用中证明自己的东西。"},"claims":[{"en":"Meaning lies in an idea’s conceivable practical effects.","zh":"观念的意义在于它可设想的实际效果。"},{"en":"All knowledge is fallible and open to revision.","zh":"一切知识都可能出错，都可以修正。"},{"en":"Inquiry and democracy are shared, experimental practices.","zh":"探究与民主都是共同参与的实验性实践。"}],"legacy":{"en":"Through Dewey it reshaped American education, law and social science; it returned as “neopragmatism” with Rorty and Putnam, and through Hu Shi entered Chinese debates of the May Fourth era.","zh":"经由杜威，它重塑了美国的教育、法学与社会科学；后来又以罗蒂、普特南的“新实用主义”回归，并经由胡适进入五四时期的中国思想论争。"},"works":[{"by":"peirce","t":{"en":"How to Make Our Ideas Clear","zh":"《如何使我们的观念清晰》"},"y":1878},{"by":"james","t":{"en":"Pragmatism","zh":"《实用主义》"},"y":1907},{"by":"dewey","t":{"en":"Democracy and Education","zh":"《民主与教育》"},"y":1916},{"by":"rorty","t":{"en":"Philosophy and the Mirror of Nature","zh":"《哲学和自然之镜》"},"y":1979}],"figures":["peirce","james","dewey","rorty","hu-shi"],"tags":"pragmatism pragmatic maxim truth inquiry fallibilism experience democracy metaphysical club neopragmatism 实用主义 实效 探究 可错论 经验 民主 新实用主义","wiki":"Pragmatism"},
  {"id":"early-analytic","tradition":"analytic","start":1879,"end":1930,"dates":{"en":"1879 – c. 1930","zh":"1879年–约1930年"},"name":{"en":"Early analytic philosophy","zh":"早期分析哲学"},"branches":["logic","metaphysics","epistemology"],"idea":{"en":"Many philosophical problems come from the misleading surface of language, and can be solved by analysing statements into their true logical form.","zh":"许多哲学问题源于语言表面的误导，只要把命题分析成它真正的逻辑形式，就能加以解决。"},"question":{"en":"What is the logical structure of thought, language and the world?","zh":"思想、语言与世界的逻辑结构是什么？"},"origin":{"en":"Frege’s new logic of 1879 set out to show that arithmetic rests on logic alone, giving philosophy a tool far sharper than Aristotle’s syllogisms. From 1898 in Cambridge, Russell and Moore broke with the Hegel-inspired British idealism they had been taught, and turned to logic and common sense instead.","zh":"弗雷格1879年创立的新逻辑，意在证明算术完全建立在逻辑之上，给了哲学一件比亚里士多德三段论锋利得多的工具。1898年起，罗素与摩尔在剑桥与他们所受教育中的、受黑格尔影响的英国唯心论决裂，转向逻辑与常识。"},"reasoning":{"en":"Grammar can hide logical form: “The present king of France is bald” looks as if it names someone, but analysis shows it asserts that exactly one such king exists, so it is simply false. If philosophy clarifies what our sentences really say, puzzles about existence, meaning and truth can be answered precisely or dissolved. Logic thus becomes the method of philosophy.","zh":"语法会掩盖逻辑形式：“当今的法国国王是秃头”看似在指称某个人，分析后却发现它断言“恰好存在一位这样的国王”，因此这句话只是假的。只要哲学弄清句子真正说了什么，关于存在、意义与真理的难题就能被精确回答或被消解。于是，逻辑成了哲学的方法。"},"claims":[{"en":"Modern logic is the essential tool of philosophy.","zh":"现代逻辑是哲学最根本的工具。"},{"en":"Grammatical form can mislead us about logical form.","zh":"语法形式会让人误解逻辑形式。"},{"en":"Analysis breaks complex propositions into simpler ones.","zh":"分析就是把复杂命题拆解为更简单的命题。"}],"legacy":{"en":"It founded the analytic tradition that dominates English-language philosophy, and its formal logic fed directly into the theory of computation.","zh":"它开创了在英语世界占主导地位的分析哲学传统，其形式逻辑也直接哺育了计算理论。"},"works":[{"by":"frege","t":{"en":"Begriffsschrift","zh":"《概念文字》"},"y":1879},{"by":"russell","t":{"en":"On Denoting","zh":"《论指称》"},"y":1905},{"by":"russell","t":{"en":"Principia Mathematica (with A. N. Whitehead)","zh":"《数学原理》（与怀特海合著）"},"y":1910},{"by":"wittgenstein","t":{"en":"Tractatus Logico-Philosophicus","zh":"《逻辑哲学论》"},"y":1921}],"figures":["frege","russell","moore","wittgenstein"],"tags":"analytic philosophy logic logicism analysis definite descriptions logical atomism common sense 分析哲学 逻辑 逻辑主义 分析 摹状词 逻辑原子主义 常识","wiki":"Analytic philosophy"},
  {"id":"logical-positivism","tradition":"analytic","start":1924,"end":1960,"dates":{"en":"1920s – 1950s","zh":"20世纪20–50年代"},"name":{"en":"Logical positivism (Vienna Circle)","zh":"逻辑实证主义（维也纳学派）"},"branches":["epistemology","logic","metaphysics"],"idea":{"en":"A statement means something only if experience could verify it or logic alone makes it true; traditional metaphysics is therefore literally meaningless.","zh":"一个陈述只有能被经验证实、或仅凭逻辑即为真，才有意义；因此传统形而上学在字面上就是无意义的。"},"question":{"en":"Which statements actually say something about the world?","zh":"哪些陈述真正说出了关于世界的东西？"},"origin":{"en":"In 1920s Vienna, scientists and philosophers gathered around Moritz Schlick, impressed by Einstein’s relativity and by the new logic of Frege, Russell and the Tractatus. They wanted a “scientific world-conception” and saw speculative metaphysics as an obstacle to clear thinking and social progress.","zh":"20世纪20年代的维也纳，一批科学家与哲学家聚集在石里克周围。他们深受爱因斯坦相对论以及弗雷格、罗素和《逻辑哲学论》的新逻辑触动，想要建立一种“科学的世界观”，并把思辨的形而上学视为清晰思考与社会进步的障碍。"},"reasoning":{"en":"Logic and mathematics are true by the meanings of their symbols and say nothing about the world. Every other meaningful claim must, at least in principle, be checkable by observation. Sentences that are neither, such as “the Absolute is beyond time”, express attitudes or feelings, not facts.","zh":"逻辑与数学凭借符号的意义而为真，并不陈述世界的任何情况。其余一切有意义的断言，至少在原则上必须能用观察来检验。两者都不是的句子，例如“绝对者超越时间”，表达的只是态度或情感，而不是事实。"},"claims":[{"en":"The meaning of a statement is its method of verification.","zh":"一个陈述的意义就是它的证实方法。"},{"en":"Logic and mathematics are analytic, not factual.","zh":"逻辑与数学是分析的，不陈述事实。"},{"en":"Philosophy’s task is to clarify the language of science.","zh":"哲学的任务是澄清科学的语言。"}],"legacy":{"en":"The verification principle collapsed under criticism, not least because it fails its own test, but the movement set the agenda of philosophy of science; when Nazism forced its members into exile, they carried it to Britain and America.","zh":"证实原则在批评中崩溃了——它本身就通不过自己的检验——但这一运动为科学哲学设定了议程；纳粹迫使其成员流亡后，他们把它带到了英国和美国。"},"works":[{"by":"carnap","t":{"en":"The Logical Structure of the World (Der logische Aufbau der Welt)","zh":"《世界的逻辑构造》"},"y":1928},{"by":"carnap","t":{"en":"The Logical Syntax of Language","zh":"《语言的逻辑句法》"},"y":1934},{"by":"ayer","t":{"en":"Language, Truth and Logic","zh":"《语言、真理与逻辑》"},"y":1936}],"figures":["schlick","carnap","ayer"],"tags":"logical positivism logical empiricism vienna circle verification principle verificationism meaningless metaphysics analytic synthetic 逻辑实证主义 逻辑经验主义 维也纳学派 证实原则 拒斥形而上学","wiki":"Logical positivism"},
  {"id":"post-positivism","tradition":"analytic","start":1934,"end":2026,"dates":{"en":"1934 – today","zh":"1934年至今"},"name":{"en":"Post-positivist philosophy of science","zh":"后实证主义科学哲学"},"branches":["epistemology","logic","metaphysics"],"idea":{"en":"Science does not grow by piling up verified facts: theories are tested as wholes, can be refuted but never finally proven, and change through historical upheavals.","zh":"科学并不是靠堆积已证实的事实而成长的：理论作为整体接受检验，可以被证伪却永远无法被最终证明，并在历史的剧变中更替。"},"question":{"en":"How does science actually gain knowledge?","zh":"科学究竟是怎样获得知识的？"},"origin":{"en":"The logical positivists hoped to ground science on verification, but no finite set of observations can verify a universal law, and the line between “observational” and “theoretical” kept blurring. Between the 1930s and the 1960s, Popper, Quine and Kuhn dismantled that picture from three different directions.","zh":"逻辑实证主义者希望以“证实”为科学奠基，但有限的观察永远无法证实一条普遍定律，“观察”与“理论”的界线也越来越模糊。从20世纪30年代到60年代，波普尔、蒯因和库恩从三个不同方向拆解了这幅图景。"},"reasoning":{"en":"Popper: no number of white swans proves “all swans are white”, but one black swan refutes it, so science advances by bold conjectures and attempted refutations. Quine: a test never confronts a single sentence, only a whole web of belief, so even logic is in principle revisable. Kuhn: “normal science” works inside a paradigm until anomalies pile up and a revolution replaces it.","zh":"波普尔：再多的白天鹅也证明不了“所有天鹅都是白的”，一只黑天鹅却能推翻它，所以科学靠大胆猜想与尝试反驳前进。蒯因：接受检验的从来不是单个句子，而是整张信念之网，因此连逻辑原则上也可修正。库恩：“常规科学”在一个范式内运作，直到反常积累，一场革命以新范式取而代之。"},"claims":[{"en":"Falsifiability, not verifiability, marks a scientific theory.","zh":"科学理论的标志是可证伪性，而非可证实性。"},{"en":"Beliefs face experience as a whole web, not one by one.","zh":"信念作为一整张网面对经验，而非逐条接受检验。"},{"en":"Science changes through paradigm shifts, not only accumulation.","zh":"科学通过范式转换而变化，不只是线性积累。"}],"legacy":{"en":"It made the history and sociology of science central to philosophy of science, and put “falsifiable” and “paradigm shift” into everyday language.","zh":"它让科学史与科学社会学成为科学哲学的核心，也让“可证伪”“范式转换”成了日常用语。"},"works":[{"by":"popper","t":{"en":"The Logic of Scientific Discovery (Logik der Forschung)","zh":"《科学发现的逻辑》"},"y":1934},{"by":"quine","t":{"en":"Two Dogmas of Empiricism","zh":"《经验论的两个教条》"},"y":1951},{"by":"kuhn","t":{"en":"The Structure of Scientific Revolutions","zh":"《科学革命的结构》"},"y":1962}],"figures":["popper","quine","kuhn"],"tags":"philosophy of science falsification falsifiability critical rationalism holism web of belief paradigm shift scientific revolution naturalism 科学哲学 证伪 可证伪性 批判理性主义 整体论 信念之网 范式 科学革命 自然主义","wiki":"Postpositivism"},
  {"id":"ordinary-language","tradition":"analytic","start":1945,"end":1970,"dates":{"en":"c. 1945 – 1970","zh":"约1945–1970年"},"name":{"en":"Ordinary language philosophy","zh":"日常语言哲学"},"branches":["logic","mind","epistemology"],"idea":{"en":"Philosophical puzzles arise when words are taken out of their everyday use; looking closely at how language is actually used dissolves them.","zh":"当词语脱离日常用法时，哲学难题便产生了；仔细考察语言实际上如何被使用，就能消解这些难题。"},"question":{"en":"What do our words mean in the way we actually use them?","zh":"我们的词语在实际使用中究竟意味着什么？"},"origin":{"en":"Wittgenstein, back in Cambridge from 1929, came to reject the picture of language in his own Tractatus. After 1945, Oxford philosophers such as Gilbert Ryle and J. L. Austin, equally wary of ideal logical languages, turned to the fine grain of everyday speech.","zh":"1929年回到剑桥的维特根斯坦，逐渐否定了自己《逻辑哲学论》中的语言图像。1945年后，赖尔、奥斯汀等牛津哲学家同样不信任理想化的逻辑语言，转而细究日常言语的纹理。"},"reasoning":{"en":"The meaning of a word is its use within a practice (a “language-game”), not an object it stands for. Philosophers create problems, such as whether the mind is a ghostly thing inside the body, by stretching words beyond the contexts that give them sense. Map the actual uses, and the problem often disappears.","zh":"一个词的意义在于它在某种实践（“语言游戏”）中的用法，而不是它所代表的某个对象。哲学家把词语拉出赋予其意义的语境，于是制造出问题，比如“心灵是否是身体里一个幽灵般的东西”。把实际用法梳理清楚，问题往往就消失了。"},"claims":[{"en":"The meaning of a word is its use in a form of life.","zh":"词的意义在于它在生活形式中的用法。"},{"en":"Many philosophical problems are confusions of language.","zh":"许多哲学问题源于语言的混乱。"},{"en":"Speaking is doing: utterances are actions.","zh":"说话就是做事：言语本身就是行动。"}],"legacy":{"en":"It gave us speech-act theory, developed by Austin and then Searle, shaped linguistic pragmatics, and left philosophy with a lasting habit of attending carefully to usage.","zh":"它催生了由奥斯汀开创、塞尔发展的言语行为理论，影响了语言学中的语用学，也让哲学养成了细察用法的持久习惯。"},"works":[{"by":"ryle","t":{"en":"The Concept of Mind","zh":"《心的概念》"},"y":1949},{"by":"wittgenstein","t":{"en":"Philosophical Investigations","zh":"《哲学研究》"},"y":1953},{"by":"austin","t":{"en":"How to Do Things with Words","zh":"《如何以言行事》"},"y":1962}],"figures":["wittgenstein","ryle","austin"],"tags":"ordinary language oxford philosophy language-game meaning is use speech acts performative category mistake 日常语言哲学 牛津学派 语言游戏 意义即用法 言语行为 施行话语 范畴错误","wiki":"Ordinary language philosophy"},
  {"id":"philosophy-of-mind","tradition":"analytic","start":1950,"end":2026,"dates":{"en":"1950s – today","zh":"20世纪50年代至今"},"name":{"en":"Analytic philosophy of mind","zh":"分析心灵哲学"},"branches":["mind","metaphysics"],"idea":{"en":"The mind is studied as part of nature: mental states are explained by what brains do, while consciousness remains the hardest test of that picture.","zh":"把心灵当作自然的一部分来研究：心理状态由大脑的活动来解释，而意识始终是对这一图景最严峻的考验。"},"question":{"en":"How can a physical brain have thoughts and feelings?","zh":"一个物理的大脑怎么会有思想和感受？"},"origin":{"en":"Behaviourism and Ryle’s attack on the “ghost in the machine” left Cartesian dualism unfashionable, while computers and neuroscience suggested the mind might be explained physically. From the 1950s, philosophers asked what kind of physical explanation could actually work.","zh":"行为主义和赖尔对“机器中的幽灵”的抨击让笛卡尔式二元论失势，而计算机与神经科学则暗示心灵或许可以得到物理的解释。从20世纪50年代起，哲学家开始追问：什么样的物理解释才真正行得通？"},"reasoning":{"en":"Functionalism (Putnam) holds that a mental state is defined by its causal role, not its material, so the same mind could in principle run on neurons or silicon. Critics answer that something is left out: Searle’s Chinese Room says symbol manipulation is not understanding, and Nagel and Chalmers argue that the felt quality of experience, “what it is like”, resists functional explanation. Dennett replies that this “hard problem” is an illusion produced by our intuitions.","zh":"功能主义（普特南）认为，心理状态由其因果角色而非构成材料来界定，所以同一个心灵原则上既可以在神经元上、也可以在硅片上运行。批评者回应说有东西被遗漏了：塞尔的“中文屋”表明，操纵符号不等于理解；内格尔与查默斯则主张，经验的感受性质——“是什么样子”——无法用功能来解释。丹尼特反驳说，这个“难问题”只是直觉制造的幻觉。"},"claims":[{"en":"Mental states are defined by their functional roles.","zh":"心理状态由其功能角色来界定。"},{"en":"Manipulating symbols is not the same as understanding them.","zh":"操纵符号并不等于理解符号。"},{"en":"Explaining subjective experience is the “hard problem”.","zh":"解释主观经验是意识的“难问题”。"}],"legacy":{"en":"It laid the conceptual foundations of cognitive science and frames today’s arguments about whether AI systems can think or feel.","zh":"它为认知科学奠定了概念基础，也构成了今天关于人工智能能否思考或感受的争论框架。"},"works":[{"by":"putnam","t":{"en":"Psychological Predicates","zh":"《心理谓词》"},"y":1967},{"by":"nagel","t":{"en":"What Is It Like to Be a Bat?","zh":"《成为一只蝙蝠可能是什么样子？》"},"y":1974},{"by":"searle","t":{"en":"Minds, Brains, and Programs","zh":"《心灵、大脑与程序》"},"y":1980},{"by":"chalmers","t":{"en":"The Conscious Mind","zh":"《有意识的心灵》"},"y":1996}],"figures":["putnam","searle","nagel","dennett","chalmers"],"tags":"philosophy of mind functionalism physicalism chinese room hard problem consciousness qualia artificial intelligence mind-body problem 心灵哲学 功能主义 物理主义 中文屋 难问题 意识 感受质 人工智能 心身问题","wiki":"Philosophy of mind"},
  {"id":"virtue-ethics","tradition":"analytic","start":1958,"end":2026,"dates":{"en":"1958 – today","zh":"1958年至今"},"name":{"en":"Virtue ethics revival","zh":"美德伦理学的复兴"},"branches":["ethics"],"idea":{"en":"Ethics should ask what kind of person to be and what makes a human life go well, not only which rules or consequences make acts right.","zh":"伦理学应当追问做一个什么样的人、什么让人生过得好，而不只是追问哪些规则或后果使行为正确。"},"question":{"en":"What kind of person should I be?","zh":"我应该成为什么样的人？"},"origin":{"en":"In 1958 Elizabeth Anscombe argued that modern moral philosophy, both Kantian duty and consequentialism, relied on a notion of moral “obligation” left over from a divine-law ethics it no longer believed in. She urged a return to Aristotle’s questions about virtue and human flourishing, and Philippa Foot and Alasdair MacIntyre took up the call.","zh":"1958年，安斯康姆指出，现代道德哲学——无论康德式的义务论还是后果主义——所依赖的道德“义务”概念，是一种它自己已不再相信的神圣律法伦理的残留。她呼吁回到亚里士多德关于美德与人的繁荣的问题，富特与麦金太尔随后响应。"},"reasoning":{"en":"Virtues such as courage, justice and honesty are traits a human being needs in order to flourish, much as a wolf needs to hunt with its pack. A right action is what a virtuous person would characteristically do in the situation. Because virtues are learned within practices and communities, ethics cannot be separated from character, emotion and tradition.","zh":"勇敢、正义、诚实等美德，是人要活得好所需要的品质，正如狼需要与狼群一同狩猎。正确的行为，就是一个有德之人在该情境中通常会做的事。既然美德是在实践与共同体中习得的，伦理就不能与品格、情感和传统分开。"},"claims":[{"en":"Character, not rules, is the centre of ethics.","zh":"伦理的中心是品格，而不是规则。"},{"en":"Virtues are the traits humans need to flourish.","zh":"美德是人实现繁荣所需的品质。"},{"en":"Moral reasoning lives within practices and traditions.","zh":"道德推理存在于实践与传统之中。"}],"legacy":{"en":"It became one of the three main approaches in normative ethics, alongside consequentialism and deontology, and shapes medical, business and professional ethics.","zh":"它与后果主义、义务论并列，成为规范伦理学的三大进路之一，并影响着医学、商业与职业伦理。"},"works":[{"by":"anscombe","t":{"en":"Modern Moral Philosophy","zh":"《现代道德哲学》"},"y":1958},{"by":"macintyre","t":{"en":"After Virtue","zh":"《追寻美德》"},"y":1981},{"by":"foot","t":{"en":"Natural Goodness","zh":"《自然的善》"},"y":2001}],"figures":["anscombe","foot","macintyre"],"tags":"virtue ethics character flourishing eudaimonia aristotle practice tradition neo-aristotelian 美德伦理学 德性伦理学 品格 繁荣 幸福 亚里士多德 实践 传统 新亚里士多德主义","wiki":"Virtue ethics"},
  {"id":"liberal-egalitarianism","tradition":"analytic","start":1971,"end":2026,"dates":{"en":"1971 – today","zh":"1971年至今"},"name":{"en":"Liberal theories of justice (Rawls and after)","zh":"罗尔斯以来的自由主义正义理论"},"branches":["politics","ethics"],"idea":{"en":"A just society is one whose basic institutions free and equal people could agree to: protecting basic liberties, and allowing inequalities only when they benefit the worst-off.","zh":"正义的社会，是自由而平等的人都能同意其基本制度的社会：保障基本自由，并且只允许那些有利于最不利者的不平等。"},"question":{"en":"What principles should govern a fair society?","zh":"一个公平的社会应当遵循什么原则？"},"origin":{"en":"By the 1960s utilitarianism dominated Anglo-American moral and political thought, while the civil-rights movement and arguments over the welfare state made justice an urgent question. Rawls revived the social-contract tradition to show what utilitarianism missed: that each person’s life is separate and cannot simply be traded off for a larger total.","zh":"到20世纪60年代，功利主义主导着英美的道德与政治思想，而民权运动和关于福利国家的争论让正义问题变得迫切。罗尔斯复兴社会契约传统，以指出功利主义遗漏了什么：每个人的生命都是分立的，不能为了更大的总量而被随意交换。"},"reasoning":{"en":"Imagine choosing the rules of society behind a “veil of ignorance”, not knowing your class, talents, race or idea of the good life. Rational people would secure equal basic liberties and accept inequalities only if they help the least advantaged (the “difference principle”). Nozick objected that any such pattern violates people’s rights to what they freely acquire; Nussbaum, with Amartya Sen, asked instead what people are actually able to do and to be.","zh":"设想在“无知之幕”后选择社会规则：你不知道自己的阶层、天赋、种族或对美好生活的看法。理性的人会确保平等的基本自由，并且只接受有利于最不利者的不平等（“差别原则”）。诺齐克反驳说，任何此类分配模式都侵犯了人们对自由取得之物的权利；努斯鲍姆则与阿马蒂亚·森一起追问：人们实际上能够做什么、成为什么。"},"claims":[{"en":"Justice is the first virtue of social institutions.","zh":"正义是社会制度的首要美德。"},{"en":"Fair principles are those chosen behind a veil of ignorance.","zh":"公平的原则是在无知之幕后选出的原则。"},{"en":"Rights and capabilities matter, not just total welfare.","zh":"重要的是权利与能力，而不只是福利总量。"}],"legacy":{"en":"It revived political philosophy as a field and supplied the vocabulary of today’s debates on welfare, rights and global justice; the capabilities approach influenced the UN’s Human Development Index.","zh":"它让政治哲学重新成为一门显学，为今天关于福利、权利与全球正义的辩论提供了基本词汇；能力进路还影响了联合国的人类发展指数。"},"works":[{"by":"rawls","t":{"en":"A Theory of Justice","zh":"《正义论》"},"y":1971},{"by":"nozick","t":{"en":"Anarchy, State, and Utopia","zh":"《无政府、国家和乌托邦》"},"y":1974},{"by":"nussbaum","t":{"en":"Creating Capabilities","zh":"《寻求有尊严的生活：正义的能力理论》"},"y":2011}],"figures":["rawls","nozick","nussbaum"],"tags":"justice as fairness veil of ignorance original position difference principle libertarianism capabilities approach liberalism 正义论 公平正义 无知之幕 原初状态 差别原则 自由至上主义 能力进路 自由主义","wiki":"A Theory of Justice"}
];
